QT_ISI(9,{"1042":["(Pemuka-pemuka dari kaum Syuaib yang menyombongkan diri berkata,) mereka yang sombong tidak mau beriman (\"Sesungguhnya kami akan mengusir kamu hai Syuaib dan orang-orang yang beriman bersamamu dari kota kami atau kamu kembali) sungguh mau kembali (kepada agama kami.\") yaitu din/agama kami. Di dalam pembicaraan ini yang dipakai dhamir jamak padahal pembicaranya hanya seorang yaitu Syuaib sendiri. Sebab Syuaib itu sama sekali bukan berada dalam agama mereka, lalu ia menjawab sebaliknya (Syuaib menjawab, \"Apakah) kami harus kembali kepada agamamu itu (kendatipun kami tidak menyukainya?\") Istifham/kata tanya di sini mengandung pengertian pengingkaran.",[["۞ قَالَ","Berkata"],["ٱلْمَلَأُ","ketua-ketua"],["ٱلَّذِينَ","orang yang"],["ٱسْتَكْبَرُوا۟","adalah sombong"],["مِن","antara"],["قَوْمِهِۦ","umatnya"],["لَنُخْرِجَنَّكَ","Kami pasti akan menghalau kamu"],["يَـٰشُعَيْبُ","Wahai Syuaib"],["وَٱلَّذِينَ","Dan orang yang"],["ءَامَنُوا۟","(telah) beriman"],["مَعَكَ","bersama kamu"],["مِن","daripada"],["قَرْيَتِنَآ","bandar kami"],["أَوْ","atau"],["لَتَعُودُنَّ","kamu mesti balik"],["فِى","kepada"],["مِلَّتِنَا ۚ","agama kita"],["قَالَ","Dia berkata"],["أَوَلَوْ","Walaupun"],["كُنَّا","kita"],["كَـٰرِهِينَ","(orang-orang) yang membencinya"]]],"1043":["(Sungguh kami mengada-adakan kebohongan yang besar terhadap Allah jika kami kembali kepada agamamu sesudah Allah melepaskan kami daripadanya. Dan tidaklah patut) tidak pantas (bagi kami kembali kepadanya kecuali jika Allah Tuhan kami menghendaki) hal itu, yaitu menghinakan kami (Pengetahuan Tuhan kami meliputi segala sesuatu) yang di antaranya ialah Dia mengetahui keadaanku dan keadaanmu (Kepada Allah sajalah kami bertawakal. Ya Tuhan kami, berilah keputusan) ketentuan hukum (antara kami dan kaum kami dengan hak dan Engkaulah pemberi keputusan yang sebaik-baiknya) yakni hakim yang paling baik.",[["قَدِ","Sesungguhnya"],["ٱفْتَرَيْنَا","kami akan mengada-adakan"],["عَلَى","terhadap"],["ٱللَّهِ","Allah"],["كَذِبًا","satu pembohongan"],["إِنْ","jika"],["عُدْنَا","kami balik"],["فِى","dalam"],["مِلَّتِكُم","agama kamu"],["بَعْدَ","selepas"],["إِذْ","[apabila]"],["نَجَّىٰنَا","menyelamatkan kami"],["ٱللَّهُ","Allah"],["مِنْهَا ۚ","daripadanya"],["وَمَا","Dan tidak"],["يَكُونُ","ia adalah"],["لَنَآ","bagi kami"],["أَن","bahawa"],["نَّعُودَ","kita balik"],["فِيهَآ","di dalamnya"],["إِلَّآ","kecuali"],["أَن","bahawa"],["يَشَآءَ","wasiat"],["ٱللَّهُ","Allah"],["رَبُّنَا ۚ","Tuhan kami"],["وَسِعَ","merangkumi"],["رَبُّنَا","(oleh) Tuhan kami"],["كُلَّ","setiap"],["شَىْءٍ","perkara"],["عِلْمًا ۚ","(dalam) pengetahuan"],["عَلَى","selepas"],["ٱللَّهِ","Allah"],["تَوَكَّلْنَا ۚ","kami meletakkan kepercayaan kami"],["رَبَّنَا","Wahai Tuhan kami"],["ٱفْتَحْ","buat keputusan"],["بَيْنَنَا","antara kita"],["وَبَيْنَ","dan antara"],["قَوْمِنَا","orang kita"],["بِٱلْحَقِّ","dalam kebenaran"],["وَأَنتَ","dan kamu"],["خَيْرُ","(adalah) Terbaik"],["ٱلْفَـٰتِحِينَ","(daripada) mereka yang Memutuskan"]]],"1044":["(Pemuka-pemuka kaum Syuaib yang kafir berkata,) sebagian mereka berkata kepada sebagian yang lain (\"Sesungguhnya jika) lam adalah untuk qasam atau sumpah (kamu mengikut Syuaib, tentu jika kamu berbuat demikian menjadi orang-orang yang merugi.\")",[["وَقَالَ","Dan berkata"],["ٱلْمَلَأُ","ketua-ketua"],["ٱلَّذِينَ","orang yang"],["كَفَرُوا۟","kufur"],["مِن","antara"],["قَوْمِهِۦ","umatnya"],["لَئِنِ","Jika"],["ٱتَّبَعْتُمْ","kamu ikut"],["شُعَيْبًا","Shuaib"],["إِنَّكُمْ","sesungguhnya, kamu"],["إِذًۭا","kemudian"],["لَّخَـٰسِرُونَ","(akan menjadi) orang-orang yang rugi"]]],"1045":["(Kemudian mereka ditimpa gempa) gempa bumi yang dahsyat (maka jadilah mereka mayat-mayat yang bergelimpangan di tempat tinggal mereka) mereka mati dalam keadaan bertekuk-lutut.",[["فَأَخَذَتْهُمُ","Kemudian menangkap mereka"],["ٱلرَّجْفَةُ","gempa bumi"],["فَأَصْبَحُوا۟","kemudian mereka menjadi"],["فِى","dalam"],["دَارِهِمْ","rumah mereka"],["جَـٰثِمِينَ","jatuh tersungkur"]]],"1046":["(Yaitu orang-orang yang mendustakan Syuaib) menjadi mubtada dan khabarnya ialah (seolah-olah) dengan ditakhfifkan sedangkan isimnya dibuang, lengkapnya ialah: Seolah-olah mereka (mereka belum pernah berdiam) artinya mereka belum pernah tinggal (di kota itu) di rumah-rumah mereka sendiri (orang-orang yang mendustakan Syuaib mereka itulah orang-orang yang merugi) pengukuhan dengan mengulangi maushul dan lainnya merupakan jawaban terhadap perkataan mereka yang terdahulu.",[["ٱلَّذِينَ","Orang yang"],["كَذَّبُوا۟","dinafikan"],["شُعَيْبًۭا","Shuaib"],["كَأَن","(menjadi) seolah-olah"],["لَّمْ","tidak"],["يَغْنَوْا۟","mereka (telah) hidup"],["فِيهَا ۚ","di dalamnya"],["ٱلَّذِينَ","Orang yang"],["كَذَّبُوا۟","dinafikan"],["شُعَيْبًۭا","Shuaib"],["كَانُوا۟","mereka adalah"],["هُمُ","mereka"],["ٱلْخَـٰسِرِينَ","yang rugi"]]],"1047":["(Maka Syuaib berpaling) yakni meninggalkan (mereka seraya berkata, \"Hai kaumku! Sesungguhnya aku telah menyampaikan amanat-amanah Tuhanku dan aku telah memberi nasihat kepadamu) akan tetapi kamu tidak juga mau beriman (Maka bagaimana aku akan bersedih hati) bersusah hati (terhadap orang-orang yang kafir?\") Istifham di sini bermakna nafi.",[["فَتَوَلَّىٰ","Jadi dia berpaling"],["عَنْهُمْ","daripada mereka"],["وَقَالَ","dan berkata"],["يَـٰقَوْمِ","Wahai kaumku"],["لَقَدْ","Sesungguhnya"],["أَبْلَغْتُكُمْ","Aku (telah) sampaikan kepada kamu"],["رِسَـٰلَـٰتِ","(the) Mesej"],["رَبِّى","(dari) Tuhanku"],["وَنَصَحْتُ","dan dinasihatkan"],["لَكُمْ ۖ","[kepada] kamu"],["فَكَيْفَ","Jadi bagaimana boleh"],["ءَاسَىٰ","aku bersedih"],["عَلَىٰ","bagi"],["قَوْمٍۢ","suatu kaum"],["كَـٰفِرِينَ","(yaitu) orang-orang kafir"]]],"1048":["(Kami tidaklah mengutus seseorang nabi pun kepada sesuatu negeri) kemudian penduduknya mendustakannya (melainkan Kami timpakan) Kami siksa (kepada penduduknya kesempitan) yakni kemiskinan yang sangat (dan penderitaan) berupa penyakit (supaya mereka tunduk dengan merendahkan diri) mereka mau merendahkan dirinya sehingga mereka mau beriman.",[["وَمَآ","Dan tidak"],["أَرْسَلْنَا","Kami utus"],["فِى","dalam"],["قَرْيَةٍۢ","sebuah bandar"],["مِّن","sebarang"],["نَّبِىٍّ","Nabi"],["إِلَّآ","kecuali"],["أَخَذْنَآ","Kami rampas"],["أَهْلَهَا","rakyatnya"],["بِٱلْبَأْسَآءِ","dengan kesusahan"],["وَٱلضَّرَّآءِ","dan kesusahan"],["لَعَلَّهُمْ","supaya mereka boleh"],["يَضَّرَّعُونَ","(menjadi) merendah diri"]]],"1049":["(Kemudian Kami ganti) Kami berikan kepada mereka (kesusahan itu) yakni azab itu (dengan kesenangan) kecukupan dan kesehatan (hingga mereka bertambah banyak) makin banyak keturunan dan hartanya (dan mereka berkata,) sebagai ungkapan ingkar terhadap karunia Allah (\"Sesungguhnya nenek moyang kami pun telah merasai penderitaan dan kesenangan\") seperti apa yang sedang kami alami, memang demikianlah hukum alam itu, jadi bukanlah merupakan siksaan dari Allah, maka dari itu tetaplah kamu dengan apa yang sekarang kamu pegang. Allah berfirman, (maka Kami timpakan kepada mereka) siksaan (dengan sekonyong-konyong) secara tiba-tiba (sedangkan mereka tidak menyadarinya) sebelum saat azab itu datang.",[["ثُمَّ","Kemudian"],["بَدَّلْنَا","Kami berubah"],["مَكَانَ","(di) tempat"],["ٱلسَّيِّئَةِ","(dari) yang buruk"],["ٱلْحَسَنَةَ","yang baik"],["حَتَّىٰ","sehingga"],["عَفَوا۟","mereka bertambah"],["وَّقَالُوا۟","dan berkata"],["قَدْ","Sesungguhnya"],["مَسَّ","(telah) menyentuh"],["ءَابَآءَنَا","nenek moyang kita"],["ٱلضَّرَّآءُ","kesusahan itu"],["وَٱلسَّرَّآءُ","dan kemudahannya"],["فَأَخَذْنَـٰهُم","Maka Kami siksa mereka"],["بَغْتَةًۭ","tiba-tiba"],["وَهُمْ","sedangkan mereka"],["لَا","(tidak) tidak"],["يَشْعُرُونَ","mempersepsikan"]]],"1050":["(Dan jika sekiranya penduduk negeri-negeri) yang mendustakan (beriman) terhadap Allah dan rasul-rasul mereka (dan bertakwa) tidak kafir dan maksiat (pastilah Kami akan melimpahkan) dengan dibaca takhfif dan tasydid (kepada mereka berkah dari langit) dengan melalui hujan (dan bumi) dengan melalui tetumbuhan (tetapi mereka mendustakan) rasul-rasul (maka Kami siksa mereka) Kami hukum mereka (disebabkan perbuatan mereka sendiri).",[["وَلَوْ","Dan jika"],["أَنَّ","[bahawa]"],["أَهْلَ","orang ramai"],["ٱلْقُرَىٰٓ","(dari) bandar-bandar"],["ءَامَنُوا۟","(telah) beriman"],["وَٱتَّقَوْا۟","dan takut kepada Allah"],["لَفَتَحْنَا","sesungguhnya Kami (akan) membuka"],["عَلَيْهِم","ke atas mereka"],["بَرَكَـٰتٍۢ","berkat"],["مِّنَ","daripada"],["ٱلسَّمَآءِ","syurga itu"],["وَٱلْأَرْضِ","dan bumi"],["وَلَـٰكِن","tetapi"],["كَذَّبُوا۟","mereka menafikan"],["فَأَخَذْنَـٰهُم","Maka Kami siksa mereka"],["بِمَا","bagi apa"],["كَانُوا۟","mereka dahulu"],["يَكْسِبُونَ","peroleh"]]],"1051":["(Maka apakah merasa aman penduduk negeri-negeri itu) yang mendustakan (dari kedatangan siksaan Kami kepada mereka) yaitu azab Kami (di malam hari) tengah malam (di waktu mereka sedang tidur) dalam keadaan lalai dari kedatangan azab itu.",[["أَفَأَمِنَ","Kemudian berasa selamat"],["أَهْلُ","kaum"],["ٱلْقُرَىٰٓ","(dari) bandar-bandar"],["أَن","bahawa"],["يَأْتِيَهُم","datang kepada mereka"],["بَأْسُنَا","hukuman kita"],["بَيَـٰتًۭا","(pada) malam"],["وَهُمْ","sedangkan mereka"],["نَآئِمُونَ","(sedang) tidur"]]],"1052":["(Atau apakah penduduk negeri-negeri itu merasa aman dari kedatangan siksaan Kami kepada mereka di waktu matahari sepenggalah naik) pada waktu siang hari (ketika mereka sedang bermain).",[["أَوَأَمِنَ","Atau berasa selamat"],["أَهْلُ","kaum"],["ٱلْقُرَىٰٓ","(dari) bandar-bandar"],["أَن","bahawa"],["يَأْتِيَهُم","datang kepada mereka"],["بَأْسُنَا","hukuman kita"],["ضُحًۭى","(dalam) siang hari"],["وَهُمْ","sedangkan mereka"],["يَلْعَبُونَ","(sedang) bermain"]]],"1053":["(Maka apakah mereka merasa aman dari tipu daya Allah.) yakni istidraj Allah terhadap mereka dengan memberi mereka banyak kenikmatan kemudian Ia menghukum mereka dengan sekonyong-konyong (Tiada yang merasa aman dari tipu daya Allah kecuali hanya orang-orang yang merugi).",[["أَفَأَمِنُوا۟","Kemudian adakah mereka merasa aman"],["مَكْرَ","(daripada) rancangan"],["ٱللَّهِ ۚ","(milik) Allah"],["فَلَا","Tetapi tidak"],["يَأْمَنُ","rasa selamat"],["مَكْرَ","(daripada) rancangan"],["ٱللَّهِ","(milik) Allah"],["إِلَّا","kecuali"],["ٱلْقَوْمُ","manusia"],["ٱلْخَـٰسِرُونَ","(siapa) orang-orang yang rugi"]]],"1054":["(Dan apakah belum jelas) artinya belum terang (bagi orang-orang yang mempusakai bumi ini) sebagai tempat tinggalnya (sesudah) binasanya (penduduknya bahwa) menjadi fa'il berasal dari anna yang ditakhfifkan sedangkan isimnya dibuang, artinya bahwasanya (kalau Kami menghendaki tentu Kami timpakan kepada mereka siksaan) yakni azab (karena dosa-dosanya) sebagaimana telah Kami timpakan siksaan kepada orang-orang sebelum mereka. Kesemua hamzah di empat tempat tersebut semuanya bermakna lit-taubikh/mencela; dan huruf fa dan wawu yang memasuki pada kedua di antaranya untuk tujuan athaf. Menurut suatu qiraat dibaca dengan wawu yang disukunkan pada tempat yang pertama karena diathafkan kepada huruf aw. (Dan) Kami (kunci) Kami lak (hati mereka sehingga mereka tidak dapat mendengar) nasihat dengan pendengaran yang sehat.",[["أَوَلَمْ","Bukankah"],["يَهْدِ","panduan"],["لِلَّذِينَ","[untuk] mereka yang"],["يَرِثُونَ","mewarisi"],["ٱلْأَرْضَ","bumi"],["مِنۢ","daripada"],["بَعْدِ","selepas"],["أَهْلِهَآ","rakyatnya"],["أَن","bahawa"],["لَّوْ","jika"],["نَشَآءُ","Kami berkehendak"],["أَصَبْنَـٰهُم","Kami (boleh) menyusahkan mereka"],["بِذُنُوبِهِمْ ۚ","kerana dosa mereka"],["وَنَطْبَعُ","dan Kami meletakkan meterai"],["عَلَىٰ","atas"],["قُلُوبِهِمْ","hati mereka"],["فَهُمْ","jadi mereka"],["لَا","jangan"],["يَسْمَعُونَ","dengar"]]],"1055":["(Negeri-negeri itu) yang telah disebutkan tadi (Kami ceritakan kepadamu) hai Muhammad (tentang sebagian dari berita-beritanya) cerita-cerita penduduknya (Dan sungguh telah datang kepada mereka rasul-rasul mereka dengan membawa bukti-bukti) yaitu mukjizat-mukjizat yang selalu unggul lagi jelas (maka mereka juga tidak beriman) tatkala rasul-rasul itu datang (kepada apa yang dahulu mereka telah mendustakannya) yang telah mereka ingkari (sebelum itu) sebelum para rasul itu datang, bahkan mereka tetap terus melakukan kekafirannya. (Demikianlah) seperti penguncian itu (Allah mengunci mati hati orang-orang kafir).",[["تِلْكَ","Ini"],["ٱلْقُرَىٰ","(ialah) bandar-bandar itu"],["نَقُصُّ","Kami mengaitkan"],["عَلَيْكَ","kepada kamu"],["مِنْ","daripada"],["أَنۢبَآئِهَا ۚ","berita mereka"],["وَلَقَدْ","Dan sungguh"],["جَآءَتْهُمْ","datang kepada mereka"],["رُسُلُهُم","Rasul-rasul mereka"],["بِٱلْبَيِّنَـٰتِ","dengan bukti yang jelas"],["فَمَا","tetapi tidak"],["كَانُوا۟","mereka adalah"],["لِيُؤْمِنُوا۟","untuk beriman"],["بِمَا","pada apa"],["كَذَّبُوا۟","mereka (telah) mendustakan"],["مِن","daripada"],["قَبْلُ ۚ","sebelum"],["كَذَٰلِكَ","Demikianlah"],["يَطْبَعُ","(telah) meletakkan meterai"],["ٱللَّهُ","(oleh) Allah"],["عَلَىٰ","pada"],["قُلُوبِ","(the) hati"],["ٱلْكَـٰفِرِينَ","(dari) orang-orang kafir"]]],"1056":["(Dan Kami tidak mendapati kebanyakan mereka) maksudnya kebanyakan umat manusia itu (memenuhi janji) menunaikan janji mereka tatkala tiba saat pemenuhannya (Sesungguhnya) ditakhfifkan dari anna (Kami mendapati kebanyakan mereka orang-orang yang fasik).",[["وَمَا","Dan tidak"],["وَجَدْنَا","Kami jumpa"],["لِأَكْثَرِهِم","bagi kebanyakan mereka"],["مِّنْ","sebarang"],["عَهْدٍۢ ۖ","perjanjian"],["وَإِن","Tetapi"],["وَجَدْنَآ","Kami jumpa"],["أَكْثَرَهُمْ","kebanyakan mereka"],["لَفَـٰسِقِينَ","tentulah ingkar"]]],"1057":["(Kemudian Kami utus sesudah rasul-rasul itu) sesudah diutusnya rasul-rasul tersebut (Musa dengan membawa ayat-ayat Kami) yang banyaknya sembilan (kepada Firaun dan pemuka-pemuka kaumnya) golongannya (lalu mereka mengingkari) mengkafiri (ayat-ayat itu. Maka perhatikanlah bagaimana akibat orang-orang yang membuat kerusakan) artinya mereka binasa akibat kekafirannya itu.",[["ثُمَّ","Kemudian"],["بَعَثْنَا","Kami utus"],["مِنۢ","daripada"],["بَعْدِهِم","selepas mereka"],["مُّوسَىٰ","Musa"],["بِـَٔايَـٰتِنَآ","dengan Tanda-tanda Kami"],["إِلَىٰ","kepada"],["فِرْعَوْنَ","Firaun"],["وَمَلَإِي۟هِۦ","dan ketua-ketuanya"],["فَظَلَمُوا۟","Tetapi mereka tidak adil"],["بِهَا ۖ","kepada mereka"],["فَٱنظُرْ","Jadi lihat"],["كَيْفَ","bagaimana"],["كَانَ","adalah"],["عَـٰقِبَةُ","(akhirnya)."],["ٱلْمُفْسِدِينَ","(dari) para perasuah"]]],"1058":["(Dan Musa berkata, \"Hai Firaun, sesungguhnya aku ini adalah seorang utusan Tuhan semesta alam\") kepadamu, akan tetapi Firaun mendustakannya dan Musa berkata,",[["وَقَالَ","Dan berkata"],["مُوسَىٰ","Musa"],["يَـٰفِرْعَوْنُ","Wahai Firaun"],["إِنِّى","Memang aku"],["رَسُولٌۭ","seorang Rasul"],["مِّن","daripada"],["رَّبِّ","(yang) Tuhan"],["ٱلْعَـٰلَمِينَ","sekalian alam"]]],"1059":["(\"Aku lebih berhak) lebih pantas (untuk) agar (tidak mengatakan sesuatu terhadap Allah kecuali yang hak) menurut suatu qiraat dibaca tasydid ya-nya; haqiiqun adalah mubtada sedangkan khabarnya adalah an dan kalimat sesudahnya (Sesungguhnya aku datang kepadamu dengan membawa bukti yang nyata dari Tuhanmu, maka lepaskanlah pergi bersamaku) menuju ke negeri Syam (Bani Israel.\") kaum Bani Israel itu selalu ditindas oleh Firaun.",[["حَقِيقٌ","Diwajibkan"],["عَلَىٰٓ","pada"],["أَن","bahawa"],["لَّآ","tidak"],["أَقُولَ","aku cakap"],["عَلَى","tentang"],["ٱللَّهِ","Allah"],["إِلَّا","kecuali"],["ٱلْحَقَّ ۚ","kebenaran"],["قَدْ","Sesungguhnya"],["جِئْتُكُم","Aku (telah) datang kepada kamu"],["بِبَيِّنَةٍۢ","dengan Tanda yang jelas"],["مِّن","daripada"],["رَّبِّكُمْ","Tuhanmu"],["فَأَرْسِلْ","jadi hantar"],["مَعِىَ","dengan aku"],["بَنِىٓ","(the) Kanak-kanak"],["إِسْرَٰٓءِيلَ","(dari) Israel"]]],"1060":["(Berkatalah) Firaun kepadanya, (\"Jika kamu benar membawa sesuatu ayat) bukti yang memperkuat pengakuanmu (maka datangkanlah bukti itu jika betul kamu termasuk orang-orang yang benar.\") membawa bukti itu.",[["قَالَ","Dia berkata"],["إِن","Jika"],["كُنتَ","kamu ada"],["جِئْتَ","datang"],["بِـَٔايَةٍۢ","dengan Tanda"],["فَأْتِ","kemudian bawa"],["بِهَآ","ia"],["إِن","jika"],["كُنتَ","kamu"],["مِنَ","daripada"],["ٱلصَّـٰدِقِينَ","yang benar"]]],"1061":["(Maka Musa menjatuhkan tongkatnya, lalu seketika itu juga tongkat itu menjadi ular yang sebenarnya) yakni ular yang sangat besar bentuknya.",[["فَأَلْقَىٰ","Jadi dia melemparkan"],["عَصَاهُ","kakitangannya"],["فَإِذَا","dan tiba-tiba"],["هِىَ","ia"],["ثُعْبَانٌۭ","(adalah) seekor ular"],["مُّبِينٌۭ","nyata"]]],"1062":["(Dan ia mengeluarkan tangannya) mengeluarkannya dari dalam sakunya (maka ketika itu juga tangan itu menjadi putih bercahaya menyilaukan (bagi orang-orang yang melihatnya) berbeda warnanya dengan keadaan kulit tangan yang sebenarnya.",[["وَنَزَعَ","Dan dia menarik keluar"],["يَدَهُۥ","tangannya"],["فَإِذَا","dan tiba-tiba"],["هِىَ","ia"],["بَيْضَآءُ","(adalah) putih"],["لِلنَّـٰظِرِينَ","untuk pemerhati"]]],"1063":["(Pemuka-pemuka kaum Firaun berkata, \"Sesungguhnya Musa ini adalah ahli sihir yang pandai) yang ulung di dalam ilmu sihir, dan di dalam surah Asy-Syu`ara disebutkan bahwa perkataan ini adalah perkataan Firaun sendiri. Seolah-olah para pemuka kaum Firaun itu mengatakan perkataan tersebut bersama Firaun sendiri, setelah mereka dan dia bermusyawarah tentang hal itu.",[["قَالَ","Berkata"],["ٱلْمَلَأُ","ketua-ketua"],["مِن","daripada"],["قَوْمِ","kaum"],["فِرْعَوْنَ","(daripada) Firaun"],["إِنَّ","Sesungguhnya"],["هَـٰذَا","ini"],["لَسَـٰحِرٌ","(adalah) sesungguhnya seorang ahli sihir"],["عَلِيمٌۭ","dipelajari"]]],"1064":["(Yang bermaksud hendak mengeluarkan kamu dari negerimu.\" Firaun berkata, \"Maka apakah yang kamu anjurkan?\")",[["يُرِيدُ","Dia mahu"],["أَن","kepada"],["يُخْرِجَكُم","menghalau kamu keluar"],["مِّنْ","daripada"],["أَرْضِكُمْ ۖ","tanah kamu"],["فَمَاذَا","jadi apa"],["تَأْمُرُونَ","(ada) kamu arahkan"]]],"1065":["(Pemuka-pemuka itu menjawab, \"Beri tangguhlah dia dan saudaranya) tangguhkanlah perkara keduanya (serta kirimlah ke kota-kota beberapa orang yang akan mengumpulkan ahli-ahli sihir) yang menghimpun para ahli sihir.",[["قَالُوٓا۟","Mereka berkata"],["أَرْجِهْ","tangguhkan dia"],["وَأَخَاهُ","dan abangnya"],["وَأَرْسِلْ","dan hantar"],["فِى","dalam"],["ٱلْمَدَآئِنِ","bandar-bandar"],["حَـٰشِرِينَ","pengumpul"]]],"1066":["(Supaya mereka membawa kepadamu semua ahli sihir) menurut suatu qiraat dibaca sahhaar (yang pandai.\") maksudnya yang dapat melebihi kepandaian ilmu sihir Musa, akhirnya mereka dapat menghimpunnya.",[["يَأْتُوكَ","Mereka (akan) membawa kepada kamu"],["بِكُلِّ","[dengan] setiap"],["سَـٰحِرٍ","ahli silap mata"],["عَلِيمٍۢ","dipelajari"]]],"1067":["(Dan beberapa ahli sihir itu datang kepada Firaun mengatakan, \"Apakah sesungguhnya) menurut qiraat yang lain lafal inna dibaca ainna (kami akan mendapat upah jika kamilah yang menang?\").",[["وَجَآءَ","Jadi datang"],["ٱلسَّحَرَةُ","ahli sihir"],["فِرْعَوْنَ","(kepada) Firaun"],["قَالُوٓا۟","Mereka berkata"],["إِنَّ","Sesungguhnya"],["لَنَا","bagi kami"],["لَأَجْرًا","sesungguhnya (akan) mendapat pahala"],["إِن","jika"],["كُنَّا","kita"],["نَحْنُ","[kami]"],["ٱلْغَـٰلِبِينَ","para pemenang"]]],"1068":["(Firaun menjawab, \"Ya, dan sesungguhnya kamu benar-benar akan termasuk orang-orang yang dekat kepadaku.\")",[["قَالَ","Dia berkata"],["نَعَمْ","ya"],["وَإِنَّكُمْ","dan sesungguhnya kamu"],["لَمِنَ","nescaya (akan) daripada"],["ٱلْمُقَرَّبِينَ","mereka yang dekat"]]],"1069":["(Ahli-ahli sihir berkata, \"Hai Musa! Kamukah yang akan melemparkan lebih dahulu) tongkatmu (ataukah kami yang akan melemparkan?\") apa-apa yang ada pada kami.",[["قَالُوا۟","Mereka berkata"],["يَـٰمُوسَىٰٓ","Wahai Musa"],["إِمَّآ","sama ada"],["أَن","[bahawa]"],["تُلْقِىَ","kamu buang"],["وَإِمَّآ","atau Sama ada"],["أَن","[bahawa]"],["نَّكُونَ","kita akan jadi"],["نَحْنُ","[kami]"],["ٱلْمُلْقِينَ","yang hendak membuang"]]],"1070":["(Musa menjawab, \"Lemparkanlah olehmu lebih dahulu) ini adalah suatu perintah yang mempersilakan mereka untuk melemparkan apa yang ada pada mereka, sebagai suatu taktik dari Musa untuk menampakkan yang hak (Maka tatkala mereka melemparkan) tambang-tambang mereka dan tongkat-tongkat mereka (mereka menyulap mata orang) mereka membalik mata para hadirin supaya tidak bisa melihat hal yang sebenarnya (dan menjadikan orang banyak itu takut) artinya mereka membuatnya takut karena mereka menjadikan seolah-olah hal itu adalah ular-ular yang menjalar (serta mereka mendatangkan sihir yang besar, menakjubkan\").",[["قَالَ","Dia berkata"],["أَلْقُوا۟ ۖ","Baling"],["فَلَمَّآ","Kemudian apabila"],["أَلْقَوْا۟","mereka melemparkan"],["سَحَرُوٓا۟","mereka disihir"],["أَعْيُنَ","(mata)."],["ٱلنَّاسِ","(daripada) rakyat"],["وَٱسْتَرْهَبُوهُمْ","dan menakutkan mereka"],["وَجَآءُو","dan datang (naik)"],["بِسِحْرٍ","dengan sihir"],["عَظِيمٍۢ","yang besar"]]],"1071":["(Dan Kami wahyukan kepada Musa, \"Lemparkanlah tongkatmu!\" Maka sekonyong-konyong tongkat itu menelan) dengan membuang salah satu di antara kedua ta yang asal, yakni: tongkat itu mencaplok (apa yang mereka sulapkan) apa yang mereka balikkan pada pandangan mata orang dengan tipu sulap mereka.",[["۞ وَأَوْحَيْنَآ","Dan Kami ilhamkan"],["إِلَىٰ","kepada"],["مُوسَىٰٓ","Musa"],["أَنْ","bahawa"],["أَلْقِ","Baling"],["عَصَاكَ ۖ","kakitangan kamu"],["فَإِذَا","dan tiba-tiba"],["هِىَ","ia"],["تَلْقَفُ","telan (ed)"],["مَا","apa"],["يَأْفِكُونَ","mereka (sedang) berdusta"]]],"1072":["(Karena itu nyatalah yang benar) yakni telah tetap dan menang yang benar itu (dan batallah yang selalu mereka kerjakan) yaitu perbuatan-perbuatan sihir mereka.",[["فَوَقَعَ","Maka telah ditegakkan"],["ٱلْحَقُّ","kebenaran"],["وَبَطَلَ","dan menjadi sia-sia"],["مَا","apa"],["كَانُوا۟","mereka dahulu"],["يَعْمَلُونَ","lakukan"]]],"1073":["(Maka mereka kalah) yakni Firaun dan kaumnya (di tempat itu dan jadilah mereka orang-orang yang hina) artinya kini mereka menjadi orang-orang yang kecil lagi hina.",[["فَغُلِبُوا۟","Jadi mereka dikalahkan"],["هُنَالِكَ","di sana"],["وَٱنقَلَبُوا۟","dan kembali"],["صَـٰغِرِينَ","dihina"]]],"1074":["(Dan ahli-ahli sihir itu dengan serta-merta meniarapkan diri dengan bersujud).",[["وَأُلْقِىَ","Dan jatuh tersungkur"],["ٱلسَّحَرَةُ","ahli sihir"],["سَـٰجِدِينَ","sujud"]]],"1075":["(Mereka berkata, \"Kami beriman kepada Tuhan semesta alam).",[["قَالُوٓا۟","Mereka berkata"],["ءَامَنَّا","Kami beriman"],["بِرَبِّ","di dalam Tuhan"],["ٱلْعَـٰلَمِينَ","sekalian alam"]]],"1076":["(Yaitu Tuhan Musa dan Harun\") berkat pengetahuan mereka yang menyimpulkan bahwa apa yang telah mereka saksikan itu, yaitu tentang tongkat Musa semata-mata bukanlah perbuatan sihir.",[["رَبِّ","Tuhan"],["مُوسَىٰ","(dari) Musa"],["وَهَـٰرُونَ","dan Harun"]]],"1077":["(Firaun berkata, \"Apakah kamu beriman) lafal aamantum dapat dibaca a amantum (kepadanya) kepada Musa (sebelum aku memberi izin) (kepadamu? Sesungguhnya hal ini) apa yang kamu perbuat ini (adalah suatu muslihat yang telah kamu rencanakan di dalam kota ini untuk mengeluarkan penduduknya daripadanya, maka kelak kamu akan mengetahui) apa yang bakal kamu terima balasannya dariku.",[["قَالَ","Berkata"],["فِرْعَوْنُ","Firaun"],["ءَامَنتُم","kamu beriman"],["بِهِۦ","dalam dirinya"],["قَبْلَ","sebelum"],["أَنْ","[bahawa]"],["ءَاذَنَ","aku beri izin"],["لَكُمْ ۖ","kepada kamu"],["إِنَّ","Sesungguhnya"],["هَـٰذَا","ini"],["لَمَكْرٌۭ","(adalah) pasti satu plot"],["مَّكَرْتُمُوهُ","kamu telah merancangnya"],["فِى","dalam"],["ٱلْمَدِينَةِ","bandar itu"],["لِتُخْرِجُوا۟","supaya kamu boleh mengusir"],["مِنْهَآ","daripadanya"],["أَهْلَهَا ۖ","rakyatnya"],["فَسَوْفَ","Tetapi tidak lama lagi"],["تَعْلَمُونَ","kamu akan tahu"]]],"1078":["(Demi sesungguhnya aku akan memotong tangan dan kakimu dengan bersilang secara timbal balik) yakni tangan kanan setiap orang akan dipotong berikut kaki sebelah kirinya (kemudian sungguh-sungguh aku akan menyalibmu semuanya.\")",[["لَأُقَطِّعَنَّ","Aku pasti akan memotong"],["أَيْدِيَكُمْ","tangan kamu"],["وَأَرْجُلَكُم","dan kaki kamu"],["مِّنْ","daripada"],["خِلَـٰفٍۢ","bertentangan (sisi)"],["ثُمَّ","Kemudian"],["لَأُصَلِّبَنَّكُمْ","Aku pasti akan menyalibkan kamu"],["أَجْمَعِينَ","semua"]]],"1079":["(Ahli-ahli sihir itu menjawab, \"Sesungguhnya kepada Tuhan kamilah) sesudah kami mati dengan cara apa pun (kami kembali) dikembalikan kelak di akhirat.",[["قَالُوٓا۟","Mereka berkata"],["إِنَّآ","Sesungguhnya kami"],["إِلَىٰ","kepada"],["رَبِّنَا","Tuhan kami"],["مُنقَلِبُونَ","(akan) kembali"]]],"1080":["(Dan kamu tidak membalas dendam) maksudnya kamu tidak mengingkari (dengan menyiksa kami melainkan karena kami telah beriman kepada ayat-ayat Tuhan kami ketika ayat-ayat itu datang kepada kami.\" Mereka berdoa, \"Ya Tuhan kami, limpahkanlah kesabaran kepada kami) tatkala dilaksanakannya apa yang diancamkan oleh Firaun agar kami tidak kembali menjadi orang-orang kafir (dan wafatkanlah kami dalam keadaan berserah diri kepada-Mu.\")",[["وَمَا","Dan tidak"],["تَنقِمُ","kamu balas dendam"],["مِنَّآ","daripada kami"],["إِلَّآ","kecuali"],["أَنْ","bahawa"],["ءَامَنَّا","kami beriman"],["بِـَٔايَـٰتِ","dalam (the) Tanda-tanda"],["رَبِّنَا","(dari) Tuhan kami"],["لَمَّا","apabila"],["جَآءَتْنَا ۚ","mereka datang kepada kita"],["رَبَّنَآ","Wahai Tuhan kami"],["أَفْرِغْ","tuang"],["عَلَيْنَا","atas kita"],["صَبْرًۭا","kesabaran"],["وَتَوَفَّنَا","dan menyebabkan kita mati"],["مُسْلِمِينَ","(sebagai) orang Islam"]]],"1081":["(Berkatalah pembesar-pembesar dari kaum Firaun,) kepada Firaun sendiri (\"Apakah kamu membiarkan) meninggalkan (Musa dan kaumnya untuk membuat kerusakan di negeri ini) yaitu dengan menyeru ajakan agar menentangmu (dan meninggalkan kamu serta tuhan-tuhanmu?\") tersebutlah bahwa Firaun itu telah membuat berhala-berhala kecil untuk disembah oleh kaumnya, kemudian Firaun berkata, \"Aku adalah tuhanmu dan tuhan mereka,\" oleh karena itu ia pernah mengatakan, \"Aku adalah tuhanmu yang paling tinggi.\" (Firaun menjawab, \"Akan kita bunuh) dengan mentasydidkan huruf ta-nya (anak-anak lelaki mereka) yang baru dilahirkan (dan kita biarkan hidup) kita biarkan (perempuan-perempuan mereka) sebagaimana yang pernah kita lakukan terhadap mereka sebelumnya (dan sesungguhnya kita berkuasa penuh di atas mereka.\") yakni orang-orang yang berkuasa; akhirnya mereka melakukan hal itu terhadap kaum Musa, sehingga membuat kaum Bani Israel mengadu kepada Musa.",[["وَقَالَ","Dan berkata"],["ٱلْمَلَأُ","ketua-ketua"],["مِن","daripada"],["قَوْمِ","kaum"],["فِرْعَوْنَ","(daripada) Firaun"],["أَتَذَرُ","Adakah kamu akan pergi"],["مُوسَىٰ","Musa"],["وَقَوْمَهُۥ","dan umatnya"],["لِيُفْسِدُوا۟","sehingga menyebabkan rasuah"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["وَيَذَرَكَ","dan meninggalkan kamu"],["وَءَالِهَتَكَ ۚ","dan tuhan-tuhan kamu"],["قَالَ","Dia berkata"],["سَنُقَتِّلُ","Kami akan membunuh"],["أَبْنَآءَهُمْ","anak lelaki mereka"],["وَنَسْتَحْىِۦ","dan kami akan biarkan hidup"],["نِسَآءَهُمْ","wanita mereka"],["وَإِنَّا","dan sesungguhnya, kita"],["فَوْقَهُمْ","atas mereka"],["قَـٰهِرُونَ","(adalah) penunduk"]]],"1082":["(Musa berkata kepada kaumnya, \"Mohonlah pertolongan kepada Allah dan bersabarlah) dalam menghadapi penganiayaan mereka (sesungguhnya bumi ini kepunyaan Allah yang dipusakakan-Nya) yang diberi-Nya (kepada siapa yang dikehendaki-Nya dari hamba-hamba-Nya. Dan kesudahan yang baik) yang terpuji (adalah bagi orang-orang yang bertakwa.\") terhadap Allah.",[["قَالَ","Berkata"],["مُوسَىٰ","Musa"],["لِقَوْمِهِ","kepada umatnya"],["ٱسْتَعِينُوا۟","Dapatkan bantuan"],["بِٱللَّهِ","daripada Allah"],["وَٱصْبِرُوٓا۟ ۖ","dan bersabarlah"],["إِنَّ","Sesungguhnya"],["ٱلْأَرْضَ","bumi"],["لِلَّهِ","(kepunyaan) Allah"],["يُورِثُهَا","Dia menyebabkan untuk mewarisinya"],["مَن","yang"],["يَشَآءُ","Dia kehendaki"],["مِنْ","daripada"],["عِبَادِهِۦ ۖ","hambaNya"],["وَٱلْعَـٰقِبَةُ","Dan kesudahannya"],["لِلْمُتَّقِينَ","(adalah) untuk orang-orang yang bertakwa"]]],"1083":["(Kaum Musa berkata, \"Kami telah ditindas, oleh Firaun, sebelum kamu datang kepada kami dan sesudah kamu datang.\" Musa menjawab, \"Mudah-mudahan Allah membinasakan musuhmu dan menjadikan kamu khalifah di bumi-Nya, maka Allah akan melihat bagaimana perbuatanmu.\") di dalamnya.",[["قَالُوٓا۟","Mereka berkata"],["أُوذِينَا","Kami telah dicederakan"],["مِن","daripada"],["قَبْلِ","sebelum"],["أَن","[bahawa]"],["تَأْتِيَنَا","kamu datang kepada kami"],["وَمِنۢ","daripada"],["بَعْدِ","dan selepas"],["مَا","[apa]"],["جِئْتَنَا ۚ","kamu telah datang kepada kami"],["قَالَ","Dia berkata"],["عَسَىٰ","barangkali"],["رَبُّكُمْ","Tuhanmu"],["أَن","[bahawa]"],["يُهْلِكَ","akan memusnahkan"],["عَدُوَّكُمْ","musuh kamu"],["وَيَسْتَخْلِفَكُمْ","dan menjadikan kamu pengganti"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["فَيَنظُرَ","kemudian lihat"],["كَيْفَ","bagaimana"],["تَعْمَلُونَ","kamu akan lakukan"]]],"1084":["(Dan sesungguhnya Kami telah menghukum Firaun dan kaumnya dengan mendatangkan musim kemarau yang panjang) musim paceklik (dan kekurangan buah-buahan supaya mereka mengambil pelajaran) menjadikannya sebagai pelajaran bagi mereka kemudian mereka mau beriman karenanya.",[["وَلَقَدْ","Dan sungguh"],["أَخَذْنَآ","Kami rampas"],["ءَالَ","kaum"],["فِرْعَوْنَ","(daripada) Firaun"],["بِٱلسِّنِينَ","dengan tahun (kebuluran)"],["وَنَقْصٍۢ","dan defisit"],["مِّنَ","daripada"],["ٱلثَّمَرَٰتِ","buah-buahan"],["لَعَلَّهُمْ","supaya mereka boleh"],["يَذَّكَّرُونَ","menerima teguran"]]],"1085":["(Kemudian apabila datang kepada mereka kemakmuran) kesuburan tanah dan kecukupan hidup (mereka berkata, \"Ini adalah karena usaha kami\") kami berhak memperolehnya, akan tetapi mereka tidak mau mensyukurinya. (Dan jika mereka ditimpa kesusahan) kekeringan dan musibah/bencana (mereka lemparkan sebab kesialan itu) mereka menganggap kesialan itu (kepada Musa dan orang-orang yang besertanya) dari kalangan orang-orang yang beriman. (Ketahuilah sesungguhnya kesialan mereka itu) rasa sial mereka itu (adalah ketetapan dari Allah) yang sengaja diturunkan kepada mereka (akan tetapi kebanyakan mereka tidak mengetahui) bahwa apa yang menimpa mereka adalah datang dari sisi Allah.",[["فَإِذَا","Tetapi apabila"],["جَآءَتْهُمُ","datang kepada mereka"],["ٱلْحَسَنَةُ","yang baik"],["قَالُوا۟","mereka berkata"],["لَنَا","Untuk kita"],["هَـٰذِهِۦ ۖ","(adalah) ini"],["وَإِن","Dan jika"],["تُصِبْهُمْ","menyusahkan mereka"],["سَيِّئَةٌۭ","teruk"],["يَطَّيَّرُوا۟","mereka menganggap petanda yang jahat"],["بِمُوسَىٰ","kepada Musa"],["وَمَن","dan siapa"],["مَّعَهُۥٓ ۗ","(ada) bersamanya"],["أَلَآ","Lihatlah"],["إِنَّمَا","Hanya"],["طَـٰٓئِرُهُمْ","petanda jahat mereka"],["عِندَ","(ada) dengan"],["ٱللَّهِ","Allah"],["وَلَـٰكِنَّ","tetapi"],["أَكْثَرَهُمْ","kebanyakan mereka"],["لَا","jangan"],["يَعْلَمُونَ","mengetahui"]]],"1086":["(Dan mereka berkata,) kepada Musa (\"Bagaimana kamu mendatangkan keterangan kepada kami untuk menyihir kami dengan keterangan itu, maka kami sekali-kali tidak akan beriman kepadamu.\") kemudian Musa berdoa agar mereka diberi pelajaran.",[["وَقَالُوا۟","Dan mereka berkata"],["مَهْمَا","apapun"],["تَأْتِنَا","kamu bawa kami"],["بِهِۦ","dengan itu"],["مِنْ","daripada"],["ءَايَةٍۢ","(tanda)."],["لِّتَسْحَرَنَا","supaya kamu menyihir kami"],["بِهَا","dengannya"],["فَمَا","maka tidak"],["نَحْنُ","kita"],["لَكَ","(akan ada) dalam diri kamu"],["بِمُؤْمِنِينَ","orang yang beriman"]]],"1087":["(Maka Kami kirimkan kepada mereka taufan) yaitu air bah yang memasuki rumah-rumah mereka sehingga mencapai setinggi tempat pesanggrahan duduk mereka selama tujuh hari (belalang) kemudian belalang itu memakan persawahan dan buah-buahan milik mereka, demikian pula (kutu) ulat atau sejenis serangga yang memakan apa yang ditinggalkan oleh belalang (katak) kemudian katak itu memenuhi rumah-rumah mereka dan juga makanan-makanan mereka (dan darah) di dalam air milik mereka (sebagai bukti-bukti yang jelas) yang terang (tetapi mereka tetap menyombongkan diri) tidak mau beriman kepada bukti-bukti tersebut (dan mereka adalah kaum yang berdosa).",[["فَأَرْسَلْنَا","Maka Kami hantarkan"],["عَلَيْهِمُ","ke atas mereka"],["ٱلطُّوفَانَ","banjir"],["وَٱلْجَرَادَ","dan belalang"],["وَٱلْقُمَّلَ","dan kutu"],["وَٱلضَّفَادِعَ","dan katak"],["وَٱلدَّمَ","dan darah"],["ءَايَـٰتٍۢ","(sebagai) tanda"],["مُّفَصَّلَـٰتٍۢ","nyata"],["فَٱسْتَكْبَرُوا۟","tetapi mereka menunjukkan kesombongan"],["وَكَانُوا۟","dan mereka"],["قَوْمًۭا","suatu kaum"],["مُّجْرِمِينَ","penjenayah"]]],"1088":["(Dan ketika mereka ditimpa azab) yaitu siksaan (mereka pun berkata, \"Hai Musa! Mohonkanlah untuk kami kepada Tuhanmu dengan perantaraan kenabian yang diketahui Allah ada pada sisimu) yang dapat menghilangkan azab dari kami jika kami beriman (Sesungguhnya jika) lam adalah bermakna qasam/sumpah (kamu dapat menghilangkan azab itu dari kami, pasti kami akan beriman kepadamu dan akan kami biarkan Bani Israel pergi bersamamu.\").",[["وَلَمَّا","Dan apabila"],["وَقَعَ","jatuh"],["عَلَيْهِمُ","ke atas mereka"],["ٱلرِّجْزُ","azab"],["قَالُوا۟","mereka berkata"],["يَـٰمُوسَى","Wahai Musa"],["ٱدْعُ","Ajak"],["لَنَا","bagi kami"],["رَبَّكَ","Tuhanmu"],["بِمَا","oleh apa"],["عَهِدَ","Dia telah berjanji"],["عِندَكَ ۖ","kepada kamu"],["لَئِن","Jika"],["كَشَفْتَ","kamu keluarkan"],["عَنَّا","daripada kami"],["ٱلرِّجْزَ","azab"],["لَنُؤْمِنَنَّ","nescaya, kami akan beriman"],["لَكَ","[untuk] kamu"],["وَلَنُرْسِلَنَّ","dan pasti, kami akan hantar"],["مَعَكَ","bersama kamu"],["بَنِىٓ","(the) Kanak-kanak"],["إِسْرَٰٓءِيلَ","(dari) Israel"]]],"1089":["(Maka setelah Kami hilangkan) berkat doa Musa (dari mereka azab itu hingga batas waktu yang mereka sampai kepadanya, tiba-tiba mereka mengingkarinya) janjinya dan bersikeras melakukan kekafiran.",[["فَلَمَّا","Tetapi apabila"],["كَشَفْنَا","Kami mengeluarkan"],["عَنْهُمُ","daripada mereka"],["ٱلرِّجْزَ","azab"],["إِلَىٰٓ","sehingga"],["أَجَلٍ","istilah (tetap)."],["هُم","(yang) mereka"],["بَـٰلِغُوهُ","harus mencapai [itu]"],["إِذَا","kemudian"],["هُمْ","mereka"],["يَنكُثُونَ","pecah (perkataan)"]]],"1090":["(Kemudian Kami menghukum mereka, maka Kami tenggelamkan mereka di laut) laut yang airnya asin (disebabkan mereka) dikarenakan mereka (mendustakan ayat-ayat Kami dan mereka adalah orang-orang yang melalaikan ayat-ayat Kami) tetapi mereka tidak mau memikirkannya.",[["فَٱنتَقَمْنَا","Maka Kami mengambil pembalasan"],["مِنْهُمْ","daripada mereka"],["فَأَغْرَقْنَـٰهُمْ","dan Kami tenggelamkan mereka"],["فِى","dalam"],["ٱلْيَمِّ","laut"],["بِأَنَّهُمْ","kerana mereka"],["كَذَّبُوا۟","dinafikan"],["بِـَٔايَـٰتِنَا","Tanda-Tanda Kami"],["وَكَانُوا۟","dan mereka"],["عَنْهَا","kepada mereka"],["غَـٰفِلِينَ","lalai"]]],"1091":["(Dan Kami pusakakan kepada kaum yang telah ditindas itu) melalui perbudakan, yaitu mereka adalah kaum Bani Israel (negeri-negeri bagian timur dan bagian baratnya yang telah Kami beri berkah padanya) dengan air dan pohon, ini adalah kata sifat bagi tanah, yang dimaksud adalah tanah Syam (Dan telah sempurnalah perkataan Tuhanmu yang baik) yang dimaksud ialah firman-Nya, \"Dan Kami hendak memberi karunia kepada orang-orang yang tertindas di bumi, Mesir, itu.\" (Q.S. Al-Qashash 5) (untuk Bani Israel disebabkan kesabaran mereka) di dalam menanggung penganiayaan musuh mereka (dan Kami hancurkan) Kami binasakan (apa-apa yang telah dibuat Firaun dan kaumnya) bangunan-bangunannya (dan apa yang telah dibangun mereka) dengan mengkasrahkan ra-nya dan boleh juga didamahkan, yakni bangunan-bangunan yang telah mereka tinggikan.",[["وَأَوْرَثْنَا","Dan Kami jadikan orang-orang yang mewarisi"],["ٱلْقَوْمَ","manusia"],["ٱلَّذِينَ","orang yang"],["كَانُوا۟","adalah"],["يُسْتَضْعَفُونَ","dianggap lemah"],["مَشَـٰرِقَ","(bahagian) timur (bahagian)"],["ٱلْأَرْضِ","(dari) tanah itu"],["وَمَغَـٰرِبَهَا","dan bahagian baratnya"],["ٱلَّتِى","yang"],["بَـٰرَكْنَا","Kami memberkati"],["فِيهَا ۖ","[di dalamnya]"],["وَتَمَّتْ","Dan telah dipenuhi"],["كَلِمَتُ","(perkataan)."],["رَبِّكَ","(dari) Tuhanmu"],["ٱلْحُسْنَىٰ","yang terbaik"],["عَلَىٰ","bagi"],["بَنِىٓ","(the) Kanak-kanak"],["إِسْرَٰٓءِيلَ","(dari) Israel"],["بِمَا","kerana"],["صَبَرُوا۟ ۖ","mereka bersabar"],["وَدَمَّرْنَا","Dan Kami binasakan"],["مَا","apa"],["كَانَ","dulu"],["يَصْنَعُ","buat"],["فِرْعَوْنُ","Firaun"],["وَقَوْمُهُۥ","dan umatnya"],["وَمَا","dan apa"],["كَانُوا۟","mereka dahulu"],["يَعْرِشُونَ","tegak"]]],"1092":["(Dan Kami seberangkan) Kami lewatkan (Bani Israel ke seberang lautan itu, maka setelah mereka sampai) mereka lewat (pada suatu kaum yang tetap menyembah) dengan dibaca damah atau kasrah huruf kaf-nya (berhala mereka) mereka masih tetap menyembah berhala-berhala itu (Bani Israel berkata, \"Hai Musa! Buatlah untuk kami sebuah tuhan) berhala yang akan kami sembah (sebagaimana mereka mempunyai beberapa tuhan, berhala.\" Musa menjawab, \"Sesungguhnya kamu ini adalah kaum yang bodoh.\") karena kamu membalas karunia Allah atas kamu dengan apa yang tadi kamu katakan.",[["وَجَـٰوَزْنَا","Dan Kami memimpin seberang"],["بِبَنِىٓ","(the) Kanak-kanak"],["إِسْرَٰٓءِيلَ","(dari) Israel"],["ٱلْبَحْرَ","laut"],["فَأَتَوْا۟","Kemudian mereka datang"],["عَلَىٰ","ke atas"],["قَوْمٍۢ","suatu kaum"],["يَعْكُفُونَ","berbakti"],["عَلَىٰٓ","kepada"],["أَصْنَامٍۢ","berhala"],["لَّهُمْ ۚ","daripada mereka"],["قَالُوا۟","Mereka berkata"],["يَـٰمُوسَى","Wahai Musa"],["ٱجْعَل","buat"],["لَّنَآ","bagi kami"],["إِلَـٰهًۭا","tuhan"],["كَمَا","macam apa"],["لَهُمْ","mereka ada"],["ءَالِهَةٌۭ ۚ","tuhan"],["قَالَ","Dia berkata"],["إِنَّكُمْ","Sesungguhnya kamu"],["قَوْمٌۭ","(adalah) suatu kaum"],["تَجْهَلُونَ","jahil"]]],"1093":["(Sesungguhnya mereka itu akan dihancurkan) dibinasakan (kepercayaan yang dianutnya dan akan batal apa yang selalu mereka kerjakan).",[["إِنَّ","Sesungguhnya"],["هَـٰٓؤُلَآءِ","ini"],["مُتَبَّرٌۭ","musnah"],["مَّا","(ialah) apa"],["هُمْ","mereka"],["فِيهِ","(ada) di dalamnya"],["وَبَـٰطِلٌۭ","dan sia-sia"],["مَّا","(ialah) apa"],["كَانُوا۟","mereka dahulu"],["يَعْمَلُونَ","lakukan"]]],"1094":["(Musa menjawab, \"Patutkah aku mencari Tuhan untuk kamu yang selain daripada Allah?\") yakni sesembahan; pada asalnya lafal abghiikum itu ialah abghii lakum (padahal Dialah yang telah melebihkan kamu atas segala umat) di zaman kamu sesuai dengan apa yang dituturkan dalam firman-Nya berikut ini.",[["قَالَ","Dia berkata"],["أَغَيْرَ","Sepatutnya selain daripada"],["ٱللَّهِ","Allah"],["أَبْغِيكُمْ","Aku mencari kamu"],["إِلَـٰهًۭا","tuhan"],["وَهُوَ","manakala Dia"],["فَضَّلَكُمْ","telah mengutamakan kamu"],["عَلَى","atas"],["ٱلْعَـٰلَمِينَ","dunia"]]],"1095":["(Dan) ingatlah kamu (ketika Kami menyelamatkan kamu) dan menurut suatu qiraat dibaca anjaakum (dari Firaun dan kaumnya yang mengazab kamu) mereka menyiksa dan menganiaya kamu (dengan azab yang sangat jahat) yakni siksaan/azab yang paling keras, yaitu dalam bentuk (yaitu mereka membunuh anak-anak lelakimu dan membiarkan hidup) tidak membunuh (wanita-wanitamu. Dan pada yang demikian itu) penyelamatan dan siksaan (cobaan) pemberian nikmat dan ujian (dari Tuhanmu, yaitu cobaan yang besar) maka apakah kamu tidak mau mengambil pelajaran darinya sehingga kamu berhenti dari apa yang kamu katakan itu.",[["وَإِذْ","Dan apabila"],["أَنجَيْنَـٰكُم","Kami selamatkan kamu"],["مِّنْ","daripada"],["ءَالِ","kaum"],["فِرْعَوْنَ","(daripada) Firaun"],["يَسُومُونَكُمْ","yang menyusahkan kamu"],["سُوٓءَ","(dengan) paling teruk"],["ٱلْعَذَابِ ۖ","(dari) siksaan"],["يُقَتِّلُونَ","mereka membunuh"],["أَبْنَآءَكُمْ","anak lelaki kamu"],["وَيَسْتَحْيُونَ","dan membiarkan hidup"],["نِسَآءَكُمْ ۚ","wanita kamu"],["وَفِى","Dan dalam"],["ذَٰلِكُم","bahawa"],["بَلَآءٌۭ","(adalah) percubaan"],["مِّن","daripada"],["رَّبِّكُمْ","Tuhanmu"],["عَظِيمٌۭ","yang besar"]]],"1096":["(Dan telah Kami janjikan) dengan memakai alif dan tidak memakainya (kepada Musa sesudah berlalu waktu tiga puluh malam) di mana Kami akan berbicara kepadanya seusai masa tersebut agar ia berpuasa terlebih dahulu; masa itu adalah bulan Zulkaidah kemudian Musa berpuasa dan tatkala ia selesai, bau mulutnya masih kurang enak. Akhirnya Musa bersiwak dan Allah swt. memerintahkannya agar melakukan puasa sepuluh hari lagi agar ia dapat berbicara dengan-Nya melalui mulutnya; hal ini telah dijelaskan dalam firman Allah swt. (dan Kami sempurnakan jumlah malam itu dengan sepuluh malam lagi) yakni dari bulan Zulhijah (maka sempurnalah waktu yang telah ditentukan Tuhannya) yaitu waktu yang telah dijanjikan oleh-Nya untuk berbicara dengan-Nya (empat puluh) menjadi hal (malam) menjadi tamyiz. (Dan berkata Musa kepada saudaranya, yaitu Harun) di kala hendak pergi ke bukit untuk bermunajat (\"Gantikanlah aku) maksudnya jadilah engkau sebagai penggantiku (dalam memimpin kaumku dan perbaikilah\") perkara mereka (dan janganlah kamu mengikuti jalan orang-orang yang membuat kerusakan) dengan menyetujui mereka berbuat kemaksiatan.",[["۞ وَوَٰعَدْنَا","Dan Kami tetapkan"],["مُوسَىٰ","(untuk) Musa"],["ثَلَـٰثِينَ","tiga puluh"],["لَيْلَةًۭ","malam-malam"],["وَأَتْمَمْنَـٰهَا","dan Kami sempurnakan mereka"],["بِعَشْرٍۢ","dengan sepuluh (lebih)"],["فَتَمَّ","jadi selesai"],["مِيقَـٰتُ","(the) jangka masa yang ditetapkan"],["رَبِّهِۦٓ","(dari) Tuhannya"],["أَرْبَعِينَ","(daripada) empat puluh"],["لَيْلَةًۭ ۚ","malam"],["وَقَالَ","Dan berkata"],["مُوسَىٰ","Musa"],["لِأَخِيهِ","kepada abangnya"],["هَـٰرُونَ","Harun"],["ٱخْلُفْنِى","Ambil tempat aku"],["فِى","dalam"],["قَوْمِى","bangsaku"],["وَأَصْلِحْ","dan buat yang betul"],["وَلَا","dan jangan"],["تَتَّبِعْ","ikut"],["سَبِيلَ","jalan"],["ٱلْمُفْسِدِينَ","(dari) para perasuah"]]],"1097":["(Dan tatkala Musa datang untuk munajat dengan Kami pada waktu yang telah Kami tentukan) waktu yang telah Kami janjikan kepadanya akan berbicara dengannya pada waktu itu (dan Tuhan telah berfirman kepadanya) tanpa perantara dengan pembicaraan yang dapat Musa dengar dari segala penjuru (berkatalah Musa, \"Ya Tuhanku! Tampakkanlah kepadaku) diri Engkau (agar aku dapat melihat-Mu.\" Tuhan berfirman, \"Kamu sekali-kali tidak sanggup melihat-Ku) artinya kamu tidak akan mampu melihat-Ku; bila hal itu diungkapkan bukan dengan memakai huruf lan, maka pengertiannya berarti melihat Tuhan itu mungkin dapat dilakukan (tetapi lihatlah kepada bukit itu) yang bangunannya lebih kuat daripada dirimu (maka jika ia tetap) tegak seperti sediakala (pada tempatnya, niscaya kamu dapat melihat-Ku\") engkau dapat melihat-Ku dan jika tidak, maka niscaya kamu tidak akan kuat (Tatkala Tuhannya tampak) yakni sebagian dari nur-Nya yang hanya sebesar setengah jari manis, demikianlah menurut penjelasan dari hadis yang telah diriwayatkan oleh Al-Hakim (bagi gunung itu, kejadian itu menjadikan gunung itu hancur luluh) dengan dibaca qashr atau pendek dan panjang, yakni gunung itu menjadi lebur rata dengan tanah (dan Musa jatuh pingsan) tak sadarkan diri karena sangat terkejut melihat apa yang ia saksikan (Maka setelah Musa sadar kembali, dia berkata, \"Maha Suci Engkau) dengan memahasucikan Engkau (aku bertobat kepada Engkau) dari permintaan yang aku tidak diperintahkan mengemukakannya (dan aku orang yang pertama-tama beriman\") pada zamanku ini.",[["وَلَمَّا","Dan apabila"],["جَآءَ","datang"],["مُوسَىٰ","Musa"],["لِمِيقَـٰتِنَا","ke tempat yang Kami tetapkan"],["وَكَلَّمَهُۥ","dan bercakap dengannya"],["رَبُّهُۥ","Tuhannya"],["قَالَ","dia berkata"],["رَبِّ","Wahai Tuhanku"],["أَرِنِىٓ","Tunjukkan aku"],["أَنظُرْ","(yang) aku boleh lihat"],["إِلَيْكَ ۚ","pada Kamu"],["قَالَ","Dia berkata"],["لَن","tidak pernah"],["تَرَىٰنِى","kamu (boleh) melihat Aku"],["وَلَـٰكِنِ","tetapi"],["ٱنظُرْ","tengok"],["إِلَى","di"],["ٱلْجَبَلِ","gunung itu"],["فَإِنِ","[maka] jika"],["ٱسْتَقَرَّ","ia kekal"],["مَكَانَهُۥ","di tempatnya"],["فَسَوْفَ","kemudian"],["تَرَىٰنِى ۚ","kamu (akan) melihat Aku"],["فَلَمَّا","Tetapi apabila"],["تَجَلَّىٰ","menyatakan Kemuliaan (Nya)."],["رَبُّهُۥ","Tuhannya"],["لِلْجَبَلِ","ke gunung"],["جَعَلَهُۥ","Dia berjaya"],["دَكًّۭا","hancur menjadi debu"],["وَخَرَّ","dan jatuh"],["مُوسَىٰ","Musa"],["صَعِقًۭا ۚ","tak sedar diri"],["فَلَمَّآ","Dan apabila"],["أَفَاقَ","dia pulih"],["قَالَ","dia berkata"],["سُبْحَـٰنَكَ","Maha Suci Engkau"],["تُبْتُ","Aku berpaling (dalam taubat)"],["إِلَيْكَ","kepada kamu"],["وَأَنَا۠","dan aku"],["أَوَّلُ","(yang) pertama"],["ٱلْمُؤْمِنِينَ","(dari) orang-orang yang beriman"]]],"1098":["(Allah berfirman,) Maha Tinggi Allah (\"Hai Musa, sesungguhnya Aku memilih melebihkan kamu) yakni Aku memilihmu (dari manusia) yang hidup di masamu (untuk membawa risalah-Ku) dengan memakai jamak dan mufrad/tunggal (dan untuk berbicara langsung dengan-Ku) Aku berbicara kepadamu secara langsung (sebab itu berpegang teguhlah kepada apa yang Aku berikan kepadamu) berupa keutamaan (dan hendaklah kamu termasuk orang-orang yang bersyukur\") atas nikmat-nikmat-Ku.",[["قَالَ","Dia berkata"],["يَـٰمُوسَىٰٓ","Wahai Musa"],["إِنِّى","Sesungguhnya aku"],["ٱصْطَفَيْتُكَ","telah memilih kamu"],["عَلَى","atas"],["ٱلنَّاسِ","manusia"],["بِرِسَـٰلَـٰتِى","dengan Mesej Aku"],["وَبِكَلَـٰمِى","dan dengan firman-Ku"],["فَخُذْ","Jadi ambil"],["مَآ","apa"],["ءَاتَيْتُكَ","Aku telah memberikan kamu"],["وَكُن","dan jadilah"],["مِّنَ","antara"],["ٱلشَّـٰكِرِينَ","yang bersyukur"]]],"1099":["(Dan telah Kami tuliskan untuk Musa pada lempengan-lempengan) lempengan-lempengan kitab Taurat yang terdiri dari dedaunan surga, atau dari zabarjad atau dari tujuh jenis atau sepuluh jenis zamrud (segala sesuatu) yang diperlukan di dalam menyampaikan agama (sebagai pelajaran dan penjelasan) keterangan (bagi segala sesuatu) menjadi badal dari jar dan majrur sebelumnya. (Maka berpeganglah kepadanya) sebelumnya terdapat kalimat Kami berfirman yang ditakdirkan/yang diperkirakan keberadaannya (dengan teguh) dengan sungguh-sungguh dan dengan segala kemampuan (dan suruhlah kaummu berpegang kepadanya dengan sebaik-baiknya, nanti Aku akan memperlihatkan kepadamu negeri orang-orang yang fasik) yakni Firaun beserta para pengikutnya, yaitu negeri Mesir, supaya kamu mengambil pelajaran darinya.",[["وَكَتَبْنَا","Dan Kami tetapkan (hukum)"],["لَهُۥ","baginya"],["فِى","dalam"],["ٱلْأَلْوَاحِ","tablet itu"],["مِن","daripada"],["كُلِّ","setiap"],["شَىْءٍۢ","perkara"],["مَّوْعِظَةًۭ","suatu arahan"],["وَتَفْصِيلًۭا","dan penerangan"],["لِّكُلِّ","untuk setiap"],["شَىْءٍۢ","perkara"],["فَخُذْهَا","Jadi ambil mereka"],["بِقُوَّةٍۢ","dengan ketegasan"],["وَأْمُرْ","dan pesanan"],["قَوْمَكَ","orang kamu"],["يَأْخُذُوا۟","(untuk) mengambil"],["بِأَحْسَنِهَا ۚ","(yang) terbaik daripadanya"],["سَأُو۟رِيكُمْ","Aku akan tunjukkan kepada kamu"],["دَارَ","(rumah)"],["ٱلْفَـٰسِقِينَ","(dari) orang-orang yang durhaka"]]],"1100":["(Aku akan memalingkan dari ayat-ayat-Ku) dari bukti-bukti yang menunjukkan kekuasaan-Ku, yaitu berupa hasil-hasil ciptaan-Ku dan lain-lainnya (orang-orang yang menyombongkan dirinya di muka bumi tanpa alasan yang benar) yaitu Aku akan menjadikan mereka terhina sehingga tidak lagi mereka berlaku sombong di muka bumi (jika mereka melihat tiap-tiap ayat-Ku, mereka tidak beriman kepadanya. Dan jika mereka melihat jalan) yakni titian (yang membawa kepada petunjuk) hidayah yang datang dari sisi Tuhan (mereka tidak mau menjalankannya sebagai jalan hidup) yang mereka tempuh (tetapi jika mereka melihat jalan kesesatan) jalan yang salah (mereka terus menempuhnya. Yang demikian itu) berpalingnya mereka itu (adalah karena mereka mendustakan ayat-ayat Kami dan mereka selalu lalai daripadanya) contoh mengenai mereka telah disebutkan.",[["سَأَصْرِفُ","Aku akan berpaling"],["عَنْ","daripada"],["ءَايَـٰتِىَ","Tanda-tanda Aku"],["ٱلَّذِينَ","orang yang"],["يَتَكَبَّرُونَ","adalah sombong"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["بِغَيْرِ","tanpa"],["ٱلْحَقِّ","[yang] betul"],["وَإِن","dan jika"],["يَرَوْا۟","mereka lihat"],["كُلَّ","setiap"],["ءَايَةٍۢ","tanda"],["لَّا","tidak"],["يُؤْمِنُوا۟","(akan) mereka beriman"],["بِهَا","di dalamnya"],["وَإِن","Dan jika"],["يَرَوْا۟","mereka lihat"],["سَبِيلَ","jalan"],["ٱلرُّشْدِ","(dari) kebenaran"],["لَا","tidak"],["يَتَّخِذُوهُ","(akan) mereka mengambilnya"],["سَبِيلًۭا","(sebagai) jalan"],["وَإِن","tetapi jika"],["يَرَوْا۟","mereka lihat"],["سَبِيلَ","jalan"],["ٱلْغَىِّ","(daripada) kesilapan"],["يَتَّخِذُوهُ","mereka akan mengambilnya"],["سَبِيلًۭا ۚ","(sebagai) jalan"],["ذَٰلِكَ","Itu"],["بِأَنَّهُمْ","(adalah) kerana mereka"],["كَذَّبُوا۟","dinafikan"],["بِـَٔايَـٰتِنَا","Tanda-Tanda Kami"],["وَكَانُوا۟","dan mereka"],["عَنْهَا","daripada mereka"],["غَـٰفِلِينَ","lalai"]]],"1101":["(Dan orang-orang yang mendustakan ayat-ayat Kami dan mendustakan akan menemui akhirat) dimaksud mengenai hari berbangkit dan lain-lainnya (sia-sialah) artinya batillah (perbuatan mereka) yaitu perbuatan-perbuatan yang telah mereka lakukan sewaktu hidup di alam dunia, berupa amal-amal kebaikan seperti silaturahmi dan sedekah, maka mereka tidak lagi mendapat pahalanya karena persyaratannya sudah tidak memenuhi lagi (Tidak) (mereka itu mendapat balasan kecuali) hanya balasan (apa yang telah mereka kerjakan) yakni perbuatan mendustakan ayat-ayat Kami dan perbuatan-perbuatan maksiat.",[["وَٱلَّذِينَ","Dan orang yang"],["كَذَّبُوا۟","dinafikan"],["بِـَٔايَـٰتِنَا","Tanda-Tanda Kami"],["وَلِقَآءِ","dan (the) mesyuarat"],["ٱلْـَٔاخِرَةِ","(dari) Akhirat"],["حَبِطَتْ","tidak bernilai"],["أَعْمَـٰلُهُمْ ۚ","(adalah) perbuatan mereka"],["هَلْ","akan"],["يُجْزَوْنَ","mereka mendapat balasan"],["إِلَّا","kecuali"],["مَا","(untuk) apa"],["كَانُوا۟","mereka dahulu"],["يَعْمَلُونَ","lakukan"]]],"1102":["(Dan kaum Musa, setelah kepergian Musa, mereka membuat) setelah pergi meninggalkan mereka untuk bermunajat (dari perhiasan mereka) yang telah mereka pinjam dari kaumnya Firaun dengan alasan untuk perkawinan (berhala) yang kemudian dipuja-puja oleh mereka (anak lembu) Samirilah yang mencetaknya berdasarkan permintaan mereka (yang bertubuh) sebagai ganti dari daging dan darah (dan bersuara) artinya suara yang dapat didengar; dan dapat bergerak sebab Samiri menaruh debu di mulutnya dari bekas teracak kuda malaikat Jibril, sebagai pengaruhnya berhala itu dapat hidup. Maf'ul dari lafal ittakhadza dibuang yang asalnya ialah lafal ilaahan, yakni sebagai tuhan. (Apakah mereka tidak mengetahui bahwa anak lembu itu tidak dapat berbicara dengan mereka dan tidak dapat pula menunjukkan jalan kepada mereka?) lalu mengapa mereka menganggapnya sebagai tuhan mereka (Mereka menjadikannya) sebagai sesembahan (dan mereka adalah orang-orang yang lalim) disebabkan mengambilnya sebagai sesembahan.",[["وَٱتَّخَذَ","Dan mengambil"],["قَوْمُ","kaum"],["مُوسَىٰ","(dari) Musa"],["مِنۢ","daripada"],["بَعْدِهِۦ","selepas dia"],["مِنْ","daripada"],["حُلِيِّهِمْ","perhiasan mereka"],["عِجْلًۭا","seekor anak lembu"],["جَسَدًۭا","sebuah imej"],["لَّهُۥ","[untuk] itu"],["خُوَارٌ ۚ","(mempunyai) bunyi merendah"],["أَلَمْ","tidak"],["يَرَوْا۟","mereka lihat"],["أَنَّهُۥ","bahawa ia"],["لَا","(boleh) tidak"],["يُكَلِّمُهُمْ","bercakap dengan mereka"],["وَلَا","dan bukan"],["يَهْدِيهِمْ","membimbing mereka"],["سَبِيلًا ۘ","(ke) jalan"],["ٱتَّخَذُوهُ","Mereka mengambilnya (untuk disembah)"],["وَكَانُوا۟","dan mereka"],["ظَـٰلِمِينَ","orang yang zalim"]]],"1103":["(Dan setelah mereka menyesali perbuatannya) mereka menyesal mengambil sebagai sesembahan mereka (dan mereka melihat) mereka mengetahui (bahwa mereka telah sesat) oleh sebab perbuatan itu; penyesalan itu datang setelah Musa kembali kepada mereka (mereka pun berkata, \"Sungguh jika Tuhan kami tidak memberi rahmat kepada kami dan tidak mengampuni kami) dengan memakai ya dan ta pada kedua fi'ilnya (pastilah kami menjadi orang-orang yang merugi.\").",[["وَلَمَّا","Dan apabila"],["سُقِطَ","(ia dibuat untuk) jatuh"],["فِىٓ","ke dalam"],["أَيْدِيهِمْ","tangan mereka"],["وَرَأَوْا۟","dan mereka melihat"],["أَنَّهُمْ","bahawa mereka"],["قَدْ","(mempunyai) sesungguhnya"],["ضَلُّوا۟","sesat"],["قَالُوا۟","mereka berkata"],["لَئِن","Jika"],["لَّمْ","tidak"],["يَرْحَمْنَا","telah mengasihani kami"],["رَبُّنَا","Wahai Tuhan kami"],["وَيَغْفِرْ","dan memaafkan"],["لَنَا","[untuk] kita"],["لَنَكُونَنَّ","kita pasti akan jadi"],["مِنَ","antara"],["ٱلْخَـٰسِرِينَ","yang rugi"]]],"1104":["(Dan tatkala Musa kembali kepada kaumnya dalam keadaan marah) oleh sebab perbuatan mereka (dan sedih hati) yakni amat bersedih hati (berkatalah dia,) kepada mereka (\"Alangkah buruknya perbuatan) teramat jelek perbuatan (yang kamu kerjakan) dalam hal ini (sesudah kepergianku!) dimaksud pekerjaanmu ini di mana kamu berlaku musyrik. (Apakah kamu hendak mendahului janji Tuhanmu?\" Dan Musa pun melemparkan lempengan-lempengan) yaitu lempengan-lempengan Kitab Taurat karena marah kepada kaumnya, sehingga lempengan-lempengan itu pecah (dan ia memegang rambut kepala saudaranya) dengan tangan kanannya dan jenggotnya dengan tangan kirinya (sambil menariknya ke arahnya) saking marahnya (Harun berkata,) \"Hai (anak ibuku!) dengan mim dikasrahkan dan difathahkan, yang dimaksud adalah ummi, penyebutan dengan kata-kata ini untuk lebih menimbulkan rasa sayang ke dalam hati Musa (Sesungguhnya kaum ini telah menganggapku lemah dan hampir-hampir mereka) hampir saja (membunuhku, sebab itu janganlah kamu menjadikan gembira) membuat girang (musuh-musuh melihatku) karena kamu menghinakan diriku (dan janganlah kamu masukkan aku ke dalam golongan orang-orang yang lalim.\") sebagaimana engkau memperlakukan orang yang benar-benar menyembah anak sapi.",[["وَلَمَّا","Dan apabila"],["رَجَعَ","dikembalikan"],["مُوسَىٰٓ","Musa"],["إِلَىٰ","kepada"],["قَوْمِهِۦ","umatnya"],["غَضْبَـٰنَ","marah"],["أَسِفًۭا","dan bersedih"],["قَالَ","dia berkata"],["بِئْسَمَا","Jahat itu apa"],["خَلَفْتُمُونِى","kamu telah lakukan di tempat aku"],["مِنۢ","daripada"],["بَعْدِىٓ ۖ","selepas aku"],["أَعَجِلْتُمْ","Adakah kamu tidak sabar"],["أَمْرَ","(atas) perkara"],["رَبِّكُمْ ۖ","Tuhanmu"],["وَأَلْقَى","Dan dia melemparkan"],["ٱلْأَلْوَاحَ","tablet itu"],["وَأَخَذَ","dan dirampas"],["بِرَأْسِ","dengan kepala"],["أَخِيهِ","abangnya"],["يَجُرُّهُۥٓ","mengheret dia"],["إِلَيْهِ ۚ","kepada dirinya sendiri"],["قَالَ","Dia berkata"],["ٱبْنَ","Wahai anak"],["أُمَّ","(daripada) ibu aku"],["إِنَّ","Sesungguhnya"],["ٱلْقَوْمَ","manusia"],["ٱسْتَضْعَفُونِى","menganggap aku lemah"],["وَكَادُوا۟","dan akan"],["يَقْتُلُونَنِى","bunuh aku"],["فَلَا","Jadi (biar) jangan"],["تُشْمِتْ","bergembiralah"],["بِىَ","atas aku"],["ٱلْأَعْدَآءَ","musuh-musuh"],["وَلَا","dan jangan"],["تَجْعَلْنِى","letak aku"],["مَعَ","dengan"],["ٱلْقَوْمِ","manusia"],["ٱلظَّـٰلِمِينَ","(yang) melakukan kesalahan"]]],"1105":["(Musa berdoa, \"Ya Tuhanku! Ampunilah aku) atas apa yang telah kuperbuat terhadap saudaraku (dan saudaraku) Musa menyertakan saudaranya dalam doa demi untuk membuatnya rela atas apa yang telah ia lakukan kepadanya dan sekaligus untuk menolak agar musuh jangan girang melihat sikapnya terhadap saudaranya itu (dan masukkanlah kami ke dalam rahmat Engkau, dan Engkau adalah Maha Penyayang di antara para penyayang.\") Allah berfirman,",[["قَالَ","Dia berkata"],["رَبِّ","Wahai Tuhanku"],["ٱغْفِرْ","maafkan"],["لِى","aku"],["وَلِأَخِى","dan abang aku"],["وَأَدْخِلْنَا","dan mengakui kami"],["فِى","ke dalam"],["رَحْمَتِكَ ۖ","Kerahiman-Mu"],["وَأَنتَ","untuk kamu"],["أَرْحَمُ","(adalah) Yang Maha Penyayang"],["ٱلرَّٰحِمِينَ","(dari) yang penyayang"]]],"1106":["(\"Sesungguhnya orang-orang yang menjadikan anak lembu) sebagai sesembahan (kelak akan menimpa mereka kemurkaan) yakni azab (dari Tuhan mereka dan kehinaan dalam kehidupan di dunia) maka mereka dihukum dengan perintah agar mereka membunuh diri mereka sendiri dan kehinaan akan selalu menimpa mereka sampai hari kiamat nanti. (Demikianlah) seperti apa yang telah Kami balaskan kepada mereka (Kami memberi balasan kepada orang-orang yang membuat-buat kebohongan) terhadap Allah dengan melakukan perbuatan syirik dan lain-lainnya.",[["إِنَّ","Sesungguhnya"],["ٱلَّذِينَ","orang yang"],["ٱتَّخَذُوا۟","mengambil"],["ٱلْعِجْلَ","anak lembu itu"],["سَيَنَالُهُمْ","akan sampai kepada mereka"],["غَضَبٌۭ","kemarahan"],["مِّن","daripada"],["رَّبِّهِمْ","Tuhan mereka"],["وَذِلَّةٌۭ","dan penghinaan"],["فِى","dalam"],["ٱلْحَيَوٰةِ","kehidupan"],["ٱلدُّنْيَا ۚ","dunia"],["وَكَذَٰلِكَ","Dan dengan demikian"],["نَجْزِى","Kami membalas"],["ٱلْمُفْتَرِينَ","orang-orang yang mengada-adakan (kebohongan)"]]],"1107":["(Dan orang-orang yang mengerjakan kejahatan; kemudian bertobat) kembali tidak melakukannya (sesudah itu dan beriman) terhadap Allah (sesungguhnya Tuhan kamu sesudahnya) sesudah tobat (adalah Maha Pengampun) kepada mereka (lagi Maha Penyayang\").",[["وَٱلَّذِينَ","Dan orang yang"],["عَمِلُوا۟","lakukan"],["ٱلسَّيِّـَٔاتِ","perbuatan jahat itu"],["ثُمَّ","kemudian"],["تَابُوا۟","bertaubat"],["مِنۢ","daripada"],["بَعْدِهَا","selepas itu"],["وَءَامَنُوٓا۟","dan beriman"],["إِنَّ","sesungguhnya"],["رَبَّكَ","Tuhanmu"],["مِنۢ","daripada"],["بَعْدِهَا","selepas itu"],["لَغَفُورٌۭ","(adalah) sesungguhnya Maha Pengampun"],["رَّحِيمٌۭ","Maha Mengasihani"]]],"1108":["(Sesudah mereda) telah tenang (amarah Musa, lalu diambilnya kembali lempengan-lempengan itu) yang telah ia banting itu (dan dalam tulisannya) apa yang tertulis di dalam lempengan kitab Taurat itu (terdapat petunjuk) dari kesesatan (dan rahmat untuk orang-orang yang takut kepada Tuhannya) mereka takut kepada-Nya; huruf lam dimasukkan ke dalam maf'ul mengingat tempatnya yang didahulukan.",[["وَلَمَّا","Dan apabila"],["سَكَتَ","telah ditenangkan"],["عَن","daripada"],["مُّوسَى","Musa"],["ٱلْغَضَبُ","kemarahan itu"],["أَخَذَ","dia mengambil (naik)"],["ٱلْأَلْوَاحَ ۖ","tablet itu"],["وَفِى","dan dalam"],["نُسْخَتِهَا","inskripsi mereka"],["هُدًۭى","(adalah) petunjuk"],["وَرَحْمَةٌۭ","dan belas kasihan"],["لِّلَّذِينَ","bagi mereka yang"],["هُمْ","[mereka]"],["لِرَبِّهِمْ","dari Tuhan mereka"],["يَرْهَبُونَ","(adalah) takut"]]],"1109":["(Dan Musa memilih dari kaumnya) dimaksud sebagian dari kaumnya (sebanyak tujuh puluh orang lelaki) dari kalangan orang-orang yang tidak ikut menyembah anak sapi, ia lakukan hal itu berdasarkan perintah dari Allah swt. (untuk memenuhi waktu yang telah Kami tentukan) waktu yang telah Kami janjikan, agar mereka datang tepat pada waktunya, untuk memohon ampunan dari penyembahan terhadap anak sapi yang telah dilakukan oleh teman-teman mereka. Kemudian Musa keluar bersama mereka. (Maka ketika mereka diguncang gempa bumi) yaitu gempa yang dahsyat. Ibnu Abbas mengatakan, \"Sebab mereka tidak melarang kaumnya tatkala menyembah anak sapi itu,\" selanjutnya Ibnu Abbas mengatakan lagi, \"Mereka adalah selain dari orang-orang yang meminta agar dapat melihat Tuhan yang kemudian ditimpa azab berupa sha`iqah\" (Ia berkata,) yakni Musa (\"Ya Tuhanku! Kalau Engkau kehendaki tentulah Engkau membinasakan sebelum ini) sebelum aku keluar bersama mereka; maksud Musa untuk menentukan nasib kaum Bani Israel sehubungan dengan peristiwa penyembahan anak sapi itu, agar jika mereka terkena azab tidak menuduhku sebagai penyebabnya (dan aku. Apakah Engkau membinasakan kami karena perbuatan orang-orang yang kurang akal di antara kami?) Istifham bermakna isti`thaf, memohon belas kasihan, yakni janganlah Engkau menyiksa kami oleh sebab dosa yang dilakukan oleh selain kami. (Tidak lain) (itu) fitnah yang dilakukan oleh orang-orang yang akalnya kurang (kecuali hanyalah fitnah dari Engkau) dimaksud cobaan dari Engkau (Engkau sesatkan dengan cobaan itu siapa yang Engkau kehendaki) kesesatannya (dan Engkau beri petunjuk kepada siapa yang Engkau kehendaki) kehidayahannya. (Engkaulah yang memimpin kami) yang menguasai perkara-perkara kami (maka ampunilah kami, dan berilah kami rahmat dan Engkaulah Pemberi ampun yang sebaik-baiknya.\")",[["وَٱخْتَارَ","Dan memilih"],["مُوسَىٰ","Musa"],["قَوْمَهُۥ","(dari) kaumnya"],["سَبْعِينَ","tujuh puluh"],["رَجُلًۭا","lelaki"],["لِّمِيقَـٰتِنَا ۖ","untuk temu janji Kami"],["فَلَمَّآ","Kemudian apabila"],["أَخَذَتْهُمُ","merampas mereka"],["ٱلرَّجْفَةُ","gempa bumi"],["قَالَ","dia berkata"],["رَبِّ","Wahai Tuhanku"],["لَوْ","Jika"],["شِئْتَ","kamu (telah) menghendaki"],["أَهْلَكْتَهُم","Kamu (boleh) membinasakan mereka"],["مِّن","daripada"],["قَبْلُ","sebelum"],["وَإِيَّـٰىَ ۖ","dan aku"],["أَتُهْلِكُنَا","Adakah Engkau akan membinasakan kami"],["بِمَا","bagi apa"],["فَعَلَ","lakukan"],["ٱلسُّفَهَآءُ","yang bodoh"],["مِنَّآ ۖ","antara kita"],["إِنْ","Tidak"],["هِىَ","ia (adalah)"],["إِلَّا","tetapi"],["فِتْنَتُكَ","Percubaan kamu"],["تُضِلُّ","Kamu biarkan sesat"],["بِهَا","olehnya"],["مَن","yang"],["تَشَآءُ","Kamu akan"],["وَتَهْدِى","dan Engkau memberi petunjuk"],["مَن","yang"],["تَشَآءُ ۖ","Kamu akan"],["أَنتَ","kamu"],["وَلِيُّنَا","(adalah) Pelindung kami"],["فَٱغْفِرْ","jadi maafkan"],["لَنَا","kami"],["وَٱرْحَمْنَا ۖ","dan kasihanilah kami"],["وَأَنتَ","dan kamu"],["خَيْرُ","(adalah) Terbaik"],["ٱلْغَـٰفِرِينَ","(dari) Pengampun"]]],"1110":["(Dan tetapkanlah) pastikanlah (untuk kami kebaikan di dunia ini dan di akhirat) kebaikan (sesungguhnya kami kembali pada jalan hidayah) maksudnya kami telah bertobat (kepada-Mu. Allah berfirman,) Maha Tinggi Allah (\"Siksa-Ku akan Kutimpakan kepada siapa yang Aku kehendaki) Aku ingin menyiksanya (dan rahmat-Ku meliputi) menyeluruh (segala sesuatu) yang ada di dunia (Maka akan Aku tetapkan rahmat-Ku) di akhirat kelak (untuk orang-orang yang bertakwa yang menunaikan zakat dan orang-orang yang beriman kepada ayat-ayat Kami.\")",[["۞ وَٱكْتُبْ","Dan ditahbiskan"],["لَنَا","bagi kami"],["فِى","dalam"],["هَـٰذِهِ","ini"],["ٱلدُّنْيَا","[the] dunia"],["حَسَنَةًۭ","kebaikan"],["وَفِى","dan dalam"],["ٱلْـَٔاخِرَةِ","akhirat"],["إِنَّا","Sesungguhnya kami"],["هُدْنَآ","kami telah berpaling"],["إِلَيْكَ ۚ","kepada-Mu"],["قَالَ","Dia berkata"],["عَذَابِىٓ","hukuman aku"],["أُصِيبُ","aku menderita"],["بِهِۦ","dengannya"],["مَنْ","yang"],["أَشَآءُ ۖ","aku akan"],["وَرَحْمَتِى","tetapi Kerahiman-Ku"],["وَسِعَتْ","merangkumi"],["كُلَّ","setiap"],["شَىْءٍۢ ۚ","perkara"],["فَسَأَكْتُبُهَا","Jadi aku akan menetapkannya"],["لِلَّذِينَ","bagi mereka yang"],["يَتَّقُونَ","(adalah) soleh"],["وَيُؤْتُونَ","dan memberi"],["ٱلزَّكَوٰةَ","zakat"],["وَٱلَّذِينَ","dan orang yang"],["هُم","[mereka]"],["بِـَٔايَـٰتِنَا","dalam Ayat-ayat Kami"],["يُؤْمِنُونَ","mereka beriman"]]],"1111":["(Yaitu orang-orang yang mengikut rasul, nabi yang ummi) yaitu Nabi Muhammad saw. (yang namanya mereka dapati tertulis di dalam Taurat dan Injil yang ada di sisi mereka) lengkap dengan nama dan ciri-cirinya (yang menyuruh mereka mengerjakan yang makruf dan melarang mereka dari mengerjakan yang mungkar dan menghalalkan bagi mereka segala yang baik) dari apa yang sebelumnya diharamkan oleh syariat mereka (dan mengharamkan bagi mereka segala yang buruk) yaitu bangkai dan lain-lainnya (dan membuang dari mereka beban-beban) maksud tanggungan mereka (dan belenggu-belenggu) hal-hal yang berat (yang ada pada mereka) seperti bertobat dengan jalan membunuh diri dan memotong apa yang terkena oleh najis. (Maka orang-orang yang beriman kepadanya) dari kalangan mereka (memuliakannya) yaitu menghormatinya (menolongnya dan mengikuti cahaya yang terang yang diturunkan kepadanya) yakni Alquran (mereka itulah orang-orang yang beruntung).",[["ٱلَّذِينَ","Orang yang"],["يَتَّبِعُونَ","ikut"],["ٱلرَّسُولَ","Rasul"],["ٱلنَّبِىَّ","Nabi"],["ٱلْأُمِّىَّ","yang tidak bersurat"],["ٱلَّذِى","yang"],["يَجِدُونَهُۥ","mereka menemuinya"],["مَكْتُوبًا","bertulis"],["عِندَهُمْ","bersama mereka"],["فِى","dalam"],["ٱلتَّوْرَىٰةِ","Taurat"],["وَٱلْإِنجِيلِ","dan Injeel"],["يَأْمُرُهُم","Dia memerintahkan mereka"],["بِٱلْمَعْرُوفِ","ke kanan"],["وَيَنْهَىٰهُمْ","dan melarang mereka"],["عَنِ","daripada"],["ٱلْمُنكَرِ","yang salah"],["وَيُحِلُّ","dan dia menghalalkan"],["لَهُمُ","bagi mereka"],["ٱلطَّيِّبَـٰتِ","perkara yang suci"],["وَيُحَرِّمُ","dan menjadikan haram"],["عَلَيْهِمُ","bagi mereka"],["ٱلْخَبَـٰٓئِثَ","perkara yang tidak suci"],["وَيَضَعُ","dan dia melegakan"],["عَنْهُمْ","daripada mereka"],["إِصْرَهُمْ","beban mereka"],["وَٱلْأَغْلَـٰلَ","dan belenggu"],["ٱلَّتِى","yang"],["كَانَتْ","adalah"],["عَلَيْهِمْ ۚ","ke atas mereka"],["فَٱلَّذِينَ","Jadi mereka yang"],["ءَامَنُوا۟","beriman"],["بِهِۦ","dalam dirinya"],["وَعَزَّرُوهُ","dan muliakan dia"],["وَنَصَرُوهُ","dan bantu dia"],["وَٱتَّبَعُوا۟","dan ikut"],["ٱلنُّورَ","cahaya itu"],["ٱلَّذِىٓ","yang"],["أُنزِلَ","telah diturunkan"],["مَعَهُۥٓ ۙ","dengan dia"],["أُو۟لَـٰٓئِكَ","Mereka (adalah)"],["هُمُ","[mereka]"],["ٱلْمُفْلِحُونَ","yang berjaya"]]],"1112":["(Katakanlah,) pembicaraan ini ditujukan kepada Nabi saw. (\"Hai manusia! Sesungguhnya aku adalah utusan Allah kepadamu semua, yaitu Allah yang mempunyai kerajaan langit dan bumi; tidak ada Tuhan selain Dia; yang menghidupkan dan mematikan, maka berimanlah kamu kepada Allah dan rasul-Nya, nabi yang ummi yang beriman kepada Allah dan kepada kalimat-kalimat-Nya) yakni Alquran (dan ikutilah dia, supaya kamu mendapat petunjuk.\") artinya kamu akan mendapat bimbingan hidayah.",[["قُلْ","Katakanlah"],["يَـٰٓأَيُّهَا","Wahai"],["ٱلنَّاسُ","manusia"],["إِنِّى","Memang aku"],["رَسُولُ","(the) Rasul"],["ٱللَّهِ","(milik) Allah"],["إِلَيْكُمْ","kepada kamu"],["جَمِيعًا","semua"],["ٱلَّذِى","yang Satu"],["لَهُۥ","untuk Siapa"],["مُلْكُ","(ialah) kekuasaan"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضِ ۖ","dan bumi"],["لَآ","(Ada) tidak"],["إِلَـٰهَ","tuhan"],["إِلَّا","kecuali"],["هُوَ","Dia"],["يُحْىِۦ","Dia memberi kehidupan"],["وَيُمِيتُ ۖ","dan menyebabkan kematian"],["فَـَٔامِنُوا۟","Jadi percayalah"],["بِٱللَّهِ","kepada Allah"],["وَرَسُولِهِ","dan Rasul-Nya"],["ٱلنَّبِىِّ","Nabi"],["ٱلْأُمِّىِّ","yang tidak bersurat"],["ٱلَّذِى","orang yang"],["يُؤْمِنُ","beriman"],["بِٱللَّهِ","kepada Allah"],["وَكَلِمَـٰتِهِۦ","dan Firman-Nya"],["وَٱتَّبِعُوهُ","dan ikut dia"],["لَعَلَّكُمْ","supaya kamu"],["تَهْتَدُونَ","(dibimbing)."]]],"1113":["(Dan di antara kaum Musa itu terdapat suatu umat) suatu jemaah (yang memberi petunjuk) kepada manusia (dengan hak dan dengan yang hak itulah mereka menjalankan keadilan) di dalam memberikan keputusan hukum.",[["وَمِن","Dan antara"],["قَوْمِ","kaum"],["مُوسَىٰٓ","(dari) Musa"],["أُمَّةٌۭ","(adalah) sebuah komuniti"],["يَهْدُونَ","(yang) memberi petunjuk"],["بِٱلْحَقِّ","dengan kebenaran"],["وَبِهِۦ","dan olehnya"],["يَعْدِلُونَ","mewujudkan keadilan"]]],"1114":["(Dan Kami bagi mereka) Kami pecahkan kaum Bani Israel (menjadi dua belas) sebagai hal (suku-suku) menjadi badal dari yang sebelumnya, yaitu kabilah-kabilah (yang masing-masingnya berjumlah besar) menjadi badal dari yang sebelumnya (dan Kami wahyukan kepada Musa ketika kaumnya meminta air kepadanya,) di tengah padang sahara (\"Pukullah batu itu dengan tongkatmu!\") kemudian Musa memukulkannya (maka memancarlah) maksudnya tersemburlah (daripadanya dua belas mata air) sesuai dengan bilangan kabilah (Sesungguhnya tiap-tiap suku telah mengetahui) setiap suku dari kalangan mereka (tempat minum masing-masing. Dan Kami naungkan awan di atas mereka) di padang pasir tempat mereka berada guna melindungi mereka dari panasnya matahari (dan Kami turunkan kepada mereka manna dan salwa) keduanya adalah taranjabin, makanan manis seperti madu, dan sebangsa burung puyuh dengan ditakhfifkan mimnya dan dibaca pendek. Dan Kami berfirman kepada mereka, (\"Makanlah yang baik-baik dari apa yang telah Kami rezekikan kepadamu.\" Mereka tidak menganiaya Kami, tetapi merekalah yang selalu menganiaya dirinya sendiri).",[["وَقَطَّعْنَـٰهُمُ","Dan Kami bahagikan mereka"],["ٱثْنَتَىْ","(menjadi) dua"],["عَشْرَةَ","(dan) sepuluh [iaitu. dua belas]"],["أَسْبَاطًا","suku kaum"],["أُمَمًۭا ۚ","(sebagai) masyarakat"],["وَأَوْحَيْنَآ","Dan Kami ilhamkan"],["إِلَىٰ","kepada"],["مُوسَىٰٓ","Musa"],["إِذِ","apabila"],["ٱسْتَسْقَىٰهُ","meminta air kepadanya"],["قَوْمُهُۥٓ","umatnya"],["أَنِ","[bahawa]"],["ٱضْرِب","mogok"],["بِّعَصَاكَ","dengan kakitangan kamu"],["ٱلْحَجَرَ ۖ","batu itu"],["فَٱنۢبَجَسَتْ","Kemudian terpancut keluar"],["مِنْهُ","daripadanya"],["ٱثْنَتَا","dua"],["عَشْرَةَ","(dan) sepuluh [iaitu. dua belas]"],["عَيْنًۭا ۖ","mata air"],["قَدْ","Sungguh"],["عَلِمَ","tahu"],["كُلُّ","setiap satu"],["أُنَاسٍۢ","orang ramai"],["مَّشْرَبَهُمْ ۚ","tempat minum mereka"],["وَظَلَّلْنَا","Dan Kami teduh"],["عَلَيْهِمُ","[pada] mereka"],["ٱلْغَمَـٰمَ","(dengan) awan"],["وَأَنزَلْنَا","dan Kami turunkan"],["عَلَيْهِمُ","ke atas mereka"],["ٱلْمَنَّ","manna itu"],["وَٱلسَّلْوَىٰ ۖ","dan burung puyuh"],["كُلُوا۟","makan"],["مِن","daripada"],["طَيِّبَـٰتِ","(yang) perkara yang baik"],["مَا","yang"],["رَزَقْنَـٰكُمْ ۚ","Kami telah menyediakan kamu"],["وَمَا","Dan tidak"],["ظَلَمُونَا","mereka menzalimi Kami"],["وَلَـٰكِن","tetapi"],["كَانُوٓا۟","mereka adalah"],["أَنفُسَهُمْ","(kepada) diri mereka sendiri"],["يَظْلِمُونَ","melakukan kesalahan"]]],"1115":["(Dan) Ingatlah (ketika dikatakan kepada mereka, Bani Israel, \"Diamlah di negeri ini saja) yaitu Baitulmakdis (dan makanlah dari hasil buminya di mana saja kamu kehendaki. Dan katakanlah,) perintah Kami ('Bebaskanlah kami dari dosa kami' dan masukilah pintunya) pintu gerbang negeri itu (sambil membungkuk) dengan membungkukkan punggung (niscaya Kami ampuni) dengan memakai nun dan ta, dan bina maf'ul (kesalahan-kesalahanmu.\" Kelak Kami akan tambah pahala kepada orang-orang yang berbuat baik) orang-orang yang taat pahala.",[["وَإِذْ","Dan apabila"],["قِيلَ","ia dikatakan"],["لَهُمُ","kepada mereka"],["ٱسْكُنُوا۟","Langsung"],["هَـٰذِهِ","(dalam) ini"],["ٱلْقَرْيَةَ","bandar"],["وَكُلُوا۟","dan makan"],["مِنْهَا","daripadanya"],["حَيْثُ","di mana sahaja"],["شِئْتُمْ","kamu mahu"],["وَقُولُوا۟","dan katakan"],["حِطَّةٌۭ","Taubat"],["وَٱدْخُلُوا۟","dan masuk"],["ٱلْبَابَ","pintu pagar"],["سُجَّدًۭا","sujud"],["نَّغْفِرْ","Kami akan memaafkan"],["لَكُمْ","bagi kamu"],["خَطِيٓـَٔـٰتِكُمْ ۚ","dosa kamu"],["سَنَزِيدُ","Kami akan menambah (pahala)"],["ٱلْمُحْسِنِينَ","(dari) orang-orang yang berbuat baik"]]],"1116":["(Maka orang-orang yang lalim di antara mereka itu mengganti perkataan itu dengan perkataan yang tidak dikatakan kepada mereka) mereka mengatakan, \"Habbatun fii sya`ratin sebagai ganti dari hiththatun\" dan kemudian mereka memasuki pintu gerbangnya sambil merangkak bukannya membungkukkan badan (maka Kami timpakan kepada mereka azab) yakni siksaan (dari langit disebabkan kelaliman mereka.)",[["فَبَدَّلَ","Tetapi berubah"],["ٱلَّذِينَ","orang yang"],["ظَلَمُوا۟","dizalimi"],["مِنْهُمْ","antara mereka"],["قَوْلًا","perkataan"],["غَيْرَ","selain daripada"],["ٱلَّذِى","(itu) yang"],["قِيلَ","telah dikatakan"],["لَهُمْ","kepada mereka"],["فَأَرْسَلْنَا","Maka Kami hantarkan"],["عَلَيْهِمْ","ke atas mereka"],["رِجْزًۭا","azab"],["مِّنَ","daripada"],["ٱلسَّمَآءِ","langit"],["بِمَا","kerana"],["كَانُوا۟","mereka adalah"],["يَظْلِمُونَ","melakukan kesalahan"]]],"1117":["(Dan tanyakanlah kepada Bani Israel) hai Muhammad, sebagai celaan (tentang negeri yang terletak di dekat laut) di pinggir laut Qalzum yaitu kota Aylah; yang dipertanyakan ialah tentang apa yang terjadi atas penduduknya (ketika mereka melanggar aturan) saat mereka melakukan pelanggaran (pada hari Sabtu) di mana mereka berburu ikan yang pada hari itu mereka dilarang melakukannya (di waktu) merupakan zharaf dari lafal ya'duuna (datang kepada mereka ikan-ikan pada hari Sabtunya dengan terapung-apung pada pinggirannya) yang tampak di permukaan air (dan di hari-hari yang bukan Sabtu) maksudnya di mana mereka sudah tidak lagi terikat dengan pengagungan hari Sabtu, atau dengan kata lain ialah hari-hari selain hari Sabtu (ikan-ikan itu tidak datang kepada mereka) sebagai ujian dari Allah. (Demikianlah Kami mencoba mereka disebabkan mereka berlaku fasik) dan tatkala mereka hendak berburu ikan para penduduk kota terbagi suaranya menjadi tiga bagian; sebagian berpendapat ikut berburu bersama orang-orang yang berburu, sebagian lainnya mencegah mereka melakukannya dan sebagian lainnya bersikap abstain, tidak ikut dan juga tidak melarang.",[["وَسْـَٔلْهُمْ","Dan tanya mereka"],["عَنِ","tentang"],["ٱلْقَرْيَةِ","bandar itu"],["ٱلَّتِى","yang"],["كَانَتْ","adalah"],["حَاضِرَةَ","terletak"],["ٱلْبَحْرِ","(oleh) laut"],["إِذْ","apabila"],["يَعْدُونَ","mereka melanggar"],["فِى","dalam"],["ٱلسَّبْتِ","(perkara) Sabat"],["إِذْ","apabila"],["تَأْتِيهِمْ","datang kepada mereka"],["حِيتَانُهُمْ","ikan mereka"],["يَوْمَ","(pada) hari"],["سَبْتِهِمْ","(dari) Sabat mereka"],["شُرَّعًۭا","nampak"],["وَيَوْمَ","dan (pada) hari"],["لَا","tidak"],["يَسْبِتُونَ ۙ","mereka mempunyai hari Sabat"],["لَا","(mereka melakukannya) tidak"],["تَأْتِيهِمْ ۚ","datang kepada mereka"],["كَذَٰلِكَ","Demikianlah"],["نَبْلُوهُم","Kami menguji mereka"],["بِمَا","kerana"],["كَانُوا۟","mereka adalah"],["يَفْسُقُونَ","membangkang menderhaka"]]],"1118":["(Dan ketika) diathafkan kepada lafal idz yang sebelumnya (suatu umat di antara mereka berkata,) yaitu kaum yang tidak ikut berburu dan juga tidak melarang orang-orang yang berburu (\"Mengapa kamu menasihati kaum yang Allah akan membinasakan mereka atau mengazab mereka dengan azab yang keras?\" Mereka menjawab,) nasihat kami (\"Agar kami mempunyai alasan) yang bisa dijadikan sebagai pelepas tanggung jawab (kepada Tuhanmu) supaya kami tidak dituduh lalai dalam masalah tidak memberikan larangan kepada mereka (dan supaya mereka bertakwa.\") tidak berani melakukan perburuan lagi.",[["وَإِذْ","Dan apabila"],["قَالَتْ","berkata"],["أُمَّةٌۭ","sesebuah komuniti"],["مِّنْهُمْ","antara mereka"],["لِمَ","kenapa"],["تَعِظُونَ","(ada) kamu berdakwah"],["قَوْمًا ۙ","suatu kaum"],["ٱللَّهُ","(siapa) Allah"],["مُهْلِكُهُمْ","(akan) membinasakan mereka"],["أَوْ","atau"],["مُعَذِّبُهُمْ","menghukum mereka"],["عَذَابًۭا","(dengan) hukuman"],["شَدِيدًۭا ۖ","teruk"],["قَالُوا۟","Mereka berkata"],["مَعْذِرَةً","Untuk dibebaskan"],["إِلَىٰ","sebelum"],["رَبِّكُمْ","Tuhanmu"],["وَلَعَلَّهُمْ","dan supaya mereka boleh"],["يَتَّقُونَ","menjadi soleh"]]],"1119":["(Maka tatkala mereka melupakan) yaitu mereka meninggalkan (apa yang diperingatkan kepada mereka) apa yang dinasihatkan kepada mereka (tentang hal itu) kemudian mereka tidak mau juga menuruti nasihat (Kami selamatkan orang-orang yang melarang dari perbuatan jahat dan Kami timpakan kepada orang-orang yang lalim) yang melakukan pelanggaran (siksaan yang berat) yang keras (disebabkan mereka selalu berbuat fasik.)",[["فَلَمَّا","Maka apabila"],["نَسُوا۟","mereka lupa"],["مَا","apa"],["ذُكِّرُوا۟","mereka telah diingatkan"],["بِهِۦٓ","dengan [ia]"],["أَنجَيْنَا","Kami menyelamatkan"],["ٱلَّذِينَ","orang yang"],["يَنْهَوْنَ","melarang"],["عَنِ","[dari]"],["ٱلسُّوٓءِ","yang jahat"],["وَأَخَذْنَا","dan Kami rampas"],["ٱلَّذِينَ","orang yang"],["ظَلَمُوا۟","dizalimi"],["بِعَذَابٍۭ","dengan hukuman"],["بَـِٔيسٍۭ","celaka"],["بِمَا","kerana"],["كَانُوا۟","mereka adalah"],["يَفْسُقُونَ","membangkang menderhaka"]]],"1120":["(Maka tatkala mereka bersikap sombong) yakni bersikap takabur (terhadap) tidak mau meninggalkan (apa yang dilarang mereka mengerjakannya, Kami katakan kepada mereka, \"Jadilah kamu kera yang hina.\") yang terhina, maka jadilah mereka itu kera yang hina; keterangan ini adalah penjelasan dari apa yang telah lalu. Ibnu Abbas mengatakan, \"Saya tidak mengetahui tentang apa yang terjadi dengan golongan yang bersikap abstain.\" Ikrimah mengatakan, \"Mereka tidak dibinasakan, sebab mereka membenci apa yang telah dilakukan rekan-rekannya dan mereka mengatakan, 'Mengapa kamu menasihati....'.\" Hakim telah meriwayatkan dari Ibnu Abbas bahwa golongan tersebut ikut pula melakukannya dan bahkan takjub dengan sikap mereka yang melakukannya.",[["فَلَمَّا","Maka apabila"],["عَتَوْا۟","mereka melampaui semua batas"],["عَن","tentang"],["مَّا","apa"],["نُهُوا۟","mereka dilarang"],["عَنْهُ","daripadanya"],["قُلْنَا","Kami berkata"],["لَهُمْ","kepada mereka"],["كُونُوا۟","Jadilah"],["قِرَدَةً","beruk"],["خَـٰسِـِٔينَ","dihina"]]],"1121":["(Dan ketika memberitahukan) mempermaklumkan (Tuhanmu, bahwa sesungguhnya Dia akan mengirim kepada mereka) dimaksud orang-orang Yahudi (sampai hari kiamat orang-orang yang akan menimpakan kepada mereka azab yang seburuk-buruknya) dengan dihinakan dan dibebani pajak/jizyah; kemudian Allah mengutus Nabi Sulaiman kepada mereka, dan sesudah itu Raja Bukhtunasher (Nebukat Nezar) yang membunuh dan menawan mereka serta mewajibkan mereka membayar jizyah. Mereka selalu membayar jizyah kepada orang-orang Majusi sehingga Allah swt. mengutus nabi kita Muhammad saw. yang kemudian mengambil pula jizyah dari mereka. (Sesungguhnya Tuhanmu amat cepat siksa-Nya) (dan sesungguhnya Dia Maha Pengampun) terhadap orang-orang yang taat kepada-Nya (lagi Maha Penyayang) terhadap mereka yang taat.",[["وَإِذْ","Dan apabila"],["تَأَذَّنَ","diisytiharkan"],["رَبُّكَ","Tuhanmu"],["لَيَبْعَثَنَّ","bahawa Dia pasti akan menghantar"],["عَلَيْهِمْ","ke atas mereka"],["إِلَىٰ","sehingga"],["يَوْمِ","(the) Hari"],["ٱلْقِيَـٰمَةِ","Kiamat"],["مَن","(mereka) yang"],["يَسُومُهُمْ","akan menyusahkan mereka"],["سُوٓءَ","(dengan) yang pedih"],["ٱلْعَذَابِ ۗ","[the] hukuman"],["إِنَّ","Sesungguhnya"],["رَبَّكَ","Tuhanmu"],["لَسَرِيعُ","(adalah) pasti pantas"],["ٱلْعِقَابِ ۖ","(dalam) pembalasan"],["وَإِنَّهُۥ","tetapi sesungguhnya, Dia"],["لَغَفُورٌۭ","(adalah) sesungguhnya Maha Pengampun"],["رَّحِيمٌۭ","Maha Mengasihani"]]],"1122":["(Dan Kami bagi-bagi mereka) Kami pecah-pecah mereka (di dunia menjadi beberapa golongan) terdiri dari beberapa golongan (di antaranya ada orang-orang yang saleh dan di antaranya) ada orang-orang (yang tidak demikian) yaitu menjadi orang-orang kafir dan orang-orang fasik (Dan Kami coba mereka dengan yang baik-baik) yang nikmat-nikmat (dan yang buruk-buruk) dengan bencana-bencana (agar mereka kembali) kepada kebenaran dan tidak mau berbuat fasik lagi.",[["وَقَطَّعْنَـٰهُمْ","Dan Kami bahagikan mereka"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["أُمَمًۭا ۖ","(sebagai) negara"],["مِّنْهُمُ","Antaranya"],["ٱلصَّـٰلِحُونَ","(adalah) orang-orang yang soleh"],["وَمِنْهُمْ","dan antara mereka"],["دُونَ","(adalah) selain daripada"],["ذَٰلِكَ ۖ","bahawa"],["وَبَلَوْنَـٰهُم","Dan Kami menguji mereka"],["بِٱلْحَسَنَـٰتِ","dengan kebaikan"],["وَٱلسَّيِّـَٔاتِ","dan yang buruk"],["لَعَلَّهُمْ","supaya mereka boleh"],["يَرْجِعُونَ","kembali"]]],"1123":["(Maka datanglah sesudah mereka generasi yang jahat yang mewarisi Alkitab) yakni kitab Taurat dari para pendahulu mereka (yang mengambil harta benda dunia yang rendah ini) sesuatu yang tidak ada harganya, yaitu duniawi baik yang halal maupun yang haram (dan berkata, \"Kami akan diberi ampun.\") atas apa yang telah kami lakukan. (Dan kelak jika datang kepada mereka harta benda dunia sebanyak itu pula niscaya mereka akan mengambilnya juga) jumlah kalimat ini menjadi hal; artinya mereka masih juga mengharapkan ampunan sedangkan mereka masih tetap kembali melakukannya padahal di dalam kitab Taurat tidak ada janji ampunan jika disertai dengan menetapi perbuatan dosa (bukankah sudah diambil) Istifham atau kata tanya bermakna menetapkan (perjanjian kitab Taurat dari mereka) Idhafah di sini bermakna fii (yaitu bahwa mereka tidak akan mengatakan terhadap Allah kecuali yang benar, padahal mereka telah mempelajari) diathafkan kepada lafal yu`khadzu, yakni mereka telah membaca (apa yang tersebut di dalamnya?) maka mengapa mereka mendustakan tentang masalah ampunan itu, sedangkan mereka masih terus menepati perbuatan dosanya. (Dan kampung akhirat itu lebih baik bagi mereka yang bertakwa) yang takut terhadap perbuatan haram. (Maka apakah mereka tidak mengerti) dengan memakai ya dan ta, sesungguhnya pahala akhirat itu lebih baik yang seharusnya mereka lebih memilihnya daripada perkara duniawi.",[["فَخَلَفَ","Kemudian berjaya"],["مِنۢ","daripada"],["بَعْدِهِمْ","selepas mereka"],["خَلْفٌۭ","pengganti"],["وَرِثُوا۟","(yang) mewarisi"],["ٱلْكِتَـٰبَ","Kitab"],["يَأْخُذُونَ","mengambil"],["عَرَضَ","barang"],["هَـٰذَا","(dari) ini"],["ٱلْأَدْنَىٰ","yang lebih rendah (nyawa)"],["وَيَقُولُونَ","dan mereka berkata"],["سَيُغْفَرُ","Ia akan dimaafkan"],["لَنَا","bagi kami"],["وَإِن","Dan jika"],["يَأْتِهِمْ","datang kepada mereka"],["عَرَضٌۭ","barang"],["مِّثْلُهُۥ","serupa dengannya"],["يَأْخُذُوهُ ۚ","mereka akan mengambilnya"],["أَلَمْ","Bukan"],["يُؤْخَذْ","diambil"],["عَلَيْهِم","ke atas mereka"],["مِّيثَـٰقُ","Perjanjian"],["ٱلْكِتَـٰبِ","Kitab"],["أَن","bahawa"],["لَّا","tidak"],["يَقُولُوا۟","mereka akan berkata"],["عَلَى","tentang"],["ٱللَّهِ","Allah"],["إِلَّا","kecuali"],["ٱلْحَقَّ","kebenaran"],["وَدَرَسُوا۟","semasa mereka belajar"],["مَا","apa"],["فِيهِ ۗ","(ada) di dalamnya"],["وَٱلدَّارُ","Dan rumah"],["ٱلْـَٔاخِرَةُ","(dari) Akhirat"],["خَيْرٌۭ","(lebih) baik"],["لِّلَّذِينَ","bagi mereka yang"],["يَتَّقُونَ ۗ","takut kepada Allah"],["أَفَلَا","Jadi tidak akan"],["تَعْقِلُونَ","kamu menggunakan akal"]]],"1124":["(Dan orang-orang yang berpegang teguh) dengan memakai tasydid dan tidak/takhfif (dengan Alkitab Taurat) yaitu sebagian di antara mereka (serta mendirikan salat) seperti Abdullah bin Salam dan teman-temannya. (Sesungguhnya Kami tidak menyia-nyiakan pahala orang-orang yang mengadakan perbaikan) Jumlah kalimat ini menjadi khabar dari lafal lilladziina; dan di dalamnya terkandung meletakkan isim zhahir pada tempat isim dhamir; yakni ajrahum/pahala mereka.",[["وَٱلَّذِينَ","Dan orang yang"],["يُمَسِّكُونَ","berpegang teguh"],["بِٱلْكِتَـٰبِ","kepada Kitab"],["وَأَقَامُوا۟","dan mendirikan"],["ٱلصَّلَوٰةَ","solat"],["إِنَّا","sesungguhnya, Kami"],["لَا","(akan) tidak"],["نُضِيعُ","[Kami] melepaskan pembaziran"],["أَجْرَ","(i) ganjaran"],["ٱلْمُصْلِحِينَ","(dari) para pembaharu"]]],"1125":["(Dan) ingatlah (ketika Kami mengangkat bukit) yaitu Kami mencabutnya dari dasarnya (ke atas mereka seakan-akan bukit itu naungan awan dan mereka menduga) dan merasa yakin (bahwa bukit itu akan jatuh menimpa mereka) akan jatuh kepada mereka sesuai dengan janji Allah kepada mereka, bahwa hal itu akan menimpa mereka jika mereka tidak mau menerima hukum-hukum syariat kitab Taurat. Mereka menolaknya mengingat hal itu teramat berat pada permulaannya tetapi kemudian mereka mau menerimanya. Kami berfirman kepada mereka, (\"Peganglah dengan teguh apa yang telah Kami berikan kepadamu) dengan sungguh-sungguh dan dengan segala kemampuan (serta ingatlah selalu apa yang tersebut di dalamnya) dengan mengamalkannya (supaya kamu menjadi orang-orang yang bertakwa.\").",[["۞ وَإِذْ","Dan apabila"],["نَتَقْنَا","Kami bangkitkan"],["ٱلْجَبَلَ","gunung itu"],["فَوْقَهُمْ","di atas mereka"],["كَأَنَّهُۥ","seolah-olah ia adalah"],["ظُلَّةٌۭ","sebuah kanopi"],["وَظَنُّوٓا۟","dan mereka berfikir"],["أَنَّهُۥ","bahawa ia"],["وَاقِعٌۢ","(akan) jatuh"],["بِهِمْ","ke atas mereka"],["خُذُوا۟","(Kami berkata), \"Ambil"],["مَآ","apa"],["ءَاتَيْنَـٰكُم","Kami telah memberi kamu"],["بِقُوَّةٍۢ","dengan kekuatan"],["وَٱذْكُرُوا۟","dan ingat"],["مَا","apa"],["فِيهِ","(ada) di dalamnya"],["لَعَلَّكُمْ","supaya kamu"],["تَتَّقُونَ","takut kepada Allah"]]],"1126":["(Dan) ingatlah (ketika) sewaktu (Tuhanmu mengeluarkan keturunan anak-anak Adam dari sulbi mereka) menjadi badal isytimal dari lafal sebelumnya dengan mengulangi huruf jar (yaitu anak cucu mereka) maksudnya Dia mengeluarkan sebagian mereka dari tulang sulbi sebagian lainnya yang berasal dari sulbi Nabi Adam secara turun-temurun, sebagaimana sekarang mereka beranak-pinak mirip dengan jagung di daerah Nu`man sewaktu hari Arafah/musim jagung. Allah menetapkan kepada mereka bukti-bukti yang menunjukkan ketuhanan-Nya serta Dia memberinya akal (dan Allah mengambil kesaksian terhadap jiwa mereka) seraya berfirman, (\"Bukankah Aku ini Tuhanmu?\" Mereka menjawab, \"Betul.) Engkau adalah Tuhan kami (kami menjadi saksi.\") yang demikian itu. Kesaksian itu supaya (tidak) jangan (kamu mengatakan) dengan memakai ya dan ta pada dua tempat, yakni orang-orang kafir (di hari kiamat kelak, \"Sesungguhnya kami terhadap hal-hal ini) yakni keesaan Tuhan (adalah orang-orang yang lalai.\") kami tidak mengetahuinya.",[["وَإِذْ","Dan apabila"],["أَخَذَ","(telah) diambil"],["رَبُّكَ","(oleh) Tuhanmu"],["مِنۢ","daripada"],["بَنِىٓ","(the) Kanak-kanak"],["ءَادَمَ","(dari) Adam"],["مِن","daripada"],["ظُهُورِهِمْ","pinggang mereka"],["ذُرِّيَّتَهُمْ","keturunan mereka"],["وَأَشْهَدَهُمْ","dan menjadikan mereka bersaksi"],["عَلَىٰٓ","atas"],["أَنفُسِهِمْ","diri mereka"],["أَلَسْتُ","Adakah aku tidak"],["بِرَبِّكُمْ ۖ","Tuhanmu"],["قَالُوا۟","Mereka berkata"],["بَلَىٰ ۛ","ya"],["شَهِدْنَآ ۛ","kami telah bersaksi"],["أَن","Jangan-jangan"],["تَقُولُوا۟","kamu cakap"],["يَوْمَ","(pada) hari"],["ٱلْقِيَـٰمَةِ","Kiamat"],["إِنَّا","Sesungguhnya"],["كُنَّا","kami"],["عَنْ","tentang"],["هَـٰذَا","ini"],["غَـٰفِلِينَ","tak sedar"]]],"1127":["(Atau agar kamu tidak mengatakan, \"Sesungguhnya orang-orang tua kami telah mempersekutukan Tuhan sejak dahulu) dimaksud sebelum kami (sedangkan kami ini adalah anak-anak keturunan yang datang sesudah mereka) maka kami hanya mengikut mereka (Maka apakah Engkau akan membinasakan kami) Engkau akan mengazab kami (karena perbuatan orang-orang yang sesat dahulu?\") dari kalangan orang-orang tua kami yang pertama kali melakukan kemusyrikan. Kesimpulan pengertian dari ayat ini bahwa mereka tidak mungkin berhujah dengan alasan itu sedangkan mereka telah melakukan kesaksian terhadap diri mereka sendiri tentang keesaan Tuhan itu. Penuturan tentang hal ini melalui lisan pemilik mukjizat/Nabi Muhammad saw. kedudukannya sama dengan penuturan terhadap jiwa manusia semuanya.",[["أَوْ","Atau"],["تَقُولُوٓا۟","kamu cakap"],["إِنَّمَآ","Hanya"],["أَشْرَكَ","bersekutu (dengan Allah)"],["ءَابَآؤُنَا","(oleh) nenek moyang kita"],["مِن","daripada"],["قَبْلُ","sebelum (kita)"],["وَكُنَّا","dan kita"],["ذُرِّيَّةًۭ","keturunan"],["مِّنۢ","daripada"],["بَعْدِهِمْ ۖ","selepas mereka"],["أَفَتُهْلِكُنَا","Maka Engkau akan membinasakan kami"],["بِمَا","bagi apa"],["فَعَلَ","lakukan"],["ٱلْمُبْطِلُونَ","para pemalsu"]]],"1128":["(Dan demikianlah Kami menjelaskan ayat-ayat itu) Kami menerangkan seperti apa yang telah Kami jelaskan di dalam perjanjian kesaksian supaya mereka memikirkannya (agar mereka kembali) dari kekafiran mereka kepada kebenaran.",[["وَكَذَٰلِكَ","Dan dengan demikian"],["نُفَصِّلُ","Kami terangkan"],["ٱلْـَٔايَـٰتِ","ayat-ayat"],["وَلَعَلَّهُمْ","supaya mereka boleh"],["يَرْجِعُونَ","kembali"]]],"1129":["(Dan bacakanlah) hai Muhammad (kepada mereka) yakni orang-orang Yahudi (berita) kabar (orang yang telah Kami berikan kepadanya ayat-ayat Kami, pengetahuan tentang isi Alkitab, kemudian dia melepaskan diri dari ayat-ayat itu) maksudnya ia keluar darinya dengan membawa kekafirannya, sebagaimana seekor ular keluar dari kulitnya, orang yang dimaksud ialah Bal`am bin Ba`ura salah seorang ulama terkemuka Bani Israel. Ia diminta agar mendoakan Musa celaka dan untuk itu diberi hadiah, dia mendoakan hal itu tetapi doanya itu menyebabkan senjata makan tuan akhirnya lidahnya menjulur sampai ke dadanya (lalu dia diikuti oleh setan) setan dapat menggodanya sehingga jadilah ia temannya (maka jadilah ia termasuk orang-orang yang sesat).",[["وَٱتْلُ","Dan mengaji"],["عَلَيْهِمْ","kepada mereka"],["نَبَأَ","(yang) cerita"],["ٱلَّذِىٓ","(dari) seseorang yang"],["ءَاتَيْنَـٰهُ","Kami memberi [dia]"],["ءَايَـٰتِنَا","Ayat Kami"],["فَٱنسَلَخَ","tetapi dia berpisah"],["مِنْهَا","[dari] mereka"],["فَأَتْبَعَهُ","jadi ikut dia"],["ٱلشَّيْطَـٰنُ","syaitan"],["فَكَانَ","dan dia menjadi"],["مِنَ","daripada"],["ٱلْغَاوِينَ","mereka yang sesat"]]],"1130":["(Dan kalau Kami menghendaki, sesungguhnya Kami tinggikan dia) kepada derajat para ulama (dengan ayat-ayat itu) seumpamanya Kami memberikan taufik/kekuatan kepadanya untuk mengamalkan ayat-ayat itu (tetapi dia cenderung) yaitu lebih menyukai (kepada tanah) yakni harta benda dan duniawi (dan menurutkan hawa nafsunya yang rendah) dalam doa yang dilakukannya, akhirnya Kami balik merendahkan derajatnya. (Maka perumpamaannya) ciri khasnya (seperti anjing jika kamu menghalaunya) mengusir dan menghardiknya (diulurkannya lidahnya) lidahnya menjulur (atau) jika (kamu membiarkannya dia mengulurkan lidahnya juga) sedangkan sifat seperti itu tidak terdapat pada hewan-hewan selain anjing. Kedua jumlah syarat menjadi hal, ia menjulurkan lidahnya dalam keadaan terhina dalam segala kondisi. Maksudnya penyerupaan/tasybih ini ialah mengumpamakan dalam hal kerendahan dan kehinaan dengan qarinah adanya fa yang memberikan pengertian tertib dengan kalimat sebelumnya, yakni kecenderungan terhadap duniawi dan mengikuti hawa nafsu rendahnya, juga karena adanya qarinah/bukti firman-Nya, (Demikian itulah) perumpamaan itulah (perumpamaan orang-orang yang mendustakan ayat-ayat Kami. Maka ceritakanlah kisah-kisah itu) kepada orang-orang Yahudi (agar mereka berpikir) agar mereka mau memikirkannya hingga mereka mau beriman.",[["وَلَوْ","Dan jika"],["شِئْنَا","Kami berkehendak"],["لَرَفَعْنَـٰهُ","sesungguhnya Kami telah membangkitkannya"],["بِهَا","dengan ini"],["وَلَـٰكِنَّهُۥٓ","[dan] tetapi dia"],["أَخْلَدَ","dipatuhi"],["إِلَى","kepada"],["ٱلْأَرْضِ","bumi"],["وَٱتَّبَعَ","dan diikuti"],["هَوَىٰهُ ۚ","keinginannya (sia-sia)."],["فَمَثَلُهُۥ","Jadi contoh dia"],["كَمَثَلِ","(adalah) seperti (the) contoh"],["ٱلْكَلْبِ","(dari) anjing itu"],["إِن","jika"],["تَحْمِلْ","kamu menyerang"],["عَلَيْهِ","[pada] dia"],["يَلْهَثْ","dia menjelirkan lidah"],["أَوْ","atau"],["تَتْرُكْهُ","kalau kamu tinggalkan dia"],["يَلْهَث ۚ","dia menjelirkan lidah"],["ذَّٰلِكَ","Itu"],["مَثَلُ","(adalah) contoh"],["ٱلْقَوْمِ","(daripada) rakyat"],["ٱلَّذِينَ","yang"],["كَذَّبُوا۟","dinafikan"],["بِـَٔايَـٰتِنَا ۚ","[dalam] Tanda-tanda Kami"],["فَٱقْصُصِ","Jadi kaitkan"],["ٱلْقَصَصَ","cerita itu"],["لَعَلَّهُمْ","supaya mereka boleh"],["يَتَفَكَّرُونَ","merenung"]]],"1131":["(Amat buruklah) amat jeleklah (perumpamaan suatu kaum) yaitu perumpamaan kaum itu (yaitu orang-orang yang mendustakan ayat-ayat Kami dan kepada diri mereka sendirilah mereka berbuat lalim) dengan mendustakan ayat-ayat itu.",[["سَآءَ","jahat"],["مَثَلًا","(sebagai) contoh"],["ٱلْقَوْمُ","(adalah) rakyat"],["ٱلَّذِينَ","orang yang"],["كَذَّبُوا۟","dinafikan"],["بِـَٔايَـٰتِنَا","Tanda-Tanda Kami"],["وَأَنفُسَهُمْ","dan diri mereka sendiri"],["كَانُوا۟","mereka dahulu"],["يَظْلِمُونَ","salah"]]],"1132":["(Barang siapa yang diberi petunjuk oleh Allah, maka dialah yang mendapat petunjuk dan barang siapa yang disesatkan Allah, maka merekalah orang-orang yang merugi).",[["مَن","Siapa pun"],["يَهْدِ","(adalah) dibimbing"],["ٱللَّهُ","(oleh) Allah"],["فَهُوَ","kemudian dia"],["ٱلْمُهْتَدِى ۖ","(ialah) yang mendapat petunjuk"],["وَمَن","manakala sesiapa"],["يُضْلِلْ","Dia biarkan sesat"],["فَأُو۟لَـٰٓئِكَ","kemudian mereka"],["هُمُ","[mereka]"],["ٱلْخَـٰسِرُونَ","(adalah) orang-orang yang rugi"]]],"1133":["(Dan sesungguhnya Kami jadikan) Kami ciptakan (untuk isi neraka Jahanam kebanyakan dari jin dan manusia, mereka mempunyai hati tetapi tidak dipergunakan untuk memahami ayat-ayat Allah) yakni perkara hak (dan mereka mempunyai mata tetapi tidak dipergunakannya untuk melihat tanda-tanda kekuasaan Allah) yaitu bukti-bukti yang menunjukkan kekuasaan Allah dengan penglihatan yang disertai pemikiran (dan mereka mempunyai telinga tetapi tidak dipergunakannya untuk mendengar ayat-ayat Allah) ayat-ayat Allah dan nasihat-nasihat-Nya dengan pendengaran yang disertai pemikiran dan ketaatan (mereka itu sebagai binatang ternak) dalam hal tidak mau mengetahui, melihat dan mendengar (bahkan mereka lebih sesat) dari hewan ternak itu sebab hewan ternak akan mencari hal-hal yang bermanfaat bagi dirinya dan ia akan lari dari hal-hal yang membahayakan dirinya tetapi mereka itu berani menyuguhkan dirinya ke dalam neraka dengan menentang (mereka itulah orang-orang yang lalai)",[["وَلَقَدْ","Dan sungguh"],["ذَرَأْنَا","Kami telah mencipta"],["لِجَهَنَّمَ","untuk Neraka"],["كَثِيرًۭا","ramai"],["مِّنَ","daripada"],["ٱلْجِنِّ","jin"],["وَٱلْإِنسِ ۖ","dan lelaki"],["لَهُمْ","Untuk mereka"],["قُلُوبٌۭ","(adalah) hati"],["لَّا","(tetapi) tidak"],["يَفْقَهُونَ","mereka faham"],["بِهَا","bersama mereka"],["وَلَهُمْ","dan untuk mereka"],["أَعْيُنٌۭ","(adalah) mata"],["لَّا","(tetapi) tidak"],["يُبْصِرُونَ","mereka lihat"],["بِهَا","bersama mereka"],["وَلَهُمْ","dan untuk mereka"],["ءَاذَانٌۭ","(adalah) telinga"],["لَّا","(tetapi) tidak"],["يَسْمَعُونَ","mereka dengar"],["بِهَآ ۚ","bersama mereka"],["أُو۟لَـٰٓئِكَ","Mereka itu"],["كَٱلْأَنْعَـٰمِ","(adalah) seperti lembu"],["بَلْ","tidak"],["هُمْ","mereka"],["أَضَلُّ ۚ","(adalah) lebih sesat"],["أُو۟لَـٰٓئِكَ","Itu"],["هُمُ","mereka"],["ٱلْغَـٰفِلُونَ","(adalah) orang-orang yang lalai"]]],"1134":["(Allah mempunyai asma-asma yang baik) yang sembilan puluh sembilan, demikianlah telah disebutkan oleh hadis. Al-husna adalah bentuk muannats dari al-ahsan (maka bermohonlah kepada-Nya) sebutkanlah Dia olehmu (dengan menyebut nama-nama-Nya itu dan tinggalkanlah) maksudnya biarkanlah (orang-orang yang menyimpang dari kebenaran) berasal dan kata alhada dan lahada, yang artinya mereka menyimpang dari perkara yang hak (dalam menyebut nama-nama-Nya) artinya mereka mengambil nama-nama tersebut untuk disebutkan kepada sesembahan-sesembahan mereka, seperti nama Latta yang berakar dari lafal Allah, dan Uzzaa yang berakar dari kata Al-Aziiz, dan Manaat yang berakar dari kata Al-Mannaan (nanti mereka akan mendapat balasan) kelak di akhirat sebagai pembalasannya (terhadap apa yang telah mereka kerjakan) ketentuan ini sebelum turunnya ayat perintah berperang.",[["وَلِلَّهِ","Dan untuk Allah"],["ٱلْأَسْمَآءُ","(adalah) nama-nama"],["ٱلْحُسْنَىٰ","yang paling cantik"],["فَٱدْعُوهُ","maka mohonlah kepada-Nya"],["بِهَا ۖ","oleh mereka"],["وَذَرُوا۟","Dan pergi"],["ٱلَّذِينَ","orang yang"],["يُلْحِدُونَ","menyimpang"],["فِىٓ","tentang"],["أَسْمَـٰٓئِهِۦ ۚ","nama dia"],["سَيُجْزَوْنَ","Mereka akan mendapat balasan"],["مَا","bagi apa"],["كَانُوا۟","mereka dahulu"],["يَعْمَلُونَ","lakukan"]]],"1135":["(Dan di antara orang-orang yang Kami ciptakan ada umat yang memberi petunjuk dengan hak, dan dengan yang hak itu pula mereka menjalankan keadilan) mereka adalah umat Muhammad saw. sebagaimana yang telah dijelaskan oleh hadis.",[["وَمِمَّنْ","Dan dari (orang-orang) yang"],["خَلَقْنَآ","Kami telah mencipta"],["أُمَّةٌۭ","(adalah) sebuah negara"],["يَهْدُونَ","yang membimbing"],["بِٱلْحَقِّ","dengan kebenaran"],["وَبِهِۦ","dan dengan itu"],["يَعْدِلُونَ","mereka menegakkan keadilan"]]],"1136":["(Dan orang-orang yang mendustakan ayat-ayat Kami) yakni Alquran, dari kalangan penduduk Mekah (nanti Kami akan menarik mereka secara berangsur-angsur) Kami akan mengazab mereka sedikit demi sedikit (dengan cara yang tidak mereka ketahui).",[["وَٱلَّذِينَ","Tetapi mereka yang"],["كَذَّبُوا۟","dinafikan"],["بِـَٔايَـٰتِنَا","Tanda-Tanda Kami"],["سَنَسْتَدْرِجُهُم","Kami akan memimpin mereka secara beransur-ansur"],["مِّنْ","daripada"],["حَيْثُ","di mana"],["لَا","tidak"],["يَعْلَمُونَ","mereka tahu"]]],"1137":["(Dan Aku memberi tangguh kepada mereka) Kami menangguhkan mereka (Sesungguhnya rencana-Ku amat tangguh) amat keras dan tidak bisa ditahan.",[["وَأُمْلِى","Dan aku akan memberi tangguh"],["لَهُمْ ۚ","kepada mereka"],["إِنَّ","Sesungguhnya"],["كَيْدِى","rancangan aku"],["مَتِينٌ","(adalah) tegas"]]],"1138":["(Apakah mereka tidak memikirkan) kemudian mereka dapat mengetahui (bahwa teman mereka) yaitu Muhammad saw. (tidak berpenyakit gila) bukanlah kurang akal (tidak lain) (dia hanyalah seorang pemberi peringatan lagi pemberi penjelasan) yang jelas peringatannya.",[["أَوَلَمْ","Jangan"],["يَتَفَكَّرُوا۟ ۗ","mereka merenung"],["مَا","Tidak"],["بِصَاحِبِهِم","dalam pasangan mereka"],["مِّن","[daripada]"],["جِنَّةٍ ۚ","(adalah) sebarang kegilaan"],["إِنْ","Tidak"],["هُوَ","dia"],["إِلَّا","(adalah) tetapi"],["نَذِيرٌۭ","seorang pemberi amaran"],["مُّبِينٌ","yang nyata"]]],"1139":["(Dan apakah mereka tidak memperhatikan kerajaan) kekuasaan (langit dan bumi dan) di dalam (segala sesuatu yang diciptakan Allah) merupakan penjelasan dari apa yang sebelumnya, dengan hal itu mereka menyimpulkan tentang kekuasaan dan keesaan penciptanya (dan bahwasanya) sehubungan dengan (kemungkinan telah dekatnya) (kebinasaan mereka?) kemudian mereka mati dalam keadaan kafir, lalu mereka dimasukkan ke dalam neraka. Mengapa mereka tidak bersegera untuk beriman. (Maka kepada berita manakah lagi sesudahnya) yakni sesudah berita Alquran (mereka akan beriman?)",[["أَوَلَمْ","Jangan"],["يَنظُرُوا۟","mereka melihat"],["فِى","dalam"],["مَلَكُوتِ","(kekuasaan)."],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضِ","dan bumi"],["وَمَا","dan apa"],["خَلَقَ","telah (telah) dicipta"],["ٱللَّهُ","(oleh) Allah"],["مِن","daripada"],["شَىْءٍۢ","(setiap) perkara"],["وَأَنْ","dan bahawa"],["عَسَىٰٓ","mungkin"],["أَن","[bahawa]"],["يَكُونَ","mempunyai"],["قَدِ","sesungguhnya"],["ٱقْتَرَبَ","datang dekat"],["أَجَلُهُمْ ۖ","istilah mereka"],["فَبِأَىِّ","Jadi dalam apa"],["حَدِيثٍۭ","kenyataan"],["بَعْدَهُۥ","selepas ini"],["يُؤْمِنُونَ","adakah mereka akan beriman"]]],"1140":["(Barang siapa yang Allah sesatkan, maka baginya tak ada orang yang akan memberi petunjuk. Dan Allah membiarkan mereka) dengan memakai ya dan nun serta dirafa`kan sebagai jumlah isti'naf/permulaan; sedangkan apabila dijazamkan maka diathafkan secara mahall kepada lafal sesudah fa (terombang-ambing dalam kesesatan) mereka terombang-ambing dalam keadaan bingung.",[["مَن","Siapa pun"],["يُضْلِلِ","(adalah) membiarkan sesat"],["ٱللَّهُ","(oleh) Allah"],["فَلَا","maka (ada) tidak"],["هَادِىَ","panduan"],["لَهُۥ ۚ","baginya"],["وَيَذَرُهُمْ","Dan Dia meninggalkan mereka"],["فِى","dalam"],["طُغْيَـٰنِهِمْ","pelanggaran mereka"],["يَعْمَهُونَ","merayau buta"]]],"1141":["(Mereka menanyakan kepadamu) yaitu mereka penduduk kota Mekah (tentang kiamat,) tentang hari akhir (\"Bilakah) kapan (terjadinya?\" Katakanlah,) kepada mereka (\"Sesungguhnya pengetahuan tentang kiamat itu) bila terjadinya (adalah pada sisi Tuhanku; tidak seorang pun yang dapat menjelaskan) menerangkan (waktu kedatangannya) huruf lam bermakna fii (selain Dia. Kiamat itu amat berat) amat besar peristiwanya (yang di langit dan di bumi) amat berat dirasakan oleh penduduk keduanya mengingat kengerian huru-haranya. (Kiamat itu tidak akan datang kepadamu melainkan dengan tiba-tiba.\") secara sekonyong-konyong (Mereka bertanya kepadamu seolah-olah kamu benar-benar mengetahui) terlalu berlebihan di dalam bertanya (tentang kiamat itu) sehingga engkau memberitahukan tentangnya. (Katakanlah, \"Sesungguhnya pengetahuan tentang kiamat itu adalah di sisi Allah) merupakan pengukuhan sebelumnya (tetapi kebanyakan manusia tidak mengetahui.\") pengetahuan mengenai kiamat itu hanya ada di sisi Allah swt.",[["يَسْـَٔلُونَكَ","Mereka bertanya kepada kamu"],["عَنِ","tentang"],["ٱلسَّاعَةِ","Jam itu"],["أَيَّانَ","apabila akan jadi"],["مُرْسَىٰهَا ۖ","masa yang ditetapkan"],["قُلْ","Katakanlah"],["إِنَّمَا","Hanya"],["عِلْمُهَا","pengetahuannya"],["عِندَ","(adalah) dengan"],["رَبِّى ۖ","Tuhanku"],["لَا","tiada (satu)"],["يُجَلِّيهَا","boleh mendedahkan [ia]"],["لِوَقْتِهَآ","masanya"],["إِلَّا","kecuali"],["هُوَ ۚ","Dia"],["ثَقُلَتْ","Ia terletak dengan berat"],["فِى","dalam"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضِ ۚ","dan bumi"],["لَا","Tidak"],["تَأْتِيكُمْ","adakah ia akan datang kepada kamu"],["إِلَّا","tetapi"],["بَغْتَةًۭ ۗ","tiba-tiba"],["يَسْـَٔلُونَكَ","Mereka bertanya kepada kamu"],["كَأَنَّكَ","seolah-olah kamu"],["حَفِىٌّ","(telah) dimaklumkan dengan baik"],["عَنْهَا ۖ","mengenainya"],["قُلْ","Katakanlah"],["إِنَّمَا","Hanya"],["عِلْمُهَا","pengetahuannya"],["عِندَ","(adalah) dengan"],["ٱللَّهِ","Allah"],["وَلَـٰكِنَّ","tetapi"],["أَكْثَرَ","kebanyakannya"],["ٱلنَّاسِ","(daripada) rakyat"],["لَا","jangan"],["يَعْلَمُونَ","mengetahui"]]],"1142":["(Katakanlah, \"Aku tidak berkuasa menarik kemanfaatan bagi diriku sendiri) untuk mendapatkannya (dan tidak pula menolak kemudaratan) mampu menolaknya (kecuali yang dikehendaki Allah. Dan sekiranya aku mengetahui yang gaib) apa-apa yang gaib dariku (tentulah aku membuat kebaikan sebanyak-banyaknya dan aku tidak akan ditimpa kemudaratan) berupa kemiskinan dan lain sebagainya karena sebelumnya aku telah bersiap-siap menghadapinya dengan cara menghindari kemudaratan-kemudaratan itu (tidak lain) (aku ini hanyalah pemberi peringatan) dengan neraka bagi orang-orang kafir (dan pembawa berita gembira) dengan surga (bagi orang-orang yang beriman\").",[["قُل","Katakanlah"],["لَّآ","Tidak"],["أَمْلِكُ","Aku ada kuasa"],["لِنَفْسِى","untuk diri aku sendiri"],["نَفْعًۭا","(untuk) mendapat manfaat"],["وَلَا","dan tidak"],["ضَرًّا","(kuasa untuk) membahayakan"],["إِلَّا","kecuali"],["مَا","apa"],["شَآءَ","wasiat"],["ٱللَّهُ ۚ","Allah"],["وَلَوْ","Dan jika"],["كُنتُ","aku akan"],["أَعْلَمُ","mengetahui"],["ٱلْغَيْبَ","(dari) perkara ghaib"],["لَٱسْتَكْثَرْتُ","nescaya aku boleh berlipat ganda"],["مِنَ","daripada"],["ٱلْخَيْرِ","yang baik"],["وَمَا","dan bukan"],["مَسَّنِىَ","(boleh) menyentuh aku"],["ٱلسُّوٓءُ ۚ","yang jahat"],["إِنْ","Tidak"],["أَنَا۠","(aku) aku"],["إِلَّا","kecuali"],["نَذِيرٌۭ","seorang pemberi amaran"],["وَبَشِيرٌۭ","dan pembawa berita gembira"],["لِّقَوْمٍۢ","kepada sesuatu kaum"],["يُؤْمِنُونَ","yang beriman"]]],"1143":["(Dialah) Allahlah (yang menciptakan kamu dari diri yang satu) yaitu Adam (dan Dia menjadikan) Dia menciptakan (daripadanya istrinya) yakni Hawa (agar dia merasa tenang) Adam menjimaknya (istrinya itu mengandung kandungan yang ringan) berupa air mani (dan teruslah dia merasa ringan) masih bisa berjalan ke sana dan kemari mengingat ringannya kandungan (kemudian tatkala dia merasa berat) anak yang ada dalam perutnya makin membesar, kemudian ia merasa khawatir bahwa kandungannya itu nanti berupa hewan (keduanya bermohon kepada Allah Tuhannya seraya berkata, \"Sesungguhnya jika Engkau memberi kami) anak (yang saleh) yang sempurna (tentulah kami termasuk orang-orang yang bersyukur.\") kepada-Mu atas karunia itu.",[["۞ هُوَ","Dia"],["ٱلَّذِى","(ialah) Yang"],["خَلَقَكُم","mencipta kamu"],["مِّن","daripada"],["نَّفْسٍۢ","sebuah jiwa"],["وَٰحِدَةٍۢ","bujang"],["وَجَعَلَ","dan dibuat"],["مِنْهَا","daripadanya"],["زَوْجَهَا","jodohnya"],["لِيَسْكُنَ","supaya dia boleh hidup"],["إِلَيْهَا ۖ","dengan dia"],["فَلَمَّا","Dan apabila"],["تَغَشَّىٰهَا","dia selimutkan dia"],["حَمَلَتْ","dia bawa"],["حَمْلًا","suatu beban"],["خَفِيفًۭا","ringan"],["فَمَرَّتْ","dan berterusan"],["بِهِۦ ۖ","dengannya"],["فَلَمَّآ","Tetapi apabila"],["أَثْقَلَت","dia bertambah berat"],["دَّعَوَا","mereka berdua menyeru"],["ٱللَّهَ","Allah"],["رَبَّهُمَا","Tuhan mereka"],["لَئِنْ","Jika"],["ءَاتَيْتَنَا","Kamu berikan kami"],["صَـٰلِحًۭا","seorang yang soleh (anak)"],["لَّنَكُونَنَّ","pasti kita akan jadi"],["مِنَ","antara"],["ٱلشَّـٰكِرِينَ","yang bersyukur"]]],"1144":["(Tatkala Allah memberi kepada keduanya) seorang anak (yang saleh, maka keduanya menjadikan sekutu bagi Allah) dalam suatu qiraat dibaca dengan dikasrahkan syinnya dan tanwin pada huruf akhirnya; yakni sekutu (tentang anak yang dianugerahkan-Nya kepada mereka berdua) dengan menamakannya Abdul Harits, sedangkan tidak boleh seorang hamba menjadi hamba selain kepada Allah. Yang dimaksud dalam penyekutuan di sini bukanlah dalam masalah ubudiah/ibadah, karena Nabi Adam telah dimaksum dari hal semacam itu. Samurah telah meriwayatkan dari Nabi saw. yang pernah bersabda bahwa ketika Hawa melahirkan seorang anak, iblis bertawaf mengelilingi Siti Hawa; sebelumnya anak Siti Hawa belum pernah ada yang hidup, kemudian iblis berkata kepadanya, \"Namakanlah dia anakmu yang baru lahir itu Abdul Harits, maka ia kelak akan hidup.\" Anak itu ternyata dapat hidup, hal itu terjadi karena ada saran dari setan dan perintah darinya, demikianlah menurut apa yang diriwayatkan oleh Al-Hakim. Al-Hakim mengatakan bahwa hadis ini sahih; Tirmizi mengatakan bahwa predikat hadis ini hasan gharib (Maka Maha Tinggi Allah dari apa yang mereka persekutukan) yakni penduduk Mekah dengan menjadikan berhala-berhala sebagai sesembahan mereka. Jumlah ayat ini merupakan musabbab atau penyebab, dan diathafkan kepada lafal khalaqakum, dan di antara sabab dengan musababnya terhadap jumlah mu`taridhah.",[["فَلَمَّآ","Tetapi apabila"],["ءَاتَىٰهُمَا","Dia memberi mereka"],["صَـٰلِحًۭا","seorang yang baik, (anak)"],["جَعَلَا","mereka buat"],["لَهُۥ","untuk Dia"],["شُرَكَآءَ","rakan kongsi"],["فِيمَآ","pada apa"],["ءَاتَىٰهُمَا ۚ","Dia telah memberi mereka"],["فَتَعَـٰلَى","Tetapi ditinggikan"],["ٱللَّهُ","(ialah) Allah"],["عَمَّا","atas apa"],["يُشْرِكُونَ","mereka mempersekutukan (dengan Dia)"]]],"1145":["(Apakah mereka mempersekutukan) Allah dalam ibadah (dengan berhala-berhala yang tak dapat menciptakan sesuatu pun? Sedangkan berhala-berhala itu sendiri buatan orang).",[["أَيُشْرِكُونَ","Adakah mereka bergaul"],["مَا","apa"],["لَا","(boleh) tidak"],["يَخْلُقُ","cipta"],["شَيْـًۭٔا","sesuatu"],["وَهُمْ","dan mereka"],["يُخْلَقُونَ","dicipta"]]],"1146":["(Dan berhala-berhala itu terhadap mereka tidak dapat) terhadap para pengabdinya (memberikan pertolongan, dan kepada dirinya sendiri pun berhala-berhala itu tidak dapat memberi pertolongan) tidak dapat mencegah orang yang bermaksud merusak mereka, apakah orang itu mau memecahkannya atau mau berbuat yang lain. Istifham/kata tanya di sini mempunyai pengertian untuk mencemoohkan.",[["وَلَا","Dan tidak"],["يَسْتَطِيعُونَ","mereka mampu"],["لَهُمْ","untuk (memberi) mereka"],["نَصْرًۭا","sebarang bantuan"],["وَلَآ","dan bukan"],["أَنفُسَهُمْ","diri mereka"],["يَنصُرُونَ","bolehkah mereka membantu"]]],"1147":["(Dan jika kamu menyerunya) menyeru berhala-berhala itu (untuk memberi petunjuk kepadamu, tidaklah berhala-berhala itu dapat memperkenankan seruanmu) dengan memakai takhfif dan tasydid (sama saja hasilnya buat kamu menyeru mereka) untuk meminta petunjuk (atau pun kamu berdiam diri) tidak menyeru mereka, maka mereka pasti tidak dapat memenuhi permintaanmu karena mereka tidak dapat mendengar.",[["وَإِن","Dan jika"],["تَدْعُوهُمْ","kamu memanggil mereka"],["إِلَى","kepada"],["ٱلْهُدَىٰ","bimbingan"],["لَا","tidak"],["يَتَّبِعُوكُمْ ۚ","adakah mereka akan mengikut kamu"],["سَوَآءٌ","(Ia) sama"],["عَلَيْكُمْ","bagi kamu"],["أَدَعَوْتُمُوهُمْ","sama ada kamu memanggil mereka"],["أَمْ","atau"],["أَنتُمْ","kamu"],["صَـٰمِتُونَ","berdiam diri"]]],"1148":["(Sesungguhnya berhala-berhala yang kamu seru) yang kamu sembah (selain Allah itu adalah makhluk yang lemah) hamba-hamba (yang serupa juga dengan kamu. Maka serulah berhala-berhala itu lalu biarkanlah mereka memperkenankan permintaanmu) doa kamu (jika kami memang orang-orang yang benar) dalam anggapanmu bahwa mereka adalah tuhan. Kemudian Allah menjelaskan tentang kelemahan berhala-berhala tersebut dan Dia menjelaskan pula bahwa justru para pengabdinyalah yang lebih utama dari berhala-berhala itu sendiri. Untuk itu Allah berfirman:",[["إِنَّ","Sesungguhnya"],["ٱلَّذِينَ","mereka yang"],["تَدْعُونَ","kamu panggil"],["مِن","daripada"],["دُونِ","selain"],["ٱللَّهِ","Allah"],["عِبَادٌ","(adalah) hamba"],["أَمْثَالُكُمْ ۖ","macam kamu"],["فَٱدْعُوهُمْ","Maka serulah mereka"],["فَلْيَسْتَجِيبُوا۟","dan biarkan mereka bertindak balas"],["لَكُمْ","kepada kamu"],["إِن","jika"],["كُنتُمْ","kamu"],["صَـٰدِقِينَ","jujur"]]],"1149":["(Apakah berhala-berhala itu mempunyai kaki yang dengan itu mereka dapat berjalan atau) bahkan apakah (mereka mempunyai tangan-tangan) bentuk jamak dari lafal yadun/tangan (yang dengan tangan-tangan itu mereka dapat memukul atau) bahkan apakah (mereka mempunyai mata yang dengan mata itu mereka dapat melihat atau) bahkan apakah (mereka mempunyai telinga yang dengan telinga itu mereka dapat mendengar?) kata tanya yang terdapat di dalam ayat ini menunjukkan makna ingkar. Yakni bahwa berhala-berhala itu tidak mempunyai sesuatu pun dari hal-hal tersebut seperti apa yang kamu sekalian miliki. Lalu mengapa kamu menyembahnya sedang diri kamu sendiri keadaannya jauh lebih baik daripada mereka. (Katakanlah) kepada mereka, hai Muhammad (\"Panggillah berhala-berhalamu yang kamu jadikan sekutu bagi Allah itu) untuk mencelakakanku (kemudian lakukanlah tipu-daya kepadaku tanpa memberi tangguh kepadaku\") memberi tenggang waktu karena aku tidak lagi memperdulikanmu.",[["أَلَهُمْ","Adakah untuk mereka"],["أَرْجُلٌۭ","kaki"],["يَمْشُونَ","(untuk) berjalan"],["بِهَآ ۖ","dengan [ia]"],["أَمْ","atau"],["لَهُمْ","bagi mereka"],["أَيْدٍۢ","tangan"],["يَبْطِشُونَ","(untuk) memegang"],["بِهَآ ۖ","dengan [ia]"],["أَمْ","atau"],["لَهُمْ","bagi mereka"],["أَعْيُنٌۭ","mata"],["يُبْصِرُونَ","(untuk) melihat"],["بِهَآ ۖ","dengan [ia]"],["أَمْ","atau"],["لَهُمْ","bagi mereka"],["ءَاذَانٌۭ","telinga"],["يَسْمَعُونَ","(untuk) mendengar"],["بِهَا ۗ","dengan [ia]"],["قُلِ","Katakanlah"],["ٱدْعُوا۟","Panggil"],["شُرَكَآءَكُمْ","rakan kongsi kamu"],["ثُمَّ","kemudian"],["كِيدُونِ","rancangan terhadap aku"],["فَلَا","dan jangan"],["تُنظِرُونِ","beri aku tangguh"]]],"1150":["(Sesungguhnya pelindungku ialah Allah) yang mengurusi perkaraku (yang telah menurunkan Alkitab) Alquran (dan Dia melindungi orang-orang yang saleh) memeliharanya.",[["إِنَّ","Sesungguhnya"],["وَلِـِّۧىَ","pelindung aku"],["ٱللَّهُ","(ialah) Allah"],["ٱلَّذِى","yang Esa"],["نَزَّلَ","didedahkan"],["ٱلْكِتَـٰبَ ۖ","Kitab"],["وَهُوَ","Dan Dia"],["يَتَوَلَّى","melindungi"],["ٱلصَّـٰلِحِينَ","orang yang soleh"]]],"1151":["(Dan berhala-berhala yang kamu seru selain Allah tidaklah sanggup menolongmu, bahkan tidak dapat menolong dirinya sendiri) lalu mengapa aku mempedulikan keadaan mereka.",[["وَٱلَّذِينَ","Dan mereka yang"],["تَدْعُونَ","kamu menyeru"],["مِن","daripada"],["دُونِهِۦ","selain Dia"],["لَا","tidak"],["يَسْتَطِيعُونَ","mereka mampu"],["نَصْرَكُمْ","(untuk) membantu kamu"],["وَلَآ","dan bukan"],["أَنفُسَهُمْ","diri mereka"],["يَنصُرُونَ","bolehkah mereka membantu"]]],"1152":["(Dan jika kamu sekalian menyeru mereka) berhala-berhala itu (untuk memberi petunjuk, niscaya berhala-berhala tidak dapat mendengarnya. Dan kamu melihat mereka) berhala-berhala itu, hai Muhammad (memandang kepadamu) yakni, mereka berhadapan denganmu bagaikan orang yang sedang memandang (padahal mereka tidak dapat melihat).",[["وَإِن","Dan jika"],["تَدْعُوهُمْ","kamu memanggil mereka"],["إِلَى","kepada"],["ٱلْهُدَىٰ","bimbingan"],["لَا","tidak"],["يَسْمَعُوا۟ ۖ","adakah mereka tidak"],["وَتَرَىٰهُمْ","Dan kamu melihat mereka"],["يَنظُرُونَ","mencari"],["إِلَيْكَ","pada kamu"],["وَهُمْ","tetapi mereka"],["لَا","tidak"],["يُبْصِرُونَ","(adakah) mereka melihat"]]],"1153":["(Jadilah engkau pemaaf) mudah memaafkan di dalam menghadapi perlakuan orang-orang, dan jangan membalas (dan suruhlah orang mengerjakan makruf) perkara kebaikan (serta berpalinglah daripada orang-orang yang bodoh) janganlah engkau melayani kebodohan mereka.",[["خُذِ","tahan"],["ٱلْعَفْوَ","(untuk) pengampunan"],["وَأْمُرْ","dan menyuruh"],["بِٱلْعُرْفِ","yang baik"],["وَأَعْرِضْ","dan berpaling"],["عَنِ","daripada"],["ٱلْجَـٰهِلِينَ","yang jahil"]]],"1154":["(Dan jika) lafal immaa merupakan gabungan antara in syarthiah dan maa zaidah atau tambahan (kamu ditimpa suatu godaan setan) dimaksud jika setan memalingkan kamu dari apa yang kamu diperintahkan untuk melakukannya dengan suatu godaan (maka berlindunglah kepada Allah) sebagai jawab syarath sedangkan jawab amarnya dibuang, yaitu guna menolak setan daripada dirimu (sesungguhnya Allah Maha Mendengar) semua perkataan (lagi Maha Mengetahui) semua pekerjaan.",[["وَإِمَّا","Dan jika"],["يَنزَغَنَّكَ","cadangan jahat datang kepada kamu"],["مِنَ","daripada"],["ٱلشَّيْطَـٰنِ","Syaitan"],["نَزْغٌۭ","[cadangan jahat]"],["فَٱسْتَعِذْ","maka berlindunglah"],["بِٱللَّهِ ۚ","kepada Allah"],["إِنَّهُۥ","Sesungguhnya Dia"],["سَمِيعٌ","(ialah) Maha Mendengar"],["عَلِيمٌ","Maha Mengetahui"]]],"1155":["(Sesungguhnya orang-orang yang bertakwa bila mereka ditimpa) terkena (was-was) menurut suatu qiraat dibaca thaifun bukan thaaifun, artinya sesuatu yang menimpa mereka (dari setan mereka ingat) akan siksa Allah dan pahala-Nya (maka ketika itu mereka melihat) perbedaan antara perkara yang hak dan yang batil lalu mereka kembali kepada jalan yang hak.",[["إِنَّ","Sesungguhnya"],["ٱلَّذِينَ","orang yang"],["ٱتَّقَوْا۟","takut (Allah)"],["إِذَا","apabila"],["مَسَّهُمْ","menyentuh mereka"],["طَـٰٓئِفٌۭ","pemikiran jahat"],["مِّنَ","daripada"],["ٱلشَّيْطَـٰنِ","syaitan"],["تَذَكَّرُوا۟","mereka ingat (Allah)"],["فَإِذَا","dan kemudian"],["هُم","mereka"],["مُّبْصِرُونَ","(ialah) orang-orang yang melihat (benar)"]]],"1156":["(Dan teman-teman mereka) yaitu teman-teman setan terdiri dari orang-orang kafir (membantu mereka) setan-setan itu (dalam menyesatkan kemudian) mereka (tidak henti-hentinya) di dalam menyesatkan dengan sikap penuh hati-hati sebagaimana orang-orang yang takwa pun berhati-hati terhadap godaan mereka.",[["وَإِخْوَٰنُهُمْ","Tetapi saudara mereka"],["يَمُدُّونَهُمْ","mereka menjunam mereka"],["فِى","dalam"],["ٱلْغَىِّ","kesilapan itu"],["ثُمَّ","kemudian"],["لَا","tidak"],["يُقْصِرُونَ","mereka berhenti"]]],"1157":["(Dan apabila kamu tidak membawa kepada mereka) kepada penduduk Mekah (suatu ayat) seperti apa yang mereka minta (mereka berkata, \"Mengapa tidak) (kamu buat-buat ayat itu?\") artinya kamu buat sendiri ayat itu? (Katakanlah,) kepada mereka (\"Sesungguhnya aku hanya mengikut apa yang diwahyukan kepadaku dari Tuhanku) aku tidak berhak untuk mendatangkannya dari diriku sendiri. (Ini) Alquran ini (adalah bukti-bukti yang jelas) hujah-hujah (dari Tuhanmu, petunjuk dan rahmat bagi orang-orang yang beriman.\")",[["وَإِذَا","Dan apabila"],["لَمْ","tidak"],["تَأْتِهِم","kamu bawa mereka"],["بِـَٔايَةٍۢ","sebuah Tanda"],["قَالُوا۟","mereka berkata"],["لَوْلَا","Mengapa (belum) tidak"],["ٱجْتَبَيْتَهَا ۚ","kamu menciptanya"],["قُلْ","Katakanlah"],["إِنَّمَآ","Hanya"],["أَتَّبِعُ","aku ikut"],["مَا","apa"],["يُوحَىٰٓ","didedahkan"],["إِلَىَّ","kepada aku"],["مِن","daripada"],["رَّبِّى ۚ","Tuhanku"],["هَـٰذَا","ini (ialah)"],["بَصَآئِرُ","pencerahan"],["مِن","daripada"],["رَّبِّكُمْ","Tuhanmu"],["وَهُدًۭى","dan bimbingan"],["وَرَحْمَةٌۭ","dan belas kasihan"],["لِّقَوْمٍۢ","bagi kaum"],["يُؤْمِنُونَ","yang beriman"]]],"1158":["(Dan apabila dibacakan Alquran, maka dengarkanlah baik-baik dan perhatikanlah) jangan berbicara (agar kamu mendapat rahmat) ayat ini diturunkan sehubungan dengan perintah tidak boleh berbicara sewaktu khutbah Jumat yang diungkapkan oleh ayat ini dengan istilah Alquran, mengingat khutbah itu mengandung ayat-ayat Alquran. Menurut pendapat lain berkaitan dengan pembacaan Alquran secara mutlak.",[["وَإِذَا","Dan apabila"],["قُرِئَ","dibacakan"],["ٱلْقُرْءَانُ","al-Quran"],["فَٱسْتَمِعُوا۟","kemudian dengar"],["لَهُۥ","kepadanya"],["وَأَنصِتُوا۟","dan beri perhatian"],["لَعَلَّكُمْ","supaya kamu"],["تُرْحَمُونَ","mendapat rahmat"]]],"1159":["(Dan sebutlah nama Tuhanmu di dalam hatimu) secara diam-diam (dengan merendahkan diri) menghinakan diri (dan rasa takut) yakni takut terhadap-Nya (dan) lebih jelas lagi daripada diam-diam dengan (tidak mengeraskan suara) maksudnya pertengahan di antara diam-diam dan keras suara (di waktu pagi dan petang) pada permulaan siang hari dan pada akhir siang hari (dan janganlah kamu termasuk orang-orang yang lalai) daripada mengingat atau menyebut Allah.",[["وَٱذْكُر","Dan ingat"],["رَّبَّكَ","Tuhanmu"],["فِى","dalam"],["نَفْسِكَ","diri sendiri"],["تَضَرُّعًۭا","dengan rendah hati"],["وَخِيفَةًۭ","dan (dalam) ketakutan"],["وَدُونَ","dan tanpa"],["ٱلْجَهْرِ","bunyinya"],["مِنَ","daripada"],["ٱلْقَوْلِ","[the] perkataan"],["بِٱلْغُدُوِّ","pada waktu pagi"],["وَٱلْـَٔاصَالِ","dan (pada) petang"],["وَلَا","Dan jangan"],["تَكُن","jadilah"],["مِّنَ","antara"],["ٱلْغَـٰفِلِينَ","yang lalai"]]],"1160":["(Sesungguhnya mereka yang berada di sisi Tuhanmu) yakni malaikat-malaikat-Nya (tidaklah merasa enggan) tidak takabur (untuk menyembah Allah dan mereka bertasbih kepada-Nya) menyucikan-Nya dari hal-hal yang tidak layak menjadi sifat-Nya (dan hanya kepada-Nyalah mereka bersujud) mereka secara khusus tunduk dan bersujud hanya kepada-Nya, maka jadilah kamu sekalian seperti mereka.",[["إِنَّ","Sesungguhnya"],["ٱلَّذِينَ","orang yang"],["عِندَ","(ada) dekat"],["رَبِّكَ","Tuhanmu"],["لَا","tidak"],["يَسْتَكْبِرُونَ","(adakah) mereka berpaling dengan menyombongkan diri"],["عَنْ","daripada"],["عِبَادَتِهِۦ","ibadatnya"],["وَيُسَبِّحُونَهُۥ","Dan mereka memuliakan Dia"],["وَلَهُۥ","dan kepada-Nya"],["يَسْجُدُونَ ۩","mereka sujud"]]],"1161":["(Mereka menanyakan kepadamu) hai Muhammad (tentang harta rampasan) perang, siapakah yang berhak menerimanya (Katakanlah,) kepada mereka (\"Harta rampasan perang itu kepunyaan Allah dan rasul-Nya) harta rampasan perang itu terserah menurut kesukaan Allah dan rasul-Nya; kemudian Rasulullah saw. membagi-bagikan harta rampasan itu secara merata kepada mereka semuanya. Demikianlah menurut hadis yang diriwayatkan oleh Imam Al-Hakim di dalam kitab Al-Mustadrak (sebab itu bertakwalah kalian kepada Allah dan perbaikilah hubungan di antara sesamamu) yakni jalinlah kembali hubungan antara kalian dengan penuh kecintaan dan tinggalkanlah persengketaan (dan taatlah kalian kepada Allah dan rasul-Nya, jika kamu adalah orang-orang yang beriman.\") yang benar-benar beriman.",[["يَسْـَٔلُونَكَ","Mereka bertanya kepada kamu"],["عَنِ","tentang"],["ٱلْأَنفَالِ ۖ","harta rampasan perang"],["قُلِ","Katakanlah"],["ٱلْأَنفَالُ","Harta rampasan perang"],["لِلَّهِ","(adalah) untuk Allah"],["وَٱلرَّسُولِ ۖ","dan Rasul"],["فَٱتَّقُوا۟","Jadi takut"],["ٱللَّهَ","Allah"],["وَأَصْلِحُوا۟","dan betulkan"],["ذَاتَ","bahawa"],["بَيْنِكُمْ ۖ","(iaitu) antara kamu"],["وَأَطِيعُوا۟","dan taat"],["ٱللَّهَ","Allah"],["وَرَسُولَهُۥٓ","dan Rasul-Nya"],["إِن","jika"],["كُنتُم","kamu"],["مُّؤْمِنِينَ","orang yang beriman"]]],"1162":["(Sesungguhnya orang-orang yang beriman itu) yang sempurna keimanannya (adalah mereka yang apabila disebut Allah) yakni ancaman-Nya (gemetarlah) karena takut (hati mereka dan apabila dibacakan kepada mereka ayat-ayat-Nya bertambahlah keimanan mereka) kepercayaan mereka (dan kepada Tuhanlah mereka bertawakal) hanya kepada Rabblah mereka percaya bukan kepada selain-Nya.",[["إِنَّمَا","Hanya"],["ٱلْمُؤْمِنُونَ","orang yang beriman"],["ٱلَّذِينَ","(adalah) mereka yang"],["إِذَا","apabila"],["ذُكِرَ","disebut"],["ٱللَّهُ","Allah"],["وَجِلَتْ","rasa takut"],["قُلُوبُهُمْ","hati mereka"],["وَإِذَا","dan apabila"],["تُلِيَتْ","dibacakan"],["عَلَيْهِمْ","kepada mereka"],["ءَايَـٰتُهُۥ","Ayat-ayatNya"],["زَادَتْهُمْ","mereka menambahnya"],["إِيمَـٰنًۭا","(dalam) iman"],["وَعَلَىٰ","dan seterusnya"],["رَبِّهِمْ","Tuhan mereka"],["يَتَوَكَّلُونَ","mereka meletakkan kepercayaan mereka"]]],"1163":["(Yaitu orang-orang yang mendirikan salat) mereka menunaikannya sesuai dengan ketentuan-ketentuannya (dan sebagian dari apa yang telah Kami berikan kepada mereka) Kami anugerahkan kepada mereka (mereka menafkahkannya) demi taat kepada Allah.",[["ٱلَّذِينَ","Orang yang"],["يُقِيمُونَ","dirikanlah"],["ٱلصَّلَوٰةَ","solat"],["وَمِمَّا","dan sebahagian daripada apa"],["رَزَقْنَـٰهُمْ","Kami rezekikan kepada mereka"],["يُنفِقُونَ","mereka nafkahkan"]]],"1164":["(Itulah) orang-orang yang berciri khas seperti tadi (mereka orang-orang yang beriman dengan sebenar-benarnya) yang tidak diragukan lagi keimanannya. (Mereka akan memperoleh beberapa derajat ketinggian) kedudukan-kedudukan di surga (di sisi Tuhannya dan ampunan serta rezeki yang mulia) di surga.",[["أُو۟لَـٰٓئِكَ","Itu"],["هُمُ","mereka adalah"],["ٱلْمُؤْمِنُونَ","orang yang beriman"],["حَقًّۭا ۚ","(dalam) kebenaran"],["لَّهُمْ","Untuk mereka"],["دَرَجَـٰتٌ","(adalah) pangkat"],["عِندَ","dengan"],["رَبِّهِمْ","Tuhan mereka"],["وَمَغْفِرَةٌۭ","dan pengampunan"],["وَرِزْقٌۭ","dan peruntukan"],["كَرِيمٌۭ","mulia"]]],"1165":["(Sebagaimana Tuhanmu menyuruhmu pergi dari rumahmu dengan kebenaran) jar dan majrur berta`alluq pada lafal akhraja (padahal sesungguhnya sebagian dari orang-orang yang beriman itu tidak menyukainya) yakni mereka tidak menyukai keluar bersama Nabi. Jumlah kalimat maa akhrajaka dan seterusnya merupakan keterangan keadaan dari huruf kaf yang terdapat pada lafal kamaa. Kemudian lafal kamaa akhrajaka berkedudukan menjadi khabar atau kalimat berita dari mubtada yang dibuang, yakni keadaan yang tidak mereka sukai adalah sewaktu engkau diminta keluar sedangkan mereka tidak menyukai hal itu, padahal itu baik untuk mereka, demikianlah keadaan mereka. Demikian itu karena Abu Sofyan yang datang membawa kafilah perdagangan dari negeri Syam, beritanya sampai kepada Nabi saw. Maka Nabi saw. segera keluar bersama para sahabat guna mencegah kafilah tersebut. Akan tetapi berita keberangkatannya diketahui oleh orang-orang Quraisy. Maka keluarlah Abu Jahal beserta pasukan perang kota Mekah untuk melindungi kafilahnya itu, mereka bersenjata lengkap dan banyak pasukannya. Abu Sofyan membawa kafilahnya mengikuti jalan tepi pantai sehingga selamatlah mereka dari cegatan kaum Muslimin. Lalu ada yang berkata kepada Abu Jahal, \"Mari kita kembali.\" Akan tetapi Abu Jahal menolak dan bahkan terus bermusyawarah dengan para sahabatnya; Nabi saw. bersabda kepada mereka, \"Sesungguhnya Allah swt. telah menjanjikan kepadaku kemenangan atas salah satu dari dua rombongan,\" yaitu rombongan Abu Sofyan atau rombongan Abu Jahal. Akhirnya mereka sepakat untuk memerangi pasukan yang bersenjata; tetapi sebagian dari kaum Mukminin tidak menyukai hal itu, mereka mengatakan, \"Kami masih belum siap untuk menghadapi hal itu,\" sebagaimana yang diungkapkan oleh firman-Nya berikut ini:",[["كَمَآ","Sebagai"],["أَخْرَجَكَ","membawa kamu keluar"],["رَبُّكَ","Tuhanmu"],["مِنۢ","daripada"],["بَيْتِكَ","rumah kamu"],["بِٱلْحَقِّ","dalam kebenaran"],["وَإِنَّ","sedangkan memang"],["فَرِيقًۭا","sebuah parti"],["مِّنَ","antara"],["ٱلْمُؤْمِنِينَ","orang yang beriman"],["لَكَـٰرِهُونَ","sudah tentu tidak suka"]]],"1166":["(Mereka membantahmu tentang kebenaran) yaitu tentang alternatif berperang (sesudah nyata) sesudah jelas bagi mereka bahwa mereka pasti menang (seolah-olah mereka dihalau kepada kematian sedang mereka melihat) kematian itu secara terang-terangan yang membuat mereka tidak senang kepadanya.",[["يُجَـٰدِلُونَكَ","Mereka berselisih dengan kamu"],["فِى","tentang"],["ٱلْحَقِّ","kebenaran"],["بَعْدَ مَا","selepas apa"],["تَبَيَّنَ","telah dibuat dengan jelas"],["كَأَنَّمَا","seolah-olah"],["يُسَاقُونَ","mereka dihalau"],["إِلَى","kepada"],["ٱلْمَوْتِ","[the] kematian"],["وَهُمْ","sedangkan mereka"],["يَنظُرُونَ","(sedang) mencari"]]],"1167":["(Dan) ingatlah (ketika Allah menjanjikan kepadamu salah satu dari dua golongan) yakni rombongan kafilah atau pasukan bersenjata (bahwa salah satu dari dua golongan yang kamu hadapi adalah untukmu, sedangkan kamu menginginkan) kalian hanya menghendaki (bahwa golongan yang tidak mempunyai kekuatan senjatalah) golongan yang tidak mempunyai kekuatan dan persenjataan, yaitu golongan kafilah dagang (yang untukmu) mengingat pengawalnya sedikit dan persenjataannya pun tidak lengkap, berbeda dengan golongan pasukan bersenjata (dan Allah menghendaki untuk membenarkan yang benar) menampakkan yang benar (dengan ayat-ayat-Nya) yang dahulu melalui kemenangan Islam (dan memusnahkan orang-orang kafir) kekuatan mereka dengan mengalahkan mereka, maka Dia memerintahkan kalian untuk memerangi pasukan bersenjata mereka.",[["وَإِذْ","Dan apabila"],["يَعِدُكُمُ","berjanji kepada kamu"],["ٱللَّهُ","Allah"],["إِحْدَى","satu"],["ٱلطَّآئِفَتَيْنِ","(dari) dua kumpulan itu"],["أَنَّهَا","bahawa ia (akan)"],["لَكُمْ","untuk kamu"],["وَتَوَدُّونَ","dan kamu mahu"],["أَنَّ","bahawa"],["غَيْرَ","(satu) selain daripada"],["ذَاتِ","bahawa"],["ٱلشَّوْكَةِ","(daripada) yang bersenjata"],["تَكُونُ","akan menjadi"],["لَكُمْ","bagi kamu"],["وَيُرِيدُ","Tetapi diniatkan"],["ٱللَّهُ","Allah"],["أَن","kepada"],["يُحِقَّ","mewajarkan"],["ٱلْحَقَّ","kebenaran"],["بِكَلِمَـٰتِهِۦ","dengan firman-Nya"],["وَيَقْطَعَ","dan terputus"],["دَابِرَ","(the) akar"],["ٱلْكَـٰفِرِينَ","(dari) orang-orang kafir"]]],"1168":["(Agar Allah menetapkan yang hak dan membatalkan) menghapus (kebatilan) yakni kekafiran (walaupun orang-orang yang berdosa itu tidak menyukainya) orang-orang musyrik tidak menyenangi hal itu.",[["لِيُحِقَّ","Supaya Dia membenarkan"],["ٱلْحَقَّ","kebenaran"],["وَيُبْطِلَ","dan membuktikan palsu"],["ٱلْبَـٰطِلَ","kepalsuan itu"],["وَلَوْ","walaupun"],["كَرِهَ","tidak suka (ia)"],["ٱلْمُجْرِمُونَ","penjenayah"]]],"1169":["(Ingatlah, ketika kamu memohon pertolongan Tuhanmu) ketika kamu meminta pertolongan dari-Nya untuk dapat mengalahkan orang-orang musyrik (lalu diperkenankan-Nya bagimu, \"Sesungguhnya Aku) sungguh Aku pasti (memberikan bantuan kepadamu) akan menolongmu (dengan mendatangkan seribu malaikat yang datang berturut-turut\") yakni mereka datang secara berturut-turut, sebagian dari mereka menyusul sebagian lainnya. Pada permulaannya Allah menjanjikan untuk mereka bantuan seribu malaikat, kemudian menjadi tiga ribu malaikat, hingga sampai lima ribu malaikat, seperti yang dijelaskan di dalam surah Ali Imran. Menurut suatu qiraat lafal alfun dibaca aalaf seperti aflas dalam bentuk jamak.",[["إِذْ","Apabila"],["تَسْتَغِيثُونَ","kamu sedang mencari bantuan"],["رَبَّكُمْ","Tuhanmu"],["فَٱسْتَجَابَ","dan Dia menjawab"],["لَكُمْ","[kepada] kamu"],["أَنِّى","Memang aku"],["مُمِدُّكُم","akan menguatkan kamu"],["بِأَلْفٍۢ","dengan seribu"],["مِّنَ","daripada"],["ٱلْمَلَـٰٓئِكَةِ","para Malaikat"],["مُرْدِفِينَ","satu demi satu"]]],"1170":["(Dan Allah tidak menjadikannya) bala bantuan tersebut (melainkan sebagian berita gembira dan agar hatimu menjadi tenteram karenanya. Dan kemenangan itu hanyalah dari sisi Allah. Sesungguhnya Allah Maha Perkasa lagi Maha Bijaksana).",[["وَمَا","Dan tidak"],["جَعَلَهُ","(ia) dibuat"],["ٱللَّهُ","(oleh) Allah"],["إِلَّا","tetapi"],["بُشْرَىٰ","khabar gembira"],["وَلِتَطْمَئِنَّ","dan supaya ia boleh berehat"],["بِهِۦ","dengannya"],["قُلُوبُكُمْ ۚ","hati kamu"],["وَمَا","Dan (ada) tidak"],["ٱلنَّصْرُ","[the] kemenangan"],["إِلَّا","kecuali"],["مِنْ","daripada"],["عِندِ","[daripada]"],["ٱللَّهِ ۚ","Allah"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["عَزِيزٌ","(adalah) Maha Perkasa"],["حَكِيمٌ","Maha Bijaksana"]]],"1171":["(Ingatlah, ketika Allah menjadikan kamu mengantuk sebagai suatu penenteram) untuk menenteramkan hatimu dari rasa takut yang menimpa dirimu (daripada-Nya) Allah Yang Maha Tinggi (dan Allah menurunkan kepadamu hujan dari langit untuk menyucikan kamu dengan hujan itu) dari hadas dan jinabah itu (dan menghilangkan dari kamu gangguan-gangguan setan) godaan setan dari dirimu yang mengatakan bahwasanya jika kamu berada dalam jalan kebenaran, niscaya kamu tidak akan kehausan lagi berhadas sedang kaum musyrikin berada dekat air (dan untuk menguatkan) mengokohkan (hatimu) dalam keyakinan dan kesabaran (dan memperteguh dengannya telapak kakimu) agar telapak kakimu berdiri tegar di padang pasir.",[["إِذْ","Apabila"],["يُغَشِّيكُمُ","Dia menutup kamu"],["ٱلنُّعَاسَ","dengan [yang] mengantuk"],["أَمَنَةًۭ","sebuah keselamatan"],["مِّنْهُ","daripadaNya"],["وَيُنَزِّلُ","dan diturunkan"],["عَلَيْكُم","ke atas kamu"],["مِّنَ","daripada"],["ٱلسَّمَآءِ","langit"],["مَآءًۭ","air"],["لِّيُطَهِّرَكُم","supaya Dia mensucikan kamu"],["بِهِۦ","dengannya"],["وَيُذْهِبَ","dan bawa pergi"],["عَنكُمْ","daripada kamu"],["رِجْزَ","jahat (cadangan)"],["ٱلشَّيْطَـٰنِ","(dari) syaitan"],["وَلِيَرْبِطَ","Dan untuk menguatkan"],["عَلَىٰ","[pada]"],["قُلُوبِكُمْ","hati kamu"],["وَيُثَبِّتَ","dan teguhkan"],["بِهِ","dengannya"],["ٱلْأَقْدَامَ","kaki kamu"]]],"1172":["(Ingatlah ketika Tuhanmu mewahyukan kepada para malaikat) yang diperbantukan kepada kaum Muslimin (\"Sesungguhnya Aku) bahwasanya Aku (bersama kamu) memberikan pertolongan dan bantuan (maka teguhkanlah pendirian orang-orang yang telah beriman) dengan memberikan pertolongan kepada mereka dan mengabarkan berita gembira. (Kelak Aku akan timpakan rasa ketakutan ke dalam hati orang-orang kafir) ketakutan yang sangat (maka penggallah leher mereka) kepala mereka (dan pancunglah tiap-tiap ujung jari mereka) ujung-ujung jari tangan dan kaki. Dikatakan bahwa dalam perang itu jika seseorang muslim hendak memukul kepala si kafir tiba-tiba kepala itu sudah jatuh menggelinding sendiri sebelum pedangnya sampai kepadanya. Dan Rasulullah saw. melempar mereka dengan segenggam batu kerikil, maka tidak ada seorang musyrik pun yang luput matanya dari lemparan batu kerikil itu, akhirnya mereka kalah.",[["إِذْ","Apabila"],["يُوحِى","diilhamkan"],["رَبُّكَ","Tuhanmu"],["إِلَى","kepada"],["ٱلْمَلَـٰٓئِكَةِ","para Malaikat"],["أَنِّى","aku"],["مَعَكُمْ","bersama kamu"],["فَثَبِّتُوا۟","jadi kuatkan"],["ٱلَّذِينَ","orang yang"],["ءَامَنُوا۟ ۚ","beriman"],["سَأُلْقِى","Aku akan membuang"],["فِى","dalam"],["قُلُوبِ","(the) hati"],["ٱلَّذِينَ","orang yang"],["كَفَرُوا۟","tidak beriman"],["ٱلرُّعْبَ","keganasan itu"],["فَٱضْرِبُوا۟","jadi mogok"],["فَوْقَ","di atas"],["ٱلْأَعْنَاقِ","leher"],["وَٱضْرِبُوا۟","dan mogok"],["مِنْهُمْ","daripada mereka"],["كُلَّ","setiap"],["بَنَانٍۢ","hujung jari"]]],"1173":["(Yang demikian itu) azab yang menimpa mereka itu (adalah karena sesungguhnya mereka menentang) melawan (Allah dan rasul-Nya; dan barang siapa menentang Allah dan rasul-Nya, maka sesungguhnya Allah amat keras siksaan-Nya) terhadapnya.",[["ذَٰلِكَ","Itu"],["بِأَنَّهُمْ","(adalah) kerana mereka"],["شَآقُّوا۟","menentang"],["ٱللَّهَ","Allah"],["وَرَسُولَهُۥ ۚ","dan Rasul-Nya"],["وَمَن","Dan sesiapa"],["يُشَاقِقِ","menentang"],["ٱللَّهَ","Allah"],["وَرَسُولَهُۥ","dan Rasul-Nya"],["فَإِنَّ","maka sesungguhnya"],["ٱللَّهَ","Allah"],["شَدِيدُ","(adalah) teruk"],["ٱلْعِقَابِ","dalam penalti"]]],"1174":["(Itulah) hukuman yang ditimpakan atasmu (maka rasakanlah hukuman itu) hai orang-orang kafir, sebagai hukuman di dunia (sesungguhnya bagi orang-orang yang kafir itu) kelak di hari kemudian (azab neraka\").",[["ذَٰلِكُمْ","Itu"],["فَذُوقُوهُ","Jadi rasalah"],["وَأَنَّ","Dan bahawa"],["لِلْكَـٰفِرِينَ","bagi orang-orang kafir"],["عَذَابَ","(adalah) hukuman"],["ٱلنَّارِ","(dari) api"]]],"1175":["(Hai orang-orang yang beriman, jika kamu bertemu dengan orang-orang yang kafir yang sedang menyerangmu) mereka menghimpun kekuatan dalam jumlah yang banyak sehingga mereka kelihatan seakan-akan merayap maju (maka janganlah kamu membelakangi mereka) dalam keadaan lari karena kalah.",[["يَـٰٓأَيُّهَا","Wahai"],["ٱلَّذِينَ","yang"],["ءَامَنُوٓا۟","beriman"],["إِذَا","Apabila"],["لَقِيتُمُ","kamu jumpa"],["ٱلَّذِينَ","orang yang"],["كَفَرُوا۟","kufur"],["زَحْفًۭا","memajukan"],["فَلَا","maka (buat) jangan"],["تُوَلُّوهُمُ","berpaling kepada mereka"],["ٱلْأَدْبَارَ","bahagian belakang"]]],"1176":["(Barang siapa yang membelakangi mereka di waktu itu) ketika berhadapan dengan mereka di medan peperangan (dalam keadaan mundur kecuali berbelok) mengelak (untuk siasat perang) dengan cara berpura-pura lari tetapi untuk tujuan menyerang (atau menggabungkan diri) menyatu (dengan pasukan yang lain) dengan pasukan kaum Muslimin lainnya meminta tolong kepada mereka (maka sesungguhnya orang itu kembali) pulang (dengan membawa kemurkaan dari Allah, dan tempatnya ialah neraka Jahanam. Dan amat buruklah tempat kembalinya) sejelek-jelek tempat kembali ialah neraka Jahanam. Keadaan ini khusus jika orang-orang kafir tidak makin bertambah lemah.",[["وَمَن","Dan sesiapa"],["يُوَلِّهِمْ","berpaling kepada mereka"],["يَوْمَئِذٍۢ","hari itu"],["دُبُرَهُۥٓ","belakangnya"],["إِلَّا","kecuali"],["مُتَحَرِّفًۭا","(sebagai) strategi"],["لِّقِتَالٍ","perang"],["أَوْ","atau"],["مُتَحَيِّزًا","(untuk) menyertai"],["إِلَىٰ","kepada"],["فِئَةٍۢ","satu kumpulan"],["فَقَدْ","sudah tentu"],["بَآءَ","(dia telah) ditanggung"],["بِغَضَبٍۢ","kemarahan"],["مِّنَ","daripada"],["ٱللَّهِ","Allah"],["وَمَأْوَىٰهُ","dan tempat tinggalnya"],["جَهَنَّمُ ۖ","(ialah) Neraka"],["وَبِئْسَ","seorang yang celaka"],["ٱلْمَصِيرُ","destinasi"]]],"1177":["(Maka yang sebenarnya bukan kamu yang membunuh mereka) di Badar dengan kekuatanmu (akan tetapi Allahlah yang membunuh mereka) dengan melalui pertolongan-Nya yang Dia limpahkan kepada kalian (dan bukan kamu yang melempar) mata kaum musyrikin, hai Muhammad (ketika kamu melempar) dengan batu kerikil, sebab sekali lempar dengan segenggam batu kerikil yang dilakukan oleh manusia tidak akan dapat memenuhi mata bala tentara yang begitu banyaknya (tetapi Allahlah yang melempar) dengan cara mengenakan lemparan itu kepada mereka; hal ini sengaja Dia lakukan guna mengalahkan orang-orang kafir (dan untuk memberi kemenangan kepada orang-orang mukmin dengan kemenangan) yakni anugerah (yang baik) yang dimaksud adalah ganimah/harta rampasan perang. (Sesungguhnya Allah Maha Mendengar) perkataan mereka (lagi Maha Mengetahui) tentang keadaan mereka.",[["فَلَمْ","Dan tidak"],["تَقْتُلُوهُمْ","kamu bunuh mereka"],["وَلَـٰكِنَّ","tetapi"],["ٱللَّهَ","Allah"],["قَتَلَهُمْ ۚ","membunuh mereka"],["وَمَا","Dan tidak"],["رَمَيْتَ","kamu melempar"],["إِذْ","apabila"],["رَمَيْتَ","kamu melempar"],["وَلَـٰكِنَّ","tetapi"],["ٱللَّهَ","Allah"],["رَمَىٰ ۚ","melemparkan"],["وَلِيُبْلِىَ","dan supaya Dia menguji"],["ٱلْمُؤْمِنِينَ","orang yang beriman"],["مِنْهُ","daripadaNya"],["بَلَآءً","(dengan) percubaan"],["حَسَنًا ۚ","kebaikan"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["سَمِيعٌ","(ialah) Maha Mendengar"],["عَلِيمٌۭ","Maha Mengetahui"]]],"1178":["(Itulah) kemenangan itu suatu hal yang nyata (dan sesungguhnya Allah melemahkan) membuat tidak berdaya (tipu daya orang-orang yang kafir).",[["ذَٰلِكُمْ","Begitulah (kesnya)"],["وَأَنَّ","dan bahawa"],["ٱللَّهَ","Allah (adalah)"],["مُوهِنُ","seorang yang menjadikan lemah"],["كَيْدِ","(the) rancangan"],["ٱلْكَـٰفِرِينَ","(dari) orang-orang kafir"]]],"1179":["(Jika kalian mencari keputusan) hai orang-orang kafir, yakni kamu sekalian meminta keputusan, di mana salah seorang dari kamu yaitu Abu Jahal mengatakan, \"Ya Allah! Siapakah dari kami yang paling memutuskan silaturahmi dan yang paling banyak melakukan hal-hal yang tidak dikenal pada kalangan kami, maka semoga Engkau membinasakannya (maka telah datang kepadamu keputusan) ketentuan binasanya orang-orang yang melakukan hal itu, mereka adalah Abu Jahal dan orang-orang yang terbunuh bersamanya, bukannya Nabi saw. dan kaum mukminin (dan jika kalian berhenti) dari perbuatan kafir dan memerangi Nabi saw. (maka itulah yang lebih baik bagi kalian; dan jika kalian kembali) untuk memerangi Nabi saw. (niscaya Kami kembali) untuk memberikan pertolongan kepada Nabi saw. atas kalian (dan tidak akan dapat mencukupi) menolak (angkatan perang kalian dari kalian) yakni golongan kalian (sesuatu bahaya pun biar pun angkatan perang itu banyak dan sesungguhnya Allah beserta orang-orang yang beriman) huruf inna dibaca kasrah sebagai jumlah isti`naf, dan dibaca anna dengan memperkirakan adanya huruf lam, bentuk lengkapnya ialah lama`al mu`miina.",[["إِن","Jika"],["تَسْتَفْتِحُوا۟","kamu meminta kemenangan"],["فَقَدْ","maka sudah tentu"],["جَآءَكُمُ","telah datang kepada kamu"],["ٱلْفَتْحُ ۖ","kemenangan itu"],["وَإِن","Dan jika"],["تَنتَهُوا۟","kamu berhenti"],["فَهُوَ","maka ia (adalah)"],["خَيْرٌۭ","kebaikan"],["لَّكُمْ ۖ","bagi kamu"],["وَإِن","tetapi jika"],["تَعُودُوا۟","kamu balik"],["نَعُدْ","Kami akan kembali (juga)"],["وَلَن","Dan tidak pernah"],["تُغْنِىَ","akan mendapat manfaat"],["عَنكُمْ","kamu"],["فِئَتُكُمْ","pasukan kamu"],["شَيْـًۭٔا","sesuatu"],["وَلَوْ","walaupun"],["كَثُرَتْ","(mereka) banyak"],["وَأَنَّ","Dan bahawa"],["ٱللَّهَ","Allah"],["مَعَ","(adalah) dengan"],["ٱلْمُؤْمِنِينَ","orang yang beriman"]]],"1180":["(Hai orang-orang yang beriman, taatlah kamu sekalian kepada Allah dan Rasul-Nya, dan janganlah kalian berpaling) memalingkan diri (daripada-Nya) dengan cara menentang perintah-Nya (sedang kalian mendengar) Alquran dan nasihat-nasihat-Nya.",[["يَـٰٓأَيُّهَا","Wahai"],["ٱلَّذِينَ","yang"],["ءَامَنُوٓا۟","beriman"],["أَطِيعُوا۟","Patuh"],["ٱللَّهَ","Allah"],["وَرَسُولَهُۥ","dan Rasul-Nya"],["وَلَا","Dan jangan"],["تَوَلَّوْا۟","berpaling"],["عَنْهُ","daripada dia"],["وَأَنتُمْ","sedangkan kamu"],["تَسْمَعُونَ","dengar"]]],"1181":["(Dan janganlah kalian menjadi sebagai orang-orang yang berkata, \"Kami mendengar; padahal mereka tidak mendengarkan) secara sadar dan penuh dengan pengertian, mereka adalah orang-orang munafik dan kaum musyrikin",[["وَلَا","Dan jangan"],["تَكُونُوا۟","jadilah"],["كَٱلَّذِينَ","seperti mereka yang"],["قَالُوا۟","berkata"],["سَمِعْنَا","Kami dengar"],["وَهُمْ","sedangkan mereka"],["لَا","jangan"],["يَسْمَعُونَ","dengar"]]],"1182":["(Sesungguhnya binatang, makhluk-makhluk yang seburuk-buruknya di sisi Allah ialah orang-orang yang tuli) tidak mau mendengarkan perkara yang hak (dan bisu) tidak mengucapkan perkara yang hak (yang tidak mengerti apa pun) tentang perkara yang hak.",[["۞ إِنَّ","Sesungguhnya"],["شَرَّ","paling teruk"],["ٱلدَّوَآبِّ","(dari) makhluk hidup"],["عِندَ","dekat"],["ٱللَّهِ","Allah"],["ٱلصُّمُّ","(adalah) orang pekak"],["ٱلْبُكْمُ","yang bisu"],["ٱلَّذِينَ","orang yang"],["لَا","jangan"],["يَعْقِلُونَ","menggunakan akal (mereka)."]]],"1183":["(Kalau sekiranya Allah mengetahui kebaikan pada mereka) bakat yang baik di dalam mendengarkan perkara yang hak (tentulah Allah menjadikan mereka dapat mendengar) dengan pendengaran yang disertai pemahaman. (Dan jika Allah menjadikan mereka dapat mendengar) sebagai perumpamaan, karena Allah telah mengetahui bahwa tidak ada kebaikan dalam diri mereka (niscaya mereka pasti berpaling juga) dari perkara yang hak itu (sedangkan mereka memalingkan diri\") dari menerima perkara hak yang mereka dengar itu karena keras hati dan ingkar.",[["وَلَوْ","Dan jika"],["عَلِمَ","(telah) tahu"],["ٱللَّهُ","Allah"],["فِيهِمْ","dalam diri mereka"],["خَيْرًۭا","apa-apa kebaikan"],["لَّأَسْمَعَهُمْ ۖ","sesungguhnya Dia (Allah) menjadikan mereka mendengar"],["وَلَوْ","Dan jika"],["أَسْمَعَهُمْ","Dia telah membuat mereka mendengar"],["لَتَوَلَّوا۟","nescaya mereka berpaling"],["وَّهُم","sedangkan mereka"],["مُّعْرِضُونَ","(ada) enggan"]]],"1184":["(Hai orang-orang yang beriman, penuhilah seruan Allah dan seruan Rasul) dengan taat (apabila Rasul menyeru kamu pada suatu yang memberi kehidupan kepada kalian) berupa perkara agama sebab perkara agama merupakan penyebab bagi kehidupan yang kekal (dan ketahuilah oleh kalian bahwa sesungguhnya Allah menghalangi antara manusia dan hatinya) maka ia tidak dapat beriman atau kafir melainkan berdasarkan kehendak Allah (dan sesungguhnya kepada-Nyalah kamu akan dikumpulkan) Allah akan membalas semua amal perbuatan kalian.",[["يَـٰٓأَيُّهَا","Wahai"],["ٱلَّذِينَ","yang"],["ءَامَنُوا۟","beriman"],["ٱسْتَجِيبُوا۟","Balas"],["لِلَّهِ","kepada Allah"],["وَلِلرَّسُولِ","dan Rasul-Nya"],["إِذَا","apabila"],["دَعَاكُمْ","dia panggil kamu"],["لِمَا","ke apa"],["يُحْيِيكُمْ ۖ","memberi kamu kehidupan"],["وَٱعْلَمُوٓا۟","Dan tahu"],["أَنَّ","bahawa"],["ٱللَّهَ","Allah"],["يَحُولُ","datang"],["بَيْنَ","(dalam) antara"],["ٱلْمَرْءِ","seorang lelaki"],["وَقَلْبِهِۦ","dan hatinya"],["وَأَنَّهُۥٓ","dan bahawa"],["إِلَيْهِ","kepada-Nya"],["تُحْشَرُونَ","kamu akan dikumpulkan"]]],"1185":["(Dan peliharalah diri kalian daripada siksaan) jika siksaan menimpa kalian (ia tidak khusus menimpa orang-orang yang lalim saja di antara kalian) bahkan siksaan itu merata kepada mereka dan selain mereka. Dan cara untuk memelihara diri supaya jangan tertimpa siksaan ialah membenci penyebabnya, yaitu perkara mungkar. (Dan ketahuilah bahwa Allah sangat keras siksaan-Nya) terhadap orang-orang yang melanggar perintah dan larangan-Nya.",[["وَٱتَّقُوا۟","Dan ketakutan"],["فِتْنَةًۭ","perbicaraan"],["لَّا","tidak"],["تُصِيبَنَّ","yang akan menyusahkan"],["ٱلَّذِينَ","orang yang"],["ظَلَمُوا۟","buat salah"],["مِنكُمْ","antara kamu"],["خَآصَّةًۭ ۖ","secara eksklusif"],["وَٱعْلَمُوٓا۟","Dan tahu"],["أَنَّ","bahawa"],["ٱللَّهَ","Allah"],["شَدِيدُ","(adalah) teruk"],["ٱلْعِقَابِ","(dalam) penalti"]]],"1186":["(Dan ingatlah hai para Muhajirin ketika kalian masih berjumlah sedikit lagi tertindas di muka bumi) yakni Mekah (kalian takut orang-orang Mekah akan menculik kalian) mengambil kalian dengan cepat (maka Allah memberi kalian tempat menetap) yaitu kota Madinah (dan didukung-Nya kalian) Dia membuat kalian menjadi kuat (dengan pertolongan-Nya) ketika perang Badar, yaitu melalui bantuan para malaikat (dan diberi-Nya kalian rezeki dari yang baik-baik) berupa ganimah (agar kalian bersyukur) terhadap nikmat-nikmat-Nya. Ayat ini diturunkan berkenaan dengan Abu Lubabah alias Marwan bin Abdul Munzir. Nabi saw. telah mengutusnya kepada orang-orang Bani Quraizhah dengan membawa pesan darinya, supaya mereka mau tunduk di bawah kekuasaan Nabi saw. Maka Abu Lubabah bermusyawarah dengan mereka; akan tetapi ia mengisyaratkan dengan tangannya kepada mereka, bahwa jika mereka tunduk maka hukumannya adalah sembelih (maut). Abu Lubabah sengaja berbuat demikian demi untuk melindungi anak-anak dan harta bendanya yang berada di antara mereka.",[["وَٱذْكُرُوٓا۟","Dan ingat"],["إِذْ","apabila"],["أَنتُمْ","kamu"],["قَلِيلٌۭ","(adalah) sedikit"],["مُّسْتَضْعَفُونَ","(dan) dianggap lemah"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["تَخَافُونَ","takut"],["أَن","bahawa"],["يَتَخَطَّفَكُمُ","mungkin menghapuskan kamu"],["ٱلنَّاسُ","kaum lelaki"],["فَـَٔاوَىٰكُمْ","lalu Dia menaungi kamu"],["وَأَيَّدَكُم","dan menguatkan kamu"],["بِنَصْرِهِۦ","dengan pertolonganNya"],["وَرَزَقَكُم","dan menyediakan kamu"],["مِّنَ","daripada"],["ٱلطَّيِّبَـٰتِ","perkara yang baik"],["لَعَلَّكُمْ","supaya kamu"],["تَشْكُرُونَ","(bersyukur)"]]],"1187":["(Hai orang-orang yang beriman janganlah kalian mengkhianati Allah dan rasul-Nya dan) jangan pula (kalian mengkhianati amanat-amanat kalian) yakni apa-apa yang dipercayakan kepada kalian berupa agama dan hal-hal yang lain (sedangkan kalian mengetahui).",[["يَـٰٓأَيُّهَا","Wahai"],["ٱلَّذِينَ","yang"],["ءَامَنُوا۟","beriman"],["لَا","Jangan"],["تَخُونُوا۟","mengkhianati"],["ٱللَّهَ","Allah"],["وَٱلرَّسُولَ","dan Rasul"],["وَتَخُونُوٓا۟","atau mengkhianati"],["أَمَـٰنَـٰتِكُمْ","amanah kamu"],["وَأَنتُمْ","sedangkan kamu"],["تَعْلَمُونَ","mengetahui"]]],"1188":["(Dan ketahuilah bahwa harta kalian dan anak-anak kalian itu hanyalah sebagai cobaan) buat kalian yang menghambat kalian daripada perkara-perkara akhirat (dan sesungguhnya di sisi Allahlah pahala yang besar) maka janganlah sekali-kali kalian melewatkan pahala yang besar sehingga kalian mau berbuat khianat demi untuk mereka. Ayat berikut diturunkan berkenaan dengan tobatnya Abu Lubabah.",[["وَٱعْلَمُوٓا۟","Dan tahu"],["أَنَّمَآ","bahawa"],["أَمْوَٰلُكُمْ","kekayaan kamu"],["وَأَوْلَـٰدُكُمْ","dan anak-anak kamu"],["فِتْنَةٌۭ","(adalah) percubaan"],["وَأَنَّ","Dan bahawa"],["ٱللَّهَ","Allah"],["عِندَهُۥٓ","dengan Dia"],["أَجْرٌ","(adalah) ganjaran"],["عَظِيمٌۭ","yang besar"]]],"1189":["(Hai orang-orang yang beriman, jika kalian bertakwa kepada Allah) melalui berserah diri kepada-Nya dan cara-cara yang lain (niscaya Dia akan memberikan kepada kalian petunjuk) buat kalian sehingga kalian dapat membedakan hal-hal yang dapat membawa keselamatan dan hal-hal yang membahayakan diri kalian, sehingga kalian selamat dari hal-hal yang kalian takutkan (dan menghapuskan segala kesalahan-kesalahan dan mengampuni kalian) dosa-dosa kalian. (Dan Allah mempunyai karunia yang besar).",[["يَـٰٓأَيُّهَا","Wahai"],["ٱلَّذِينَ","yang"],["ءَامَنُوٓا۟","beriman"],["إِن","Jika"],["تَتَّقُوا۟","kamu takut"],["ٱللَّهَ","Allah"],["يَجْعَل","Dia akan mengabulkan"],["لَّكُمْ","kamu"],["فُرْقَانًۭا","satu kriteria"],["وَيُكَفِّرْ","dan akan mengeluarkan"],["عَنكُمْ","daripada kamu"],["سَيِّـَٔاتِكُمْ","perbuatan jahat kamu"],["وَيَغْفِرْ","dan memaafkan"],["لَكُمْ ۗ","kamu"],["وَٱللَّهُ","Dan Allah"],["ذُو","(ialah) Pemilik"],["ٱلْفَضْلِ","(dari) Bounty"],["ٱلْعَظِيمِ","yang Agung"]]],"1190":["(Dan) ingatlah hai Muhammad (ketika orang-orang kafir Quraisy merencanakan tipu muslihat terhadap dirimu) mereka mengadakan pertemuan di Darun Nadwah tempat mereka bermusyawarah guna mengadakan makar terhadap dirimu (untuk menangkapmu) untuk mengikatmu dan memenjarakanmu (atau membunuhmu) di mana mereka secara beramai-ramai membunuhmu (atau mengusirmu) dari Kota Mekah. (Mereka merencanakan tipu muslihat) terhadap dirimu (akan tetapi Allah menggagalkan rencana mereka dengan cara memberikan pemberitahuan kepadamu melalui wahyu-Nya akan rencana mereka dan Dia memerintahkan kamu untuk keluar terlebih dahulu. (Dan Allah sebaik-baik pembalas tipu muslihat). Dia Maha Mengetahui tentang tipu muslihat.",[["وَإِذْ","Dan apabila"],["يَمْكُرُ","diplot"],["بِكَ","terhadap kamu"],["ٱلَّذِينَ","orang yang"],["كَفَرُوا۟","kufur"],["لِيُثْبِتُوكَ","bahawa mereka menghalang kamu"],["أَوْ","atau"],["يَقْتُلُوكَ","membunuh kamu"],["أَوْ","atau"],["يُخْرِجُوكَ ۚ","menghalau kamu keluar"],["وَيَمْكُرُونَ","Dan mereka merancang"],["وَيَمْكُرُ","dan (juga) sedang merancang"],["ٱللَّهُ ۖ","Allah"],["وَٱللَّهُ","Dan Allah"],["خَيْرُ","adalah (yang) Terbaik"],["ٱلْمَـٰكِرِينَ","(dari) Perancang"]]],"1191":["(Dan apabila dibacakan kepada mereka ayat-ayat Kami) yakni Alquran (mereka berkata, \"Sesungguhnya kami telah mendengar ayat-ayat seperti ini, kalau kami menghendaki niscaya kami dapat membacakan yang seperti ini) ucapan ini telah dikatakan oleh Nadhr bin Harits, karena ia sering berkunjung ke negeri Hairah untuk tujuan berniaga. Di sana ia membeli buku-buku tentang sejarah orang-orang Ajam, kemudian ia menceritakannya kepada penduduk kota Mekah. (Tiada lain) tak lain (hal ini) yakni Alquran (hanyalah dongeng-dongengan) cerita-cerita bohong (orang-orang dahulu.\")",[["وَإِذَا","Dan apabila"],["تُتْلَىٰ","dibacakan"],["عَلَيْهِمْ","kepada mereka"],["ءَايَـٰتُنَا","Ayat Kami"],["قَالُوا۟","mereka berkata"],["قَدْ","Sesungguhnya"],["سَمِعْنَا","kita pernah dengar"],["لَوْ","jika"],["نَشَآءُ","kami mahu"],["لَقُلْنَا","pasti, kita boleh katakan"],["مِثْلَ","suka"],["هَـٰذَآ ۙ","ini"],["إِنْ","Tidak"],["هَـٰذَآ","adakah ini"],["إِلَّآ","tetapi"],["أَسَـٰطِيرُ","cerita-cerita"],["ٱلْأَوَّلِينَ","(dari) orang-orang dahulu"]]],"1192":["(Dan ingatlah ketika mereka/orang-orang musyrik berkata, \"Ya Allah! Jika betul hal ini) yaitu Alquran yang dibacakan oleh Muhammad (dialah yang benar) diturunkan (dari sisi Engkau, maka hujanilah kami dengan batu dari langit, atau datangkanlah kepada kami azab yang pedih.\") siksaan yang menyakitkan sekali sebagai pembalasan atas ingkar kami terhadapnya. Perkataan ini diucapkan oleh Nadhr dan lain-lainnya sebagai penghinaan dengan maksud untuk memberikan gambaran kepada orang lain seakan-akan ia benar-benar mengetahui akan kebatilan Alquran. Allah swt. telah berfirman:",[["وَإِذْ","Dan apabila"],["قَالُوا۟","mereka berkata"],["ٱللَّهُمَّ","Ya Allah"],["إِن","Jika"],["كَانَ","adalah"],["هَـٰذَا","ini"],["هُوَ","[ia]"],["ٱلْحَقَّ","kebenaran"],["مِنْ","[daripada]"],["عِندِكَ","daripada Engkau"],["فَأَمْطِرْ","kemudian (menghantar) hujan"],["عَلَيْنَا","atas kita"],["حِجَارَةًۭ","(dari) batu"],["مِّنَ","daripada"],["ٱلسَّمَآءِ","langit"],["أَوِ","atau"],["ٱئْتِنَا","bawa (ke atas) kami"],["بِعَذَابٍ","azab"],["أَلِيمٍۢ","yang pedih"]]],"1193":["(Dan Allah sekali-kali tidak akan mengazab mereka) oleh sebab apa yang telah mereka minta (sedangkan kamu berada di antara mereka) karena jika azab itu turun akan menimpa semua orang tanpa kecuali. Dan tiada suatu umat pun yang diazab melainkan setelah nabi dan kaum mukminin keluar daripadanya. (Dan tidak pula Allah akan mengazab mereka, sedangkan mereka meminta ampun) karena ternyata di dalam tawaf yang mereka lakukan mereka selalu mengatakan, \"Ampunan-Mu, ampunan-Mu.\" Dan menurut suatu pendapat dikatakan bahwa orang-orang yang meminta ampunan itu adalah orang-orang lemah dari kalangan kaum mukminin yang tinggal bersama dengan orang-orang kafir sebagaimana yang telah dijelaskan oleh firman-Nya, \"Sekiranya mereka tidak bercampur-baur, tentulah Kami akan mengazab orang-orang kafir di antara mereka dengan azab yang pedih.\" (Q.S. Al-Fath 25).",[["وَمَا","Tetapi tidak"],["كَانَ","ialah"],["ٱللَّهُ","(untuk) Allah"],["لِيُعَذِّبَهُمْ","bahawa Dia menghukum mereka"],["وَأَنتَ","sedangkan kamu"],["فِيهِمْ ۚ","(adalah) di antara mereka"],["وَمَا","dan bukan"],["كَانَ","ialah"],["ٱللَّهُ","Allah"],["مُعَذِّبَهُمْ","yang menghukum mereka"],["وَهُمْ","sedangkan mereka"],["يَسْتَغْفِرُونَ","minta ampun"]]],"1194":["(Mengapa Allah tidak mengazab mereka) dengan pedang sesudah engkau dan kaum mukminin yang lemah keluar dari Mekah. Berdasarkan pendapat yang pertama, ayat ini menasakh ayat sebelumnya; dan ternyata Allah swt. mengazab mereka dalam perang Badar dan perang-perang yang lain (padahal mereka menghalangi) mencegah Nabi saw. dan kaum muslimin (untuk mendatangi Masjidilharam) yakni untuk melakukan tawaf di dalamnya (dan mereka bukanlah orang-orang yang berhak menguasainya?) seperti menurut dugaan mereka. (Tiada lain) tidak lain (orang-orang yang berhak menguasainya hanyalah orang-orang yang bertakwa tetapi kebanyakan mereka tidak mengetahui) bahwasanya tidak ada hak bagi orang-orang kafir untuk menguasai Masjidilharam.",[["وَمَا","Tetapi apa"],["لَهُمْ","(adalah) untuk mereka"],["أَلَّا","itu tidak"],["يُعَذِّبَهُمُ","(hendaklah) menghukum mereka"],["ٱللَّهُ","Allah"],["وَهُمْ","sedangkan mereka"],["يَصُدُّونَ","menghalang (orang)"],["عَنِ","daripada"],["ٱلْمَسْجِدِ","Al-Masjid"],["ٱلْحَرَامِ","Al-Haraam"],["وَمَا","manakala tidak"],["كَانُوٓا۟","mereka adalah"],["أَوْلِيَآءَهُۥٓ ۚ","penjaganya"],["إِنْ","Tidak (boleh)"],["أَوْلِيَآؤُهُۥٓ","penjaganya"],["إِلَّا","kecuali"],["ٱلْمُتَّقُونَ","orang yang takut kepada Allah"],["وَلَـٰكِنَّ","tetapi"],["أَكْثَرَهُمْ","kebanyakan mereka"],["لَا","jangan"],["يَعْلَمُونَ","mengetahui"]]],"1195":["(Salat mereka di sekitar Baitullah itu tiada lain hanyalah siulan) bersiul-siul (dan tepuk tangan) artinya mereka menjadikan hal-hal tersebut sebagai upacara sembahyang mereka yang dianjurkan oleh sesama mereka. (Maka rasakanlah azab) dalam perang Badar (disebabkan kekafiran kalian).",[["وَمَا","Dan tidak"],["كَانَ","adalah"],["صَلَاتُهُمْ","doa mereka"],["عِندَ","di"],["ٱلْبَيْتِ","Dewan"],["إِلَّا","kecuali"],["مُكَآءًۭ","bersiul"],["وَتَصْدِيَةًۭ ۚ","dan bertepuk tangan"],["فَذُوقُوا۟","Jadi rasa"],["ٱلْعَذَابَ","azab"],["بِمَا","kerana"],["كُنتُمْ","kamu pernah"],["تَكْفُرُونَ","kufur"]]],"1196":["Sesungguhnya orang-orang yang kafir itu menafkahkan harta mereka) di dalam memerangi Nabi saw. (untuk menghalangi orang dari jalan Allah. Mereka akan menafkahkan harta itu kemudian hal itu) pada akhirnya (menjadi sesalan bagi mereka sendiri) mereka akan merasa menyesal karena harta mereka terbuang secara percuma dan tujuan mereka tidak berhasil (kemudian mereka dikalahkan) di dunia. (Dan orang-orang yang kafir itu) dari kalangan orang-orang Quraisy (ke neraka Jahanam) kelak di akhirat (akan dikumpulkan) mereka digiring ke dalamnya.",[["إِنَّ","Sesungguhnya"],["ٱلَّذِينَ","orang yang"],["كَفَرُوا۟","kufur"],["يُنفِقُونَ","mereka nafkahkan"],["أَمْوَٰلَهُمْ","kekayaan mereka"],["لِيَصُدُّوا۟","menghalang (orang)"],["عَن","daripada"],["سَبِيلِ","jalan"],["ٱللَّهِ ۚ","(milik) Allah"],["فَسَيُنفِقُونَهَا","Jadi mereka akan menghabiskannya"],["ثُمَّ","kemudian"],["تَكُونُ","ia akan menjadi"],["عَلَيْهِمْ","bagi mereka"],["حَسْرَةًۭ","satu penyesalan"],["ثُمَّ","kemudian"],["يُغْلَبُونَ ۗ","mereka akan diatasi"],["وَٱلَّذِينَ","Dan orang yang"],["كَفَرُوٓا۟","kufur"],["إِلَىٰ","kepada"],["جَهَنَّمَ","Neraka"],["يُحْشَرُونَ","mereka akan dikumpulkan"]]],"1197":["(Supaya Allah membedakan) lafal ini berkaitan dengan lafal takuunu pada ayat yang sebelumnya. Boleh dibaca tidak memakai tasydid atau memakainya; artinya memisahkan (antara golongan yang buruk) orang kafir (dan yang baik) orang mukmin (dan menjadikan golongan yang buruk itu sebagiannya di atas sebagian yang lain, kesemuanya ditumpukkan-Nya) artinya Allah mengumpulkan mereka secara bertumpuk-tumpuk, sebagian di antara mereka berada di atas sebagian yang lain (dan dimasukkan-Nya ke dalam neraka Jahanam. Mereka itulah orang-orang yang merugi).",[["لِيَمِيزَ","Itu boleh membezakan"],["ٱللَّهُ","Allah"],["ٱلْخَبِيثَ","orang jahat"],["مِنَ","daripada"],["ٱلطَّيِّبِ","yang baik"],["وَيَجْعَلَ","dan tempat"],["ٱلْخَبِيثَ","orang jahat"],["بَعْضَهُۥ","sebahagian mereka"],["عَلَىٰ","pada"],["بَعْضٍۢ","yang lain"],["فَيَرْكُمَهُۥ","dan timbunkan mereka"],["جَمِيعًۭا","semua bersama"],["فَيَجْعَلَهُۥ","dan letakkan mereka"],["فِى","dalam"],["جَهَنَّمَ ۚ","Neraka"],["أُو۟لَـٰٓئِكَ","Itu"],["هُمُ","mereka"],["ٱلْخَـٰسِرُونَ","(adalah) orang-orang yang rugi"]]],"1198":["(Katakanlah kepada orang-orang yang kafir itu,) seperti Abu Sofyan dan teman-temannya (\"Jika mereka berhenti) dari kekafirannya dan dari memerangi Nabi saw. (niscaya Allah akan mengampuni mereka tentang dosa-dosa mereka yang telah lalu) dari amal perbuatan mereka (dan jika mereka kembali lagi) untuk memerangi Nabi saw. (sesungguhnya akan berlaku terhadap mereka sunah Allah terhadap orang-orang dahulu.\") Allah akan memberlakukan sunah-Nya terhadap diri mereka, dengan cara membinasakannya, seperti yang telah Kami lakukan terhadap umat-umat terdahulu.",[["قُل","Katakanlah"],["لِّلَّذِينَ","kepada mereka yang"],["كَفَرُوٓا۟","kufur"],["إِن","jika"],["يَنتَهُوا۟","mereka berhenti"],["يُغْفَرْ","akan diampuni"],["لَهُم","bagi mereka"],["مَّا","apa"],["قَدْ","[sesungguhnya]"],["سَلَفَ","(sudah) lalu"],["وَإِن","Tetapi jika"],["يَعُودُوا۟","mereka balik"],["فَقَدْ","maka sesungguhnya"],["مَضَتْ","didahulukan"],["سُنَّتُ","(the) amalan"],["ٱلْأَوَّلِينَ","(dari) orang-orang dahulu"]]],"1199":["(Dan perangilah mereka supaya tidak ada) supaya jangan ada (fitnah) kemusyrikan (dan supaya agama itu semata-mata bagi Allah) hanya bagi Allah semata dan tidak disembah selain dari-Nya. (Jika mereka berhenti) dari kekafiran (Maka sesungguhnya Allah Maha Melihat apa yang mereka kerjakan) Dia akan membalas mereka karenanya.",[["وَقَـٰتِلُوهُمْ","Dan lawan mereka"],["حَتَّىٰ","sehingga"],["لَا","tidak"],["تَكُونَ","ada"],["فِتْنَةٌۭ","penindasan"],["وَيَكُونَ","dan adalah"],["ٱلدِّينُ","agama itu"],["كُلُّهُۥ","semua itu"],["لِلَّهِ ۚ","kerana Allah"],["فَإِنِ","Tetapi jika"],["ٱنتَهَوْا۟","mereka berhenti"],["فَإِنَّ","maka sesungguhnya"],["ٱللَّهَ","Allah"],["بِمَا","tentang apa"],["يَعْمَلُونَ","mereka lakukan"],["بَصِيرٌۭ","(ialah) Maha Melihat"]]],"1200":["(Dan jika mereka berpaling) dari keimanan (maka ketahuilah bahwasanya Allah pelindung kalian) yang akan menolong dan mengatur urusan-urusan kalian (sebaik-baik pelindung) adalah Dia (dan Dia adalah sebaik-baik penolong) yang akan menolong kalian.",[["وَإِن","Dan jika"],["تَوَلَّوْا۟","mereka berpaling"],["فَٱعْلَمُوٓا۟","maka ketahuilah"],["أَنَّ","bahawa"],["ٱللَّهَ","Allah"],["مَوْلَىٰكُمْ ۚ","(ialah) Pelindungmu"],["نِعْمَ","Cemerlang"],["ٱلْمَوْلَىٰ","(ialah) Pelindung"],["وَنِعْمَ","dan Cemerlang"],["ٱلنَّصِيرُ","(ialah) Penolong"]]]});